// Magic numbers para validação de imagens
const IMAGE_MAGIC_NUMBERS = {
  jpg: [0xff, 0xd8, 0xff],
  jpeg: [0xff, 0xd8, 0xff],
  png: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
  webp: [0x52, 0x49, 0x46, 0x46],
};

// Função para validar magic number de imagem
function validateImageMagicNumber(buffer: Buffer): boolean {
  for (const [format, signature] of Object.entries(IMAGE_MAGIC_NUMBERS)) {
    if (signature.every((byte, index) => buffer[index] === byte)) {
      return true;
    }
  }
  return false;
}

// Middleware para verificar autenticação obrigatória
async function requireAuth(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    // 🔒 PRIORIDADE 1: Validar sessão de coordenador (se existir)
    const session = req.session as any;
    if (session?.isCoordinator && session?.coordenadorId) {
      console.log(
        `✅ [AUTH SESSION] Coordenador autenticado: ${session.userName} (coordId=${session.coordenadorId})`
      );

      // Buscar dados atualizados do coordenador
      const coordenador = await db
        .select()
        .from(coordenadores)
        .where(eq(coordenadores.id, session.coordenadorId))
        .limit(1);

      if (coordenador && coordenador.length > 0) {
        (req as any).coordenador = coordenador[0];
       (req as any).user = {
          id: session.coordenadorId, // ✅ aqui!
          papel: session.userPapel, 
          email: session.userEmail,
          nome: session.userName,
          role: session.userPapel,
        };
        return next();
      }
    }

    // Verificar se é modo dev por vários critérios
    const devAccessQuery = req.query.dev_access === "true";
    const devAccessHeader = req.headers["x-dev-access"] === "true";
    const devReferer =
      req.headers.referer?.includes("dev_access=true") ||
      req.headers.referer?.includes("/dev");
    const isDevMode =
      isDevRequest(req) || devAccessQuery || devAccessHeader || devReferer;

    // Permitir acesso em modo dev sem autenticação
    if (isDevMode) {
      (req as any).user = { id: 1, nome: 'Dev User', papel: 'dev' };
      (req as any).isDeveloper = true;
      return next();
    }

   const userId = req.headers["x-user-id"];

    
  if (!userId) {
    return res.status(401).json({
      error: "Autenticação obrigatória - cabeçalho x-user-id necessário",
    });
  }

     
    const userIdNum = parseInt(String(userId), 10);
      if (isNaN(userIdNum)) {
        return res.status(401).json({ error: "ID de usuário inválido" });
    }

    // Tentar buscar como usuário primeiro
    let user = await storage.getUser(userIdNum);

    // Se não encontrar como usuário, tentar buscar como coordenador
    if (!user) {
      const coordenador = await db
        .select()
        .from(coordenadores)
        .where(eq(coordenadores.id, userIdNum))
        .limit(1);

      if (coordenador && coordenador.length > 0) {
        (req as any).coordenador = coordenador[0];
        (req as any).user = { id: userIdNum };
        console.log(
          "🔐 [AUTH] Coordenador autenticado via header:",
          coordenador[0].nome
        );
        return next();
      }

      return res.status(401).json({ error: "Usuário não encontrado" });
    }

    (req as any).user = user;
    next();
  } catch (error) {
    console.error("Erro no middleware de autenticação:", error);
    res.status(500).json({ error: "Erro interno do servidor" });
  }
}

// Middleware para verificar autenticação de desenvolvedor
async function requireDevAuth(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    console.log("[requireDevAuth] Session data:", {
      hasSession: !!req.session,
      developerId: req.session?.developerId,
      userPapel: req.session?.userPapel,
      sessionID: req.sessionID,
    });

    const developerId = req.session?.developerId;
    const userPapel = req.session?.userPapel;

    if (
      !developerId ||
      (userPapel !== "dev" && userPapel !== "desenvolvedor")
    ) {
      console.log("[requireDevAuth] Auth failed - missing session data");
      return res
        .status(401)
        .json({ error: "Acesso negado - sessão de desenvolvedor requerida" });
    }

    // Anexar info do desenvolvedor ao request
    (req as any).developerId = developerId;
    console.log("[requireDevAuth] Auth successful for developer:", developerId);
    return next();
  } catch (error) {
    console.error("[requireDevAuth] Error:", error);
    return res.status(500).json({ error: "Erro ao verificar autenticação" });
  }
}

// Middleware para verificar se usuário é admin
function requireAdmin(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  const user = (req as any).user;
  if (!user) {
    return res.status(401).json({ error: "Usuário não autenticado" });
  }

  const isAdmin =
    isAdminEmail(user.email) || user.role === "admin" || user.tipo === "admin";
  if (!isAdmin) {
    console.warn(
      `🚨 [SECURITY] Tentativa de acesso admin negada - Usuário ${user.id} (${user.email})`
    );
    return res.status(403).json({
      error: "Acesso negado - privilégios administrativos necessários",
    });
  }

  console.log(`✅ [ADMIN ACCESS] Admin ${user.id} (${user.email}) autorizado`);
  next();
}

// ================ RBAC MIDDLEWARE SYSTEM ================
// Middleware para verificação de papéis específicos RBAC
function requireRole(allowedRoles: string[]) {
  return (
    req: express.Request,
    res: express.Response,
    next: express.NextFunction
  ) => {
    const user = (req as any).user;
    if (!user) {
      return res.status(401).json({ error: "Usuário não autenticado" });
    }

    // Obter papel do usuário (compatibilidade com campos existentes)
    const userRole = user.papel || user.userPapel || user.tipo || user.role;

    // PERMITIR ACESSO EM DEV MODE (bypass RBAC)
    if (userRole === "dev") {
      console.log(
        `✅ [DEV MODE] Usuário ${user.id} acessando com papel "dev" (RBAC bypass)`
      );
      next();
      return;
    }

    // Verificar se o papel do usuário está na lista de papéis permitidos
    if (!userRole || !allowedRoles.includes(userRole)) {
      console.warn(
        `🚨 [RBAC] Acesso negado - Usuário ${user.id} (${
          user.email
        }) papel "${userRole}" não autorizado. Papéis permitidos: ${allowedRoles.join(
          ", "
        )}`
      );
      return res.status(403).json({
        error: "Acesso negado - papel insuficiente",
        details: `Papel "${userRole}" não autorizado para este recurso`,
      });
    }

    console.log(`✅ [RBAC] Usuário ${user.id} papel "${userRole}" autorizado`);
    next();
  };
}

// Helper para verificar acesso a recursos próprios com bypass dev mode
function ensureSelfAccess(
  user: any,
  targetId: number,
  resourceName: string = "recurso"
): { allowed: boolean; error?: any } {
  const userRole = user.papel || user.userPapel || user.tipo || user.role;
  if (userRole === "dev") {
    return { allowed: true };
  }

  if (user.id !== targetId) {
    console.warn(
      `🚨 [SECURITY] User ${user.id} tentou acessar ${resourceName} de user ${targetId}`
    );
    return {
      allowed: false,
      error: {
        status: 403,
        message: `Acesso negado - você só pode acessar seu próprio ${resourceName}`,
      },
    };
  }

  return { allowed: true };
}

