  // Create subscription for internal checkout
  app.post("/api/create-subscription", async (req, res) => {
    try {
      const { planId, customAmount, paymentMethodId, periodicity, price } =
        req.body;

      // 🔒 SECURITY: Derive userId from authenticated session, not client input
      const authenticatedUserId =
        (req as any).session?.user?.id || (req as any).user?.id;

      // 🛡️ SECURITY: Require authentication to create subscription
      if (!authenticatedUserId) {
        console.error(
          "🚨 [SECURITY] Unauthenticated subscription attempt blocked"
        );
        return res
          .status(401)
          .json({ error: "Autenticação necessária para criar assinatura" });
      }

      // Critical validation to prevent incorrect charging
      if (!planId) {
        console.error(
          "❌ [SUBSCRIPTION ERROR] Missing planId - this could cause incorrect charging!"
        );
        return res.status(400).json({ error: "PlanId é obrigatório" });
      }

      // Validate planId against known plans
      const validPlans = ["eco", "voz", "grito", "platinum", "diamante"];
      if (!validPlans.includes(planId.toLowerCase()) && planId !== "platinum") {
        console.error(
          "❌ [SUBSCRIPTION ERROR] Invalid planId:",
          planId,
          "Valid plans:",
          validPlans
        );
        return res.status(400).json({ error: `Plano inválido: ${planId}` });
      }

      // Create or retrieve customer using centralized function (prevents duplicates)
      const customerId = await getOrCreateStripeCustomer(authenticatedUserId);

      // Attach payment method safely (prevents duplicates)
      if (paymentMethodId) {
        const { paymentMethodId: finalPmId } = await attachPaymentMethodSafely(
          paymentMethodId,
          customerId
        );

        // Set as default payment method
        await stripe.customers.update(customerId, {
          invoice_settings: {
            default_payment_method: finalPmId,
          },
        });
      }

      let productName: string;
      let productDescription: string;
      let unitAmount: number;
      let intervalConfig: { interval: string; interval_count?: number } = {
        interval: "month",
      };

      if (planId === "platinum" && customAmount) {
        // Plano flexível - Platinum personalizado
        productName = "Platinum Personalizado";
        productDescription = "Valor personalizado escolhido pelo usuário";
        unitAmount = Math.round(customAmount * 100); // Converte para centavos
        console.log(
          "💰 [SUBSCRIPTION] Platinum custom plan:",
          unitAmount,
          "cents"
        );
      } else if (price && periodicity) {
        // NOVO: Usar preço e periodicidade específicos do frontend
        const plan = planPricing[planId as keyof typeof planPricing];
        if (!plan) {
          console.error(
            "❌ [SUBSCRIPTION ERROR] Plan not found in planPricing:",
            planId,
            "Available plans:",
            Object.keys(planPricing)
          );
          return res
            .status(400)
            .json({ error: `Plano não encontrado: ${planId}` });
        }

        productName = plan.name;
        productDescription = plan.description;
        unitAmount = Math.round(price * 100); // Frontend já enviou o preço correto

        // Configurar intervalo baseado na periodicidade
        switch (periodicity) {
          case "mensal":
            intervalConfig = { interval: "month" };
            break;
          case "trimestral":
            intervalConfig = { interval: "month", interval_count: 3 };
            break;
          case "semestral":
            intervalConfig = { interval: "month", interval_count: 6 };
            break;
          case "anual":
            intervalConfig = { interval: "month", interval_count: 12 };
            break;
          default:
            console.log(
              "⚠️ [SUBSCRIPTION] Periodicidade desconhecida, usando mensal:",
              periodicity
            );
            intervalConfig = { interval: "month" };
        }

        console.log(
          "💰 [SUBSCRIPTION] Plan with periodicity:",
          planId,
          periodicity,
          "price:",
          unitAmount,
          "cents (R$",
          (unitAmount / 100).toFixed(2),
          ")"
        );
      } else if (planPricing[planId as keyof typeof planPricing]) {
        // Fallback: Planos fixos usando apenas plano mensal (compatibilidade)
        const plan = planPricing[planId as keyof typeof planPricing];
        productName = plan.name;
        productDescription = plan.description;
        unitAmount = plan.price; // Já em centavos
        console.log(
          "💰 [SUBSCRIPTION] Fixed plan selected (mensal fallback):",
          planId,
          "price:",
          unitAmount,
          "cents (R$",
          (unitAmount / 100).toFixed(2),
          ")"
        );
      } else {
        console.error(
          "❌ [SUBSCRIPTION ERROR] Plan not found in planPricing:",
          planId,
          "Available plans:",
          Object.keys(planPricing)
        );
        return res
          .status(400)
          .json({ error: `Plano não encontrado: ${planId}` });
      }

      // Create product first
      const product = await stripe.products.create({
        name: productName,
        description: productDescription,
      });

      // Create price for the product with correct interval
      const stripePrice = await stripe.prices.create({
        product: product.id,
        currency: "brl",
        unit_amount: unitAmount,
        recurring: intervalConfig,
      });

      // === CRIAR PAYMENTINTENT PARA PRIMEIRO PAGAMENTO ===
      // Criar PaymentIntent direto (webhook cria subscription depois)
      const paymentIntent = await stripe.paymentIntents.create({
        amount: unitAmount,
        currency: "brl",
        customer: customerId,
        payment_method_types: ["card"],
        setup_future_usage: "off_session",
        metadata: {
          planId: planId,
          authenticatedUserId: String(authenticatedUserId || ""),
          isRecurring: "true",
          priceId: stripePrice.id,
        },
      });

      console.log("✅ PAYMENTINTENT criado para subscription:", {
        paymentIntentId: paymentIntent.id,
        amount: unitAmount / 100,
        customer: customerId,
      });

      // CRITICAL: Create donor record immediately
      try {
        await db.insert(doadores).values({
          userId: authenticatedUserId || null,
          plano: planId,
          valor: (unitAmount / 100).toString(),
          stripePaymentIntentId: paymentIntent.id,
          status: "pending",
          dataDoacaoInicial: new Date(),
          ativo: true,
        });
        console.log(
          "✅ [SUBSCRIPTION] Donor record created for PaymentIntent:",
          paymentIntent.id
        );
      } catch (dbError: any) {
        console.error(
          "❌ [SUBSCRIPTION] Failed to create donor record:",
          dbError
        );
      }

      res.json({
        customerId: customer.id,
        clientSecret: paymentIntent.client_secret,
        paymentIntentId: paymentIntent.id,
        requiresAction: paymentIntent.status === "requires_action",
      });
    } catch (error: any) {
      console.error("Error creating subscription:", error);
      res.status(500).json({ error: "Erro ao criar subscription" });
    }
  });

  // 🔒 WEBHOOK SEGURO - Verificação de assinatura obrigatória

 app.post("/api/webhook/stripe", async (req, res) => {
  const sig = req.headers["stripe-signature"];
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;

  if (!endpointSecret) {
    console.error("🚨 WEBHOOK ERROR: STRIPE_WEBHOOK_SECRET não configurado");
    return res.status(500).json({ error: "Webhook endpoint secret not configured" });
  }

  if (!sig) {
    console.error("🚨 WEBHOOK ERROR: Assinatura não fornecida");
    return res.status(400).json({ error: "Missing stripe signature" });
  }

  let event: Stripe.Event;

  // ✅ 1) Verificar assinatura (obrigatório)
  try {
    const rawBody = Buffer.isBuffer(req.body)
      ? req.body
      : Buffer.from(
          typeof req.body === "string" ? req.body : JSON.stringify(req.body),
          "utf8"
        );

    event = stripe.webhooks.constructEvent(rawBody, sig as string, endpointSecret);
    console.log(`✅ [WEBHOOK SECURE] Evento ${event.type} validado com sucesso`);
  } catch (err: any) {
    console.error("🚨 [WEBHOOK SECURITY] Verificação de assinatura falhou:", err?.message);
    return res.status(400).json({
      error: `Webhook signature verification failed: ${err?.message}`,
    });
  }

  // ✅ 2) Processar (sempre responder 2xx rápido quando possível)
  try {
    switch (event.type) {
      // =====================================================
      // CHECKOUT - SESSÃO COMPLETA
      // =====================================================
      case "checkout.session.completed": {
        const session = event.data.object as Stripe.Checkout.Session;
        console.log("Checkout session completed:", session.id);

        try {
          const retrievedSession = await stripe.checkout.sessions.retrieve(session.id, {
            expand: ["subscription", "customer"],
          });

          // 🎫 Pagamento de ingresso
          if (retrievedSession.metadata?.type === "ingresso") {
            console.log("🎫 [WEBHOOK] Processando pagamento de ingresso:", session.id);

            const customer = retrievedSession.customer_details;
            const nomeComprador = customer?.name || "";
            const emailComprador = customer?.email || "";
            const telefoneComprador = customer?.phone || "";

            const ingressoData = {
              userId: null,
              nomeComprador,
              emailComprador,
              telefoneComprador,
              stripeCheckoutSessionId: session.id,
              valorPago: 1990,
              status: "ativo",
              dataCompra: new Date(),
            };

            const ingresso = await storage.createIngresso(ingressoData);
            console.log(
              `✅ [WEBHOOK] Ingresso criado com sucesso: ${ingresso.numero} (ID: ${ingresso.id})`
            );
            break;
          }

          // 💳 Subscription recorrente personalizada (fluxo custom)
          if (retrievedSession.metadata?.customSubscription === "true") {
            console.log("💰 [WEBHOOK] Processando subscription recorrente personalizada:", session.id);

            const customerId = retrievedSession.customer as string | null;
            const subscriptionId = retrievedSession.subscription as string | null;
            const customerEmail = retrievedSession.customer_details?.email || "";
            const customerName = retrievedSession.customer_details?.name || "";

            if (!customerId || !subscriptionId) {
              console.error("❌ [WEBHOOK] Customer ID ou Subscription ID ausente");
              break;
            }

            try {
              const stripeSubscription = await stripe.subscriptions.retrieve(subscriptionId);

              const tier = retrievedSession.metadata?.tier || "PLATINUM";
              const amountMonthly = parseFloat(retrievedSession.metadata?.amountMonthly || "0");
              const intervalMonths = parseInt(retrievedSession.metadata?.intervalMonths || "1");

              console.log(
                `✅ [WEBHOOK] Subscription criada - Tier: ${tier}, Valor: R$ ${amountMonthly}, Intervalo: ${intervalMonths} meses`
              );

              // Buscar usuário pelo email
              let userId: number | null = null;
              const existingUser = await db
                .select()
                .from(users)
                .where(eq(users.email, customerEmail))
                .limit(1);

              if (existingUser.length > 0) {
                userId = existingUser[0].id;
                console.log(`✅ [WEBHOOK] Usuário encontrado: ${userId}`);

                await db
                  .update(users)
                  .set({
                    stripeCustomerId: customerId,
                    stripeSubscriptionId: subscriptionId,
                    plano: tier.toLowerCase(),
                  })
                  .where(eq(users.id, userId));
              } else {
                console.log(`⚠️ [WEBHOOK] Usuário não encontrado para email: ${customerEmail}`);
              }

              // donorSubscriptions
              let subscriptionRecord: any[] = [];
              if (userId) {
                subscriptionRecord = await db
                  .insert(donorSubscriptions)
                  .values({
                    userId,
                    stripeSubscriptionId: subscriptionId,
                    stripeCustomerId: customerId,
                    status: stripeSubscription.status,
                    planPriceId: stripeSubscription.items.data[0]?.price?.id || "price_custom",
                    planName: tier.toLowerCase(),
                    currentPeriodStart: stripeSubscription.current_period_start,
                    currentPeriodEnd: stripeSubscription.current_period_end,
                    cancelAt: stripeSubscription.cancel_at || null,
                    canceledAt: stripeSubscription.canceled_at || null,
                    createdAt: new Date(),
                    updatedAt: new Date(),
                  })
                  .returning();
              }

              console.log(
                `✅ [WEBHOOK] Registro criado em donorSubscriptions: ${subscriptionRecord[0]?.id}`
              );

              // billingEvents
              if (subscriptionRecord.length > 0 && userId) {
                await db.insert(billingEvents).values({
                  userId,
                  subscriptionId: subscriptionRecord[0].id,
                  stripeSubscriptionId: subscriptionId,
                  eventType: "checkout.session.completed",
                  status: "active",
                  payloadSummary: {
                    tier,
                    amountMonthly,
                    intervalMonths,
                    customerEmail,
                    customerName,
                    checkoutSessionId: session.id,
                  },
                  processed: true,
                });

                console.log(`✅ [WEBHOOK] Evento de billing registrado`);
              }

              // doadores (compat antigo)
              if (userId) {
                const existingDoador = await db
                  .select()
                  .from(doadores)
                  .where(eq(doadores.userId, userId))
                  .limit(1);

                if (existingDoador.length === 0) {
                  await db.insert(doadores).values({
                    userId,
                    plano: tier,
                    valor: amountMonthly.toString(),
                    stripeSubscriptionId: subscriptionId,
                    status: "paid",
                    dataDoacaoInicial: new Date(),
                    ativo: true,
                  });

                  console.log(`✅ [WEBHOOK] Registro criado em doadores`);
                } else {
                  await db
                    .update(doadores)
                    .set({
                      plano: tier,
                      valor: amountMonthly.toString(),
                      stripeSubscriptionId: subscriptionId,
                      status: "paid",
                      ultimaDoacao: new Date(),
                      ativo: true,
                    })
                    .where(eq(doadores.id, existingDoador[0].id));

                  console.log(`✅ [WEBHOOK] Doador atualizado: ${existingDoador[0].id}`);
                }
              }
            } catch (error) {
              console.error("❌ [WEBHOOK] Erro ao processar subscription personalizada:", error);
            }

            break;
          }

          // Assinatura normal (fluxo antigo)
          console.log("Customer ID:", retrievedSession.customer);
          console.log("Subscription ID:", retrievedSession.subscription);
          console.log("Plan ID:", retrievedSession.metadata?.planId);

          if (
            retrievedSession.metadata?.planId &&
            retrievedSession.customer &&
            retrievedSession.subscription
          ) {
            console.log("Atualizando dados do Stripe para o usuário...");
          }
        } catch (error) {
          console.error("Error processing checkout session:", error);
        }

        break;
      }

      // =====================================================
      // INVOICE PAYMENT SUCCEEDED (AUTO-CREATE USER/DOADOR)
      // =====================================================
      case "invoice.payment_succeeded": {
        const successInvoice = event.data.object as Stripe.Invoice;

        if (!successInvoice.customer) {
          console.log("⚠️ [WEBHOOK] invoice.payment_succeeded sem customer");
          break;
        }

        let user = await db
          .select()
          .from(users)
          .where(eq(users.stripeCustomerId, successInvoice.customer as string))
          .limit(1);

        if (!user[0]) {
          console.log(
            `🆕 [WEBHOOK-AUTO-CREATE] Customer ${successInvoice.customer} não encontrado - criando automaticamente...`
          );

          try {
            const stripeCustomer = await stripe.customers.retrieve(successInvoice.customer as string);

            if (!stripeCustomer.deleted) {
              const subscription = successInvoice.subscription
                ? await stripe.subscriptions.retrieve(successInvoice.subscription as string)
                : null;

              const unitAmount = subscription?.items.data[0]?.price?.unit_amount || 0;

              let planName = "eco";
              let planValue = 9.9;

              if (unitAmount === 990) {
                planName = "eco";
                planValue = 9.9;
              } else if (unitAmount === 1990) {
                planName = "voz";
                planValue = 19.9;
              } else if (unitAmount === 8970) {
                planName = "grito";
                planValue = 89.7;
              } else if (unitAmount === 10000) {
                planName = "platinum";
                planValue = 100.0;
              }

              const newUser = await db
                .insert(users)
                .values({
                  nome: stripeCustomer.name || "Doador",
                  telefone: stripeCustomer.phone || "+5500000000000",
                  email: stripeCustomer.email || "temp@temp.com",
                  plano: planName,
                  role: "doador",
                  stripeCustomerId: successInvoice.customer as string,
                  stripeSubscriptionId: subscription?.id || null,
                  subscriptionStatus: subscription?.status || "active",
                  verificado: true,
                  ativo: true,
                  gritosTotal: 50,
                  nivelAtual: "Aliado do Grito",
                  tipo: "doador",
                  fonte: "doacao",
                })
                .returning();

              // ✅ evitar duplicação doador
              const existingDoador = await findExistingDonor({
                subscriptionId: subscription?.id,
                customerId: successInvoice.customer as string,
              });

              if (existingDoador) {
                const interval = subscription?.items.data[0]?.price?.recurring?.interval || "month";
                const periodicidade =
                  interval === "year" ? "anual" : interval === "month" ? "mensal" : "semestral";

                await db
                  .update(doadores)
                  .set({
                    plano: planName,
                    valor: planValue,
                    periodicidade,
                    status: "paid",
                    ultimaDoacao: new Date(successInvoice.created * 1000),
                    userId: newUser[0].id,
                    ativo: true,
                  })
                  .where(eq(doadores.id, existingDoador.id));

                console.log(
                  `♻️ [WEBHOOK-AUTO-CREATE] Doador existente atualizado e vinculado ao user ${newUser[0].id}`
                );
              } else {
                await db.insert(doadores).values({
                  userId: newUser[0].id,
                  plano: planName,
                  valor: planValue,
                  status: "paid",
                  ativo: true,
                  stripeCustomerId: successInvoice.customer as string,
                  stripeSubscriptionId: subscription?.id || null,
                  dataDoacaoInicial: new Date(successInvoice.created * 1000),
                  ultimaDoacao: new Date(successInvoice.created * 1000),
                });
              }

              console.log(
                `✅ [WEBHOOK-AUTO-CREATE] Usuário criado: ${newUser[0].nome} (ID: ${newUser[0].id}) - Plano: ${planName} - 50 Gritos creditados`
              );

              // 🔗 Criar link de marketing
              try {
                const linkSlug = newUser[0].nome
                  .toLowerCase()
                  .normalize("NFD")
                  .replace(/[̀-ͯ]/g, "")
                  .replace(/[^a-z0-9\s-]/g, "")
                  .trim()
                  .replace(/\s+/g, "-");

                const linkCode = `${linkSlug}-${newUser[0].id}`;

                await db.insert(marketingLinks).values({
                  campaignId: 1,
                  code: linkCode,
                  medium: "marketing",
                  source: "dev-marketing",
                  utmSource: "marketing",
                  utmMedium: "marketing",
                  utmCampaign: "Indique e Ganhe - IV ENCONTRO DO GRITO",
                  rewardToUserId: newUser[0].id,
                  metadata: { targetUrl: "/" },
                  isActive: true,
                });

                console.log(`🔗 [WEBHOOK-AUTO-CREATE] Link de marketing criado: ${linkCode}`);
              } catch (linkError) {
                console.error("⚠️ [WEBHOOK-AUTO-CREATE] Erro ao criar link de marketing:", linkError);
              }

              user = newUser;
            }
          } catch (createError) {
            console.error("❌ [WEBHOOK-AUTO-CREATE] Erro ao criar usuário:", createError);
          }
        }

        // indicação + marca evento
        if (user[0]) {
          try {
            const jaProcessado = await storage.isStripeEventProcessed(event.id);

            if (!jaProcessado) {
              const indicacao = await storage.getIndicacaoByIndicado(user[0].id);

              if (indicacao && indicacao.status === "PENDENTE") {
                const agora = new Date();
                const validade = new Date(indicacao.validade);
                let podeConfirmar = true;

                if (agora <= validade) {
                  const marketingLink = await storage.getMarketingLinkByCode(indicacao.refCode);

                  if (marketingLink) {
                    if (!marketingLink.isActive) podeConfirmar = false;
                    if (marketingLink.expiresAt && new Date(marketingLink.expiresAt) < agora)
                      podeConfirmar = false;

                    if (marketingLink.maxConversions !== null && marketingLink.maxConversions > 0) {
                      const stats = await storage.getMarketingLinkStats(marketingLink.id);
                      if (stats.conversoes >= marketingLink.maxConversions) podeConfirmar = false;
                    }
                  }

                  if (podeConfirmar) {
                    await storage.confirmarIndicacao(indicacao.id);
                    console.log(
                      `✅ [WEBHOOK-INDICAÇÃO] Indicação ${indicacao.id} confirmada - ${indicacao.indicouId} ganhou 1 ponto!`
                    );
                  }
                }
              }

              try {
                await storage.linkUserToActiveCampaign(user[0].id);
              } catch (linkError) {
                console.error(
                  `⚠️ [WEBHOOK-AUTO-LINK] Erro ao vincular usuário ${user[0].id} à campanha:`,
                  linkError
                );
              }

              await storage.markStripeEventProcessed(event.id, event.type);
            }
          } catch (error) {
            console.error(`❌ [WEBHOOK-INDICAÇÃO] Erro ao processar indicação para usuário ${user[0].id}:`, error);
          }
        }

        break;
      }

      // =====================================================
      // SUBSCRIPTION UPDATED
      // =====================================================
      case "customer.subscription.updated": {
        const subscription = event.data.object as Stripe.Subscription;
        console.log("Subscription updated:", subscription.id);

        try {
          const stripeCustomerId = subscription.customer as string;

          const userToUpdate = await db
            .select()
            .from(users)
            .where(
              or(
                eq(users.stripeSubscriptionId, subscription.id),
                eq(users.stripeCustomerId, stripeCustomerId)
              )
            )
            .limit(1)
            .then((r) => r[0]);

          if (!userToUpdate) {
            console.log(
              `⚠️ [WEBHOOK] Nenhum user encontrado para sub=${subscription.id} customer=${stripeCustomerId}`
            );
            break;
          }

          let planFromStripe = userToUpdate.plano || "eco";
          const priceAmount = subscription.items?.data?.[0]?.price?.unit_amount || 0;

          if (priceAmount) {
            const amountReais = priceAmount / 100;
            if (amountReais > 30) planFromStripe = "platinum";
            else if (amountReais >= 30) planFromStripe = "grito";
            else if (amountReais >= 20) planFromStripe = "voz";
            else if (amountReais >= 10) planFromStripe = "eco";
            else planFromStripe = "eco";
          }

          const paused = !!(subscription as any).pause_collection;
          const activeLike = ["active", "trialing"].includes(subscription.status);
          const shouldBeActive = activeLike && !paused;

          await db.update(users).set({ plano: planFromStripe }).where(eq(users.id, userToUpdate.id));

          const dbSub = await db
            .select()
            .from(donorSubscriptions)
            .where(eq(donorSubscriptions.stripeSubscriptionId, subscription.id))
            .limit(1)
            .then((r) => r[0]);

          if (dbSub) {
            await db
              .update(donorSubscriptions)
              .set({
                status: subscription.status,
                currentPeriodStart: subscription.current_period_start,
                currentPeriodEnd: subscription.current_period_end,
                cancelAt: subscription.cancel_at,
                canceledAt: subscription.canceled_at,
                updatedAt: new Date(),
              })
              .where(eq(donorSubscriptions.id, dbSub.id));

            await db.insert(billingEvents).values({
              userId: userToUpdate.id,
              subscriptionId: dbSub.id,
              stripeSubscriptionId: subscription.id,
              eventType: "customer.subscription.updated",
              status: subscription.status,
              payloadSummary: {
                status: subscription.status,
                plan: planFromStripe,
                paused,
              },
              processed: true,
            });
          }

          await db
            .update(doadores)
            .set({
              plano: planFromStripe,
              status: shouldBeActive ? "paid" : subscription.status,
              ativo: shouldBeActive,
              stripeCustomerId,
              stripeSubscriptionId: subscription.id,
              ultimaDoacao: shouldBeActive ? new Date() : undefined,
            } as any)
            .where(
              or(
                eq(doadores.userId, userToUpdate.id),
                eq(doadores.stripeSubscriptionId, subscription.id),
                eq(doadores.stripeCustomerId, stripeCustomerId)
              )
            );

          console.log(
            `✅ [WEBHOOK] Usuário ${userToUpdate.id} atualizado - Status: ${subscription.status}, Plano: ${planFromStripe}, Ativo=${shouldBeActive}`
          );
        } catch (error) {
          console.error("Error processing subscription update:", error);
        }

        break;
      }

      // =====================================================
      // SUBSCRIPTION DELETED (✅ corrigido: variáveis/escopo/chaves)
      // =====================================================
      case "customer.subscription.deleted": {
        const sub = event.data.object as Stripe.Subscription;
        const customerId = sub.customer as string;

        console.log("Subscription deleted:", sub.id);

        try {
          const userToUpdate = await db
            .select()
            .from(users)
            .where(or(eq(users.stripeSubscriptionId, sub.id), eq(users.stripeCustomerId, customerId)))
            .limit(1)
            .then((r) => r[0]);

          if (!userToUpdate) {
            console.log(`⚠️ [CANCEL] Nenhum user encontrado para sub=${sub.id} customer=${customerId}`);
            break;
          }

          // ✅ Se houver outra assinatura ativa no mesmo customer, NÃO derrubar acesso
          const best = await findBestActiveSubscription(stripe, customerId);

          if (best.ok && best.sub && best.sub.id !== sub.id) {
            console.log(
              `🛡️ [CANCEL] Ignorado: há outra assinatura ativa no customer. ativa=${best.sub.id}`
            );
            break; // <- MUITO IMPORTANTE
          }

          // alinhar donorSubscriptions (se existir)
          const dbSub = await db
            .select()
            .from(donorSubscriptions)
            .where(eq(donorSubscriptions.stripeSubscriptionId, sub.id))
            .limit(1)
            .then((r) => r[0]);

          if (dbSub) {
            await db
              .update(donorSubscriptions)
              .set({
                status: "canceled",
                canceledAt: sub.canceled_at || null,
                updatedAt: new Date(),
              } as any)
              .where(eq(donorSubscriptions.id, dbSub.id));

            await db.insert(billingEvents).values({
              userId: userToUpdate.id,
              subscriptionId: dbSub.id,
              stripeSubscriptionId: sub.id,
              eventType: "customer.subscription.deleted",
              status: "canceled",
              processed: true,
            });
          }

          // user inativo
          await db.update(users).set({ ativo: false } as any).where(eq(users.id, userToUpdate.id));
          console.log(`🔴 [CANCEL] User ${userToUpdate.id} marcado como inativo`);

          // doador inativo/canceled
          await db
            .update(doadores)
            .set({
              ativo: false,
              status: "canceled",
            } as any)
            .where(or(eq(doadores.userId, userToUpdate.id), eq(doadores.stripeCustomerId, customerId)));

          console.log(`🔴 [CANCEL] Doador do user ${userToUpdate.id} marcado como inativo`);
        } catch (error) {
          console.error("Error processing subscription deletion:", error);
        }

        break;
      }

      // =====================================================
      // DEFAULT
      // =====================================================
      default:
        console.log(`Unhandled event type ${event.type}`);
        break;
    }

    // ✅ Retornar 200 rapidamente para Stripe
    return res.status(200).json({ received: true, processed: true });
  } catch (err) {
    console.error("❌ [STRIPE WEBHOOK] Error geral:", err);
    return res.status(500).json({ error: "Internal server error" });
  }
});


  // 🗑️ DEPRECATED: Endpoint antigo redireciona para nova implementação com schedules
  app.post("/api/update-subscription", async (req, res) => {
    console.log(
      "⚠️ [DEPRECATED] Endpoint /api/update-subscription está obsoleto. Redirecionando para /api/schedule-plan-change"
    );

    // Redirecionar para nova implementação
    try {
      const response = await fetch(
        `${req.protocol}://${req.get("host")}/api/schedule-plan-change`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(req.body),
        }
      );

      const data = await response.json();

      if (response.ok) {
        res.json({
          ...data,
          deprecationWarning:
            "Este endpoint está obsoleto. Use /api/schedule-plan-change para novas implementações.",
        });
      } else {
        res.status(response.status).json(data);
      }
    } catch (error: any) {
      console.error("❌ [DEPRECATED] Erro ao redirecionar:", error);
      res.status(500).json({
        error: "Erro ao processar solicitação",
        message:
          "Use o endpoint /api/schedule-plan-change para mudanças de plano",
      });
    }
  });

  // Rota para verificar status da assinatura
  app.post("/api/check-subscription-status", async (req, res) => {
    try {
      const { subscriptionId } = req.body;

      if (!subscriptionId) {
        return res.status(400).json({ error: "Subscription ID é obrigatório" });
      }

      const subscription = await stripe.subscriptions.retrieve(subscriptionId);

      res.json({
        success: true,
        status: subscription.status,
        subscription: subscription,
      });
    } catch (error: any) {
      console.error("Error checking subscription status:", error);
      res.status(500).json({ error: "Erro ao verificar status da assinatura" });
    }
  });

  // Rota para cancelar assinatura
  app.post("/api/cancel-subscription", async (req, res) => {
    try {
      const { subscriptionId } = req.body;

      if (!subscriptionId) {
        return res.status(400).json({ error: "Subscription ID é obrigatório" });
      }

      const canceledSubscription = await stripe.subscriptions.cancel(
        subscriptionId
      );

      res.json({
        success: true,
        subscription: canceledSubscription,
        message: "Assinatura cancelada com sucesso",
      });
    } catch (error: any) {
      console.error("Error canceling subscription:", error);
      res.status(500).json({ error: "Erro ao cancelar assinatura" });
    }
  });

  // Buscar informações do plano anterior para reativação
  app.get("/api/billing/previous-plan", requireAuth, async (req, res) => {
    try {
      const user = (req as any).user;

      if (!user) {
        return res.status(400).json({
          error: "Usuário não encontrado",
          message: "Você não está autenticado",
        });
      }

      console.log(
        `📋 [PREVIOUS-PLAN] Buscando plano anterior para user ${user.id}`
      );

      // PRIORIDADE 1: Buscar do banco de dados (tabela doadores) - dados originais
      const doadorResult = await pool.query(
        `SELECT plano, valor, periodicidade FROM doadores WHERE user_id = $1 ORDER BY created_at DESC LIMIT 1`,
        [user.id]
      );

      let nomePlano = user.plano || "eco";
      let valor = 9.9; // valor padrão eco
      let valorCentavos = 990;
      let periodicidade = "mensal";

      if (doadorResult.rows.length > 0) {
        const doador = doadorResult.rows[0];
        if (doador.plano) {
          nomePlano = doador.plano;
        }
        if (doador.valor) {
          valor = parseFloat(doador.valor);
          valorCentavos = Math.round(valor * 100);
        }
        if (doador.periodicidade) {
          periodicidade = doador.periodicidade;
        }
        console.log(
          `📋 [PREVIOUS-PLAN] Dados encontrados no banco: ${nomePlano}, R$ ${valor}, ${periodicidade}`
        );
      } else {
        // PRIORIDADE 2: Usar o plano salvo no usuário com valores padrão
        const planPrices: Record<string, number> = {
          eco: 990,
          voz: 1990,
          grito: 2990,
          platinum: 9990,
        };
        const planoLower = (user.plano || "eco").toLowerCase();
        valorCentavos = planPrices[planoLower] || 990;
        valor = valorCentavos / 100;
        nomePlano = planoLower;
        console.log(
          `📋 [PREVIOUS-PLAN] Usando valores padrão do plano ${nomePlano}: R$ ${valor}`
        );
      }

      // Capitalizar nome do plano
      const nomeCapitalizado =
        nomePlano.charAt(0).toUpperCase() + nomePlano.slice(1).toLowerCase();

      console.log(
        `✅ [PREVIOUS-PLAN] Plano encontrado: ${nomeCapitalizado}, R$ ${valor}, ${periodicidade}`
      );

      res.json({
        success: true,
        plano: {
          nome: nomeCapitalizado,
          valor: valor,
          valorCentavos: valorCentavos,
          periodicidade: periodicidade,
          priceId: null,
          status: "canceled",
        },
      });
    } catch (error: any) {
      console.error("❌ [PREVIOUS-PLAN] Error:", error);
      res.status(500).json({
        error: "Erro ao buscar plano anterior",
        message: error.message,
      });
    }
  });

  // Reativar assinatura com Apple Pay/Google Pay ou Cartão (com seleção de plano/upgrade)
  app.post(
    "/api/billing/reactivate-with-setup",
    requireAuth,
    async (req, res) => {
      try {
        const user = (req as any).user;
        const { planoId, valorCentavos, periodicity } = req.body;

        // Mapear periodicidade para intervalo do Stripe
        const intervalMapping: {
          [key: string]: {
            interval: "month" | "year";
            interval_count?: number;
          };
        } = {
          mensal: { interval: "month" },
          trimestral: { interval: "month", interval_count: 3 },
          semestral: { interval: "month", interval_count: 6 },
          anual: { interval: "year" },
        };
        const intervalConfig = intervalMapping[periodicity || "mensal"] || {
          interval: "month",
        };

        console.log("🎯 [REACTIVATE] Dados recebidos:", {
          planoId,
          valorCentavos,
          periodicity,
          intervalConfig,
        });

        if (!user || !user.stripeSubscriptionId) {
          return res.status(400).json({
            error: "Assinatura não encontrada",
            message: "Você não possui uma assinatura para reativar",
          });
        }

        let stripeCustomerId = user.stripeCustomerId;

        // Verificar se o customer ainda existe no Stripe (e não foi deletado)
        if (stripeCustomerId) {
          try {
            const existingCustomer = (await stripe.customers.retrieve(
              stripeCustomerId
            )) as any;
            if (existingCustomer.deleted) {
              console.log(
                `⚠️ [REACTIVATE-SETUP] Customer ${stripeCustomerId} foi DELETADO do Stripe, criando novo...`
              );
              stripeCustomerId = null;
            } else {
              console.log(
                `✅ [REACTIVATE-SETUP] Customer ${stripeCustomerId} existe e está ativo no Stripe`
              );
            }
          } catch (customerError: any) {
            console.log(
              `⚠️ [REACTIVATE-SETUP] Erro ao verificar customer: ${customerError.code} - ${customerError.message}`
            );
            if (customerError.code === "resource_missing") {
              console.log(
                `⚠️ [REACTIVATE-SETUP] Customer ${stripeCustomerId} não existe mais no Stripe, criando novo...`
              );
              stripeCustomerId = null;
            } else {
              throw customerError;
            }
          }
        }

        // Se não tem customer válido, criar um novo
        if (!stripeCustomerId) {
          console.log(
            `🆕 [REACTIVATE-SETUP] Criando novo customer Stripe para user ${user.id}`
          );
          const newCustomer = await stripe.customers.create({
            email: user.email || undefined,
            name: user.nome || "Doador",
            phone: user.telefone || undefined,
            metadata: {
              userId: String(user.id),
              nome: user.nome || "",
              reativacao: "true",
            },
          });
          stripeCustomerId = newCustomer.id;
          console.log(
            `✅ [REACTIVATE-SETUP] Novo customer criado: ${stripeCustomerId}`
          );

          // Atualizar no banco
          await pool.query(
            "UPDATE users SET stripe_customer_id = $1 WHERE id = $2",
            [stripeCustomerId, user.id]
          );
          await pool.query(
            "UPDATE doadores SET stripe_customer_id = $1 WHERE user_id = $2",
            [stripeCustomerId, user.id]
          );
        }

        console.log(
          `🔄 [REACTIVATE-SETUP] Iniciando setup para reativação - user ${
            user.id
          }, plano: ${planoId || "anterior"}`
        );

        // Tentar recuperar subscription antiga (pode não existir mais)
        let subscription: any = null;
        let priceId: string | null = null;
        let needsToCancelOld = false;

        try {
          subscription = await stripe.subscriptions.retrieve(
            user.stripeSubscriptionId
          );
          priceId = subscription.items.data[0]?.price?.id;
          needsToCancelOld = subscription.status !== "canceled";
          console.log(
            `📋 [REACTIVATE-SETUP] Subscription antiga encontrada: ${subscription.id}, status: ${subscription.status}`
          );
        } catch (stripeError: any) {
          // Subscription não existe mais no Stripe - criar nova
          if (stripeError.code === "resource_missing") {
            console.log(
              `⚠️ [REACTIVATE-SETUP] Subscription antiga não existe mais no Stripe, criando nova...`
            );
            needsToCancelOld = false;

            // Buscar o produto padrão de doação para criar um preço
            const products = await stripe.products.list({
              active: true,
              limit: 10,
            });
            const doacaoProduct = products.data.find(
              (p) =>
                p.name.toLowerCase().includes("doação") ||
                p.name.toLowerCase().includes("doacao") ||
                p.name.toLowerCase().includes("clube")
            );

            if (doacaoProduct && valorCentavos) {
              const newPrice = await stripe.prices.create({
                product: doacaoProduct.id,
                unit_amount: valorCentavos,
                currency: "brl",
                recurring: { interval: "month", interval_count: 1 },
                metadata: { plano: planoId || "eco", tipo: "reativacao" },
              });
              priceId = newPrice.id;
              console.log(
                `✅ [REACTIVATE-SETUP] Novo preço criado: ${priceId}`
              );
            }
          } else {
            throw stripeError;
          }
        }

        if (!priceId) {
          return res.status(400).json({
            error: "Plano não encontrado",
            message: "Não foi possível recuperar ou criar o plano",
          });
        }

        // CORREÇÃO: Sempre usar o plano e valor SELECIONADOS pelo usuário
        if (planoId && valorCentavos) {
          console.log(
            `🎯 [REACTIVATE] Usando plano SELECIONADO: ${planoId} (R$ ${
              valorCentavos / 100
            })`
          );

          // Buscar produto para criar preço
          let productId: string;

          if (priceId) {
            // Usar produto do preço existente
            const existingPrice = await stripe.prices.retrieve(priceId);
            productId = existingPrice.product as string;
          } else {
            // Buscar produto de doação
            const products = await stripe.products.list({
              active: true,
              limit: 10,
            });
            const doacaoProduct = products.data.find(
              (p) =>
                p.name.toLowerCase().includes("doação") ||
                p.name.toLowerCase().includes("doacao") ||
                p.name.toLowerCase().includes("clube")
            );
            productId =
              doacaoProduct?.id ||
              (
                await stripe.products.create({
                  name: "Doação Clube do Grito",
                  metadata: { tipo: "doacao" },
                })
              ).id;
          }

          // Criar novo preço com o valor e periodicidade SELECIONADOS
          const newPrice = await stripe.prices.create({
            product: productId,
            unit_amount: valorCentavos,
            currency: "brl",
            recurring: {
              interval: intervalConfig.interval,
              interval_count: intervalConfig.interval_count || 1,
            },
            metadata: {
              plano: planoId,
              periodicidade: periodicity || "mensal",
              tipo: "reativacao",
            },
          });
          priceId = newPrice.id;
          console.log(
            `✅ [REACTIVATE] Preço criado: ${priceId} (${valorCentavos} centavos, ${
              periodicity || "mensal"
            })`
          );
        }

        // 🔄 Verificar se o preço está ativo, se não, buscar/criar um equivalente
        if (!priceId) {
          return res.status(400).json({
            error: "Plano não encontrado",
            message: "Não foi possível determinar o plano para reativação",
          });
        }
        const originalPrice = await stripe.prices.retrieve(priceId);
        console.log(
          `🔍 [REACTIVATE] Preço original: ${priceId}, ativo: ${originalPrice.active}`
        );

        if (!originalPrice.active) {
          console.log(
            `⚠️ [REACTIVATE] Preço ${priceId} está inativo, buscando alternativa...`
          );

          // Buscar um preço ativo do mesmo produto com mesmos atributos
          const activePrices = await stripe.prices.list({
            product: originalPrice.product as string,
            active: true,
            limit: 10,
          });

          // Filtrar para encontrar preço com mesmo valor, moeda e intervalo
          const compatiblePrice = activePrices.data.find(
            (p) =>
              p.unit_amount === originalPrice.unit_amount &&
              p.currency === originalPrice.currency &&
              p.recurring?.interval === originalPrice.recurring?.interval
          );

          if (compatiblePrice) {
            priceId = compatiblePrice.id;
            console.log(
              `✅ [REACTIVATE] Preço compatível encontrado: ${priceId}`
            );
          } else {
            // Criar novo preço ativo com os mesmos atributos
            const newPrice = await stripe.prices.create({
              product: originalPrice.product as string,
              unit_amount: originalPrice.unit_amount!,
              currency: originalPrice.currency,
              recurring: originalPrice.recurring
                ? {
                    interval: originalPrice.recurring.interval,
                    interval_count: originalPrice.recurring.interval_count || 1,
                  }
                : undefined,
            });
            priceId = newPrice.id;
            console.log(`🆕 [REACTIVATE] Novo preço criado: ${priceId}`);
          }
        }

        if (needsToCancelOld) {
          console.log(
            `🗑️ [REACTIVATE-SETUP] Cancelando subscription antiga: ${user.stripeSubscriptionId}`
          );
          try {
            await stripe.subscriptions.cancel(user.stripeSubscriptionId);
          } catch (cancelError: any) {
            console.log(
              `⚠️ [REACTIVATE-SETUP] Erro ao cancelar subscription antiga (pode já estar cancelada): ${cancelError.message}`
            );
          }
        }

        const newSubscription = await stripe.subscriptions.create({
          customer: user.stripeCustomerId,
          items: [{ price: priceId }],
          payment_behavior: "default_incomplete",
          payment_settings: {
            save_default_payment_method: "on_subscription",
            payment_method_types: ["card"],
          },
          expand: ["latest_invoice.payment_intent", "pending_setup_intent"],
        });

        console.log(
          `✅ [REACTIVATE-SETUP] Nova subscription criada: ${newSubscription.id}, status: ${newSubscription.status}`
        );

        let clientSecret: string | null = null;
        let secretType: "setup" | "payment" = "setup";

        if (newSubscription.pending_setup_intent) {
          const setupIntent =
            typeof newSubscription.pending_setup_intent === "string"
              ? await stripe.setupIntents.retrieve(
                  newSubscription.pending_setup_intent
                )
              : newSubscription.pending_setup_intent;
          clientSecret = setupIntent.client_secret;
          secretType = "setup";
          console.log(
            `🔧 [REACTIVATE-SETUP] Usando SetupIntent: ${setupIntent.id}`
          );
        } else if (newSubscription.latest_invoice) {
          const invoice =
            typeof newSubscription.latest_invoice === "string"
              ? await stripe.invoices.retrieve(newSubscription.latest_invoice, {
                  expand: ["payment_intent"],
                })
              : newSubscription.latest_invoice;

          if (invoice.payment_intent) {
            const paymentIntent =
              typeof invoice.payment_intent === "string"
                ? await stripe.paymentIntents.retrieve(invoice.payment_intent)
                : invoice.payment_intent;
            clientSecret = paymentIntent.client_secret;
            secretType = "payment";
            console.log(
              `💳 [REACTIVATE-SETUP] Usando PaymentIntent: ${paymentIntent.id}`
            );
          }
        }

        if (!clientSecret) {
          console.log(
            `🔧 [REACTIVATE-SETUP] Criando SetupIntent manualmente...`
          );
          const setupIntent = await stripe.setupIntents.create({
            customer: user.stripeCustomerId,
            payment_method_types: ["card"],
            usage: "off_session",
          });
          clientSecret = setupIntent.client_secret;
          secretType = "setup";
        }

        await storage.updateUserStripeInfo(
          user.id,
          user.stripeCustomerId,
          newSubscription.id,
          newSubscription.status
        );

        // Atualizar o plano no banco Digital Ocean
        if (planoId) {
          console.log(
            `📝 [REACTIVATE-SETUP] Atualizando plano no Digital Ocean: ${planoId}`
          );
          await pool.query(`UPDATE users SET plano = $1 WHERE id = $2`, [
            planoId,
            user.id,
          ]);
          console.log(
            `✅ [REACTIVATE-SETUP] Plano atualizado para: ${planoId}`
          );
        }

        res.json({
          success: true,
          subscriptionId: newSubscription.id,
          clientSecret: clientSecret,
          secretType: secretType,
          status: newSubscription.status,
        });
      } catch (error: any) {
        console.error("❌ [REACTIVATE-SETUP] Error:", error);
        res.status(500).json({
          error: "Erro ao preparar reativação",
          message: error.message,
        });
      }
    }
  );

  // Confirmar pagamento da reativação (após Apple Pay/Google Pay ou Cartão)
  app.post("/api/billing/reactivate-confirm", requireAuth, async (req, res) => {
    try {
      const user = (req as any).user;
      const { subscriptionId, paymentMethodId } = req.body;

      if (!subscriptionId) {
        return res.status(400).json({
          error: "Subscription ID obrigatório",
        });
      }

      console.log(
        `✅ [REACTIVATE-CONFIRM] Confirmando reativação - subscription ${subscriptionId}`
      );

      if (paymentMethodId) {
        try {
          await stripe.paymentMethods.attach(paymentMethodId, {
            customer: user.stripeCustomerId,
          });
        } catch (attachError: any) {
          if (!attachError.message?.includes("already been attached")) {
            throw attachError;
          }
        }

        await stripe.customers.update(user.stripeCustomerId, {
          invoice_settings: {
            default_payment_method: paymentMethodId,
          },
        });

        await stripe.subscriptions.update(subscriptionId, {
          default_payment_method: paymentMethodId,
        });

        console.log(
          `💳 [REACTIVATE-CONFIRM] Payment method ${paymentMethodId} definido como padrão`
        );
      }

      const subscription = await stripe.subscriptions.retrieve(subscriptionId);

      await storage.updateUserStripeInfo(
        user.id,
        user.stripeCustomerId,
        subscriptionId,
        subscription.status
      );

      await pool.query(
        `UPDATE users SET subscription_status = $1 WHERE id = $2`,
        [subscription.status, user.id]
      );

      console.log(
        `✅ [REACTIVATE-CONFIRM] Reativação confirmada - status: ${subscription.status}`
      );

      res.json({
        success: true,
        subscriptionId: subscriptionId,
        status: subscription.status,
        message: "Assinatura reativada com sucesso",
      });
    } catch (error: any) {
      console.error("❌ [REACTIVATE-CONFIRM] Error:", error);
      res.status(500).json({
        error: "Erro ao confirmar reativação",
        message: error.message,
      });
    }
  });

  // Reativar assinatura expirada (incomplete_expired/void/unpaid)
  app.post("/api/billing/reactivate", requireAuth, async (req, res) => {
    try {
      const user = (req as any).user;
      const { paymentMethodId } = req.body;

      if (!user || !user.stripeSubscriptionId) {
        return res.status(400).json({
          error: "Assinatura não encontrada",
          message: "Você não possui uma assinatura para reativar",
        });
      }

      if (!paymentMethodId) {
        return res.status(400).json({
          error: "Método de pagamento obrigatório",
          message: "Selecione um cartão ou adicione um novo",
        });
      }

      console.log(
        `🔄 [REACTIVATE] Reativando subscription ${user.stripeSubscriptionId} para user ${user.id}`
      );

      // Buscar subscription atual
      const subscription = await stripe.subscriptions.retrieve(
        user.stripeSubscriptionId
      );

      // Validar status (apenas incomplete_expired, unpaid ou canceled podem ser reativadas)
      const reactivableStatuses = ["incomplete_expired", "unpaid", "canceled"];
      if (!reactivableStatuses.includes(subscription.status)) {
        return res.status(400).json({
          error: "Assinatura não pode ser reativada",
          message: `Status atual: ${subscription.status}. Apenas assinaturas expiradas, não pagas ou canceladas podem ser reativadas.`,
          currentStatus: subscription.status,
        });
      }

      // Criar nova subscription com o mesmo plano
      const priceId = subscription.items.data[0].price.id;

      if (!user.stripeCustomerId) {
        return res.status(400).json({
          error: "Customer não encontrado",
          message: "Dados do Stripe incompletos",
        });
      }

      // Anexar payment method ao customer
      await stripe.paymentMethods.attach(paymentMethodId, {
        customer: user.stripeCustomerId,
      });

      // Definir como padrão
      await stripe.customers.update(user.stripeCustomerId, {
        invoice_settings: {
          default_payment_method: paymentMethodId,
        },
      });

      // Criar nova subscription com payment method já anexado
      const newSubscription = await stripe.subscriptions.create({
        customer: user.stripeCustomerId,
        items: [{ price: priceId }],
        default_payment_method: paymentMethodId,
        payment_behavior: "default_incomplete",
        payment_settings: {
          save_default_payment_method: "on_subscription",
          payment_method_types: ["card"],
        },
        // ✅ REMOVIDO: expand - não precisamos buscar síncrono, webhook processa
      });

      // Cancelar subscription antiga se necessário
      if (subscription.status !== "canceled") {
        await stripe.subscriptions.cancel(user.stripeSubscriptionId);
      }

      // Atualizar banco de dados
      await storage.updateUserStripeInfo(
        user.id,
        user.stripeCustomerId,
        newSubscription.id,
        newSubscription.status
      );

      console.log(
        `✅ [REACTIVATE] Nova subscription criada: ${newSubscription.id}, status: ${newSubscription.status}`
      );

      // ✅ CORREÇÃO: Buscar PaymentIntent de forma assíncrona (se necessário)
      // Webhook processará o pagamento - não bloqueamos a resposta
      res.json({
        success: true,
        subscriptionId: newSubscription.id,
        status: newSubscription.status,
        message: "Assinatura reativada com sucesso",
      });
    } catch (error: any) {
      console.error("❌ [REACTIVATE] Error:", error);
      res.status(500).json({
        error: "Erro ao reativar assinatura",
        message: error.message,
      });
    }
  });

  // Buscar client_secret de um PaymentIntent para autenticação 3DS
  app.get(
    "/api/billing/payment-intent/:invoiceId",
    requireAuth,
    async (req, res) => {
      try {
        const user = (req as any).user;
        const { invoiceId } = req.params;

        if (!invoiceId) {
          return res.status(400).json({
            error: "Invoice ID obrigatório",
          });
        }

        console.log(
          `🔐 [3DS] Buscando PaymentIntent para invoice ${invoiceId} (user ${user.id})`
        );

        // Buscar invoice
        const invoice = await stripe.invoices.retrieve(invoiceId);

        // Verificar se pertence ao usuário (segurança)
        if (invoice.customer !== user.stripeCustomerId) {
          return res.status(403).json({
            error: "Acesso negado",
            message: "Esta fatura não pertence a você",
          });
        }

        // Buscar PaymentIntent
        const paymentIntentId = invoice.payment_intent as string;

        if (!paymentIntentId) {
          return res.status(404).json({
            error: "PaymentIntent não encontrado",
            message: "Esta fatura não possui um pagamento associado",
          });
        }

        const paymentIntent = await stripe.paymentIntents.retrieve(
          paymentIntentId
        );

        console.log(
          `✅ [3DS] PaymentIntent ${paymentIntentId} encontrado, status: ${paymentIntent.status}`
        );

        res.json({
          success: true,
          clientSecret: paymentIntent.client_secret,
          status: paymentIntent.status,
          requiresAction: paymentIntent.status === "requires_action",
        });
      } catch (error: any) {
        console.error("❌ [3DS] Error:", error);
        res.status(500).json({
          error: "Erro ao buscar informações de pagamento",
          message: error.message,
        });
      }
    }
  );

  // Update user Stripe information
  app.post("/api/update-user-stripe", async (req, res) => {
    try {
      const {
        userId,
        stripeCustomerId,
        stripeSubscriptionId,
        subscriptionStatus,
      } = req.body;

      if (!userId) {
        return res.status(400).json({ error: "User ID é obrigatório" });
      }

      const updatedUser = await storage.updateUserStripeInfo(
        userId,
        stripeCustomerId,
        stripeSubscriptionId,
        subscriptionStatus
      );

      res.json({
        success: true,
        message: "Informações do Stripe atualizadas com sucesso",
        user: updatedUser,
      });
    } catch (error: any) {
      console.error("Error updating user Stripe info:", error);
      res
        .status(500)
        .json({ error: "Erro ao atualizar informações do Stripe" });
    }
  });

  // Register user
  app.post("/api/register", async (req, res) => {
    try {
      const userData = postPaymentRegisterSchema.parse(req.body);

      // Check if this user is coming from a payment flow (has plano)
      const isDoador =
        userData.plano &&
        ["eco", "voz", "grito", "platinum"].includes(userData.plano);

      // 🔗 VERIFICAR REFERRAL: Se tem código de convite na requisição
      let referralData = null;
      if (req.body.referralCode) {
        try {
          const referral = await db
            .select()
            .from(referrals)
            .where(eq(referrals.codigoConvite, req.body.referralCode))
            .limit(1);

          if (referral[0] && referral[0].status === "pendente") {
            // Verificar se não expirou
            if (
              !referral[0].expiradoEm ||
              new Date() <= new Date(referral[0].expiradoEm)
            ) {
              referralData = referral[0];
              console.log(
                `🎯 [REFERRAL] Novo usuário via referral: ${req.body.referralCode} de usuário ${referralData.referrerUserId}`
              );
            } else {
              console.log(
                `⚠️ [REFERRAL] Link expirado: ${req.body.referralCode}`
              );
            }
          }
        } catch (error) {
          console.error("Erro ao verificar referral:", error);
        }
      }

      // CONSOLIDAÇÃO AUTOMÁTICA: Garantir que vire um user na tabela principal
      const { consolidateUser } = await import("./userConsolidation");
      const consolidatedUser = await consolidateUser({
        nome: `${userData.nome} ${userData.sobrenome || ""}`.trim(),
        telefone: userData.telefone,
        email: userData.email,
        tipo: isDoador ? "doador" : "doador", // Always doador for this endpoint
        fonte: referralData ? "referral" : "doacao", // Marcar como referral se veio de convite
        plano: userData.plano || "eco",
      });

      console.log(
        `✅ [CONSOLIDAÇÃO] Usuário registrado: ${consolidatedUser.nome} (${consolidatedUser.telefone}) como ${consolidatedUser.tipo} via ${consolidatedUser.fonte}`
      );

      // 🔗 SISTEMA DE INDICAÇÃO (novo): ref_code pode vir de user ou marketing_link
      if (req.body.referralCode) {
        try {
          const refCode = req.body.referralCode;

          // Verificar se é um link de marketing
          const marketingLink = await storage.getMarketingLinkByCode(refCode);

          if (marketingLink && marketingLink.isActive) {
            // Link de marketing encontrado
            console.log(
              `🔗 [MARKETING] Cadastro via link de marketing: ${refCode}`
            );

            // Verificar expiração
            const now = new Date();
            if (
              marketingLink.expiresAt &&
              new Date(marketingLink.expiresAt) < now
            ) {
              console.log(`⏰ [MARKETING] Link expirado: ${refCode}`);
            } else {
              // Criar indicação com marketing link
              const indicouId = marketingLink.rewardToUserId || null; // Pode ser NULL
              await storage.createIndicacao(
                indicouId,
                consolidatedUser.id,
                refCode
              );
              console.log(
                `✅ [MARKETING-INDICAÇÃO] Indicação criada: link ${refCode} -> user ${consolidatedUser.id}`
              );
            }
          } else {
            // Não é marketing link, verificar se é ref_slug de usuário
            const indicador = await storage.getUserByRefSlug(refCode);

            if (indicador) {
              // Bloquear autoindicação
              if (indicador.id === consolidatedUser.id) {
                console.log(
                  `⚠️ [INDICAÇÃO] Bloqueada autoindicação: user ${consolidatedUser.id}`
                );
              } else {
                await storage.createIndicacao(
                  indicador.id,
                  consolidatedUser.id,
                  refCode
                );
                console.log(
                  `✅ [INDICAÇÃO] Criada indicação: user ${indicador.id} indicou ${consolidatedUser.id}`
                );
              }
            } else {
              console.log(
                `❌ [INDICAÇÃO] Código de indicação não encontrado: ${refCode}`
              );
            }
          }
        } catch (error) {
          console.error("❌ [INDICAÇÃO] Erro ao processar ref_code:", error);
        }
      }

      // Generate verification code
      const verificationCode = Math.floor(
        100000 + Math.random() * 900000
      ).toString();

      try {
        // Try to send SMS via Twilio
        const client = getTwilioClient();
        await client.messages.create({
          body: `Seu código de verificação do Clube do Grito é: ${verificationCode}`,
          from: process.env.TWILIO_PHONE_NUMBER,
          to: `+55${userData.telefone.replace(/\D/g, "")}`,
        });

        console.log(
          `SMS enviado para ${userData.telefone}: ${verificationCode}`
        );
      } catch (twilioError: any) {
        // If Twilio fails (trial account, unverified number, etc.), log the code for development
        console.log(
          `DESENVOLVIMENTO - Código para ${userData.telefone}: ${verificationCode}`
        );
        console.log("Erro Twilio:", twilioError.message);
      }

      // Store verification code (in production, use a proper cache like Redis)
      verificationCodes.set(userData.telefone, verificationCode);

      // 🎯 PROCESSAR REFERRAL: Se veio de convite, guardar para processar na verificação
      if (referralData) {
        // Armazenar dados do referral para processar quando verificar o código
        verificationCodes.set(
          `referral_${userData.telefone}`,
          JSON.stringify({
            referralId: referralData.id,
            referrerUserId: referralData.referrerUserId,
            missaoId: referralData.missaoId,
            gritosRecompensa: referralData.gritosRecompensa,
          })
        );
        console.log(
          `💾 [REFERRAL] Dados salvos para processar na verificação: ${userData.telefone}`
        );
      }

      res.json({
        userId: consolidatedUser.id,
        message: "Código de verificação enviado via SMS",
        // In development, return the code for testing
        ...(process.env.NODE_ENV === "development" && {
          devCode: verificationCode,
        }),
      });
    } catch (error: any) {
      console.error("Error registering user:", error);
      if (error instanceof z.ZodError) {
        return res
          .status(400)
          .json({ error: "Dados inválidos", details: error.errors });
      }
      res.status(500).json({ error: "Erro ao registrar usuário" });
    }
  });

  app.get("/api/admin/check-all-subscriptions", async (req, res) => {
    try {
      // Buscar todos os doadores com subscriptions
      const doadoresList = await db
        .select({
          id: doadores.id,
          nome: users.nome,
          stripeSubscriptionId: doadores.stripeSubscriptionId,
          stripeCustomerId: doadores.stripeCustomerId,
        })
        .from(doadores)
        .leftJoin(users, eq(doadores.userId, users.id))
        .where(ne(doadores.stripeSubscriptionId, null));

      const results = [];

      for (const doador of doadoresList) {
        if (!doador.stripeSubscriptionId) continue;

        try {
          const subscription = await stripe.subscriptions.retrieve(
            doador.stripeSubscriptionId
          );

          results.push({
            doadorId: doador.id,
            nome: doador.nome,
            stripeSubId: doador.stripeSubscriptionId,
            status: subscription.status,
            currentPeriodStart: new Date(
              subscription.current_period_start * 1000
            ),
            currentPeriodEnd: new Date(subscription.current_period_end * 1000),
            nextBillingDate: new Date(subscription.current_period_end * 1000),
            amount: subscription.items.data[0]?.price?.unit_amount
              ? subscription.items.data[0].price.unit_amount / 100
              : 0,
            interval: subscription.items.data[0]?.price?.recurring?.interval,
            intervalCount:
              subscription.items.data[0]?.price?.recurring?.interval_count,
            cancelAtPeriodEnd: subscription.cancel_at_period_end,
          });
        } catch (error: any) {
          results.push({
            doadorId: doador.id,
            nome: doador.nome,
            stripeSubId: doador.stripeSubscriptionId,
            error: error.message,
          });
        }
      }

      res.json({ total: results.length, subscriptions: results });
    } catch (error: any) {
      console.error("Error checking subscriptions:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post(
    "/api/admin/create-manual-subscription",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        const { userId, monthlyAmount, intervalMonths } = req.body;

        if (!userId || !monthlyAmount) {
          return res
            .status(400)
            .json({ error: "userId e monthlyAmount são obrigatórios" });
        }

        const interval = intervalMonths || 1;
        if (![1, 3, 6, 12].includes(interval)) {
          return res
            .status(400)
            .json({ error: "intervalMonths deve ser 1, 3, 6 ou 12" });
        }

        const [user] = await db
          .select()
          .from(users)
          .where(eq(users.id, userId))
          .limit(1);
        if (!user) {
          return res.status(404).json({ error: "Usuário não encontrado" });
        }

        console.log(
          `🔧 [MANUAL SUB] Criando subscription manual para ${user.nome} (ID: ${userId})`
        );
        console.log(
          `💰 Valor: R$ ${monthlyAmount}/mês | Intervalo: ${interval} meses`
        );

        const [doador] = await db
          .select()
          .from(doadores)
          .where(eq(doadores.userId, userId))
          .orderBy(doadores.dataDoacaoInicial)
          .limit(1);

        if (!doador?.stripePaymentIntentId) {
          return res.status(404).json({
            error:
              "Usuário não tem payment intent registrado. É necessário que ele tenha feito pelo menos um pagamento anteriormente.",
          });
        }

        console.log(
          `🔍 [MANUAL SUB] Payment Intent: ${doador.stripePaymentIntentId}`
        );

        const paymentIntent = await stripe.paymentIntents.retrieve(
          doador.stripePaymentIntentId
        );

        if (!paymentIntent.customer) {
          return res.status(400).json({
            error: "Payment Intent não tem customer associado",
          });
        }

        const customerId =
          typeof paymentIntent.customer === "string"
            ? paymentIntent.customer
            : paymentIntent.customer.id;

        console.log(`✅ [MANUAL SUB] Customer ID: ${customerId}`);

        const customer = await stripe.customers.retrieve(customerId);
        if (customer.deleted) {
          return res
            .status(400)
            .json({ error: "Customer foi deletado no Stripe" });
        }

        const paymentMethods = await stripe.paymentMethods.list({
          customer: customerId,
          type: "card",
        });

        if (paymentMethods.data.length === 0) {
          return res.status(400).json({
            error:
              "Usuário não tem método de pagamento salvo. É necessário que ele adicione um cartão através da página de planos.",
          });
        }

        const defaultPaymentMethod = paymentMethods.data[0].id;
        console.log(`💳 [MANUAL SUB] Payment Method: ${defaultPaymentMethod}`);

        const priceData: Stripe.SubscriptionCreateParams.Item.PriceData = {
          currency: "brl",
          product_data: {
            name: `Contribuição Mensal - ${user.nome}`,
            description: `Assinatura recorrente de R$ ${monthlyAmount.toFixed(
              2
            )} a cada ${interval} ${interval === 1 ? "mês" : "meses"}`,
          },
          unit_amount: Math.round(monthlyAmount * 100),
          recurring: {
            interval: "month",
            interval_count: interval,
          },
        };

        const subscription = await stripe.subscriptions.create({
          customer: customerId,
          items: [{ price_data: priceData }],
          default_payment_method: defaultPaymentMethod,
          metadata: {
            userId: userId.toString(),
            tier:
              monthlyAmount <= 10
                ? "eco"
                : monthlyAmount <= 30
                ? "bronze"
                : monthlyAmount <= 60
                ? "prata"
                : monthlyAmount <= 100
                ? "ouro"
                : "platinum",
            amountMonthly: monthlyAmount.toString(),
            intervalMonths: interval.toString(),
            manuallyCreated: "true",
          },
        });

        console.log(`✅ [MANUAL SUB] Subscription criada: ${subscription.id}`);
        console.log(`📊 Status: ${subscription.status}`);

      await db.update(users)
        .set({ 
          stripeCustomerId: customerId,
          stripeSubscriptionId: subscription.id 
        })
        .where(eq(users.id, userId));

      await db.update(doadores)
        .set({ 
          stripeCustomerId: customerId,
          stripeSubscriptionId: subscription.id,
          status: subscription.status === 'active' ? 'paid' : 'pending',
          ativo: subscription.status === 'active',
        })
        .where(eq(doadores.id, doador.id));

        await db.insert(donorSubscriptions).values({
          userId,
          stripeCustomerId: customerId,
          stripeSubscriptionId: subscription.id,
          status: subscription.status,
          billingCycleAnchor: subscription.billing_cycle_anchor,
          currentPeriodStart: subscription.current_period_start,
          currentPeriodEnd: subscription.current_period_end,
          planPriceId: subscription.items.data[0].price.id,
          planName: `R$ ${monthlyAmount} / ${
            interval === 1 ? "mês" : `${interval} meses`
          }`,
          defaultPaymentMethod: defaultPaymentMethod,
        });

        res.json({
          success: true,
          subscription: {
            id: subscription.id,
            status: subscription.status,
            customerId,
            amount: monthlyAmount,
            interval,
            currentPeriodEnd: new Date(subscription.current_period_end * 1000),
            nextBillingDate: new Date(subscription.current_period_end * 1000),
          },
          message: `Subscription criada com sucesso! Próxima cobrança: ${new Date(
            subscription.current_period_end * 1000
          ).toLocaleDateString("pt-BR")}`,
        });
      } catch (error: any) {
        console.error("❌ [MANUAL SUB] Error:", error);
        res.status(500).json({
          error: error.message,
          details: error.raw?.message || error.toString(),
        });
      }
    }
  );

  // Force immediate billing for a subscription
  app.post("/api/admin/force-billing/:doadorId", async (req, res) => {
    try {
      const { doadorId } = req.params;

      // Buscar doador e usuário separadamente (apenas campos que existem)
      const [doador] = await db
        .select({
          id: doadores.id,
          userId: doadores.userId,
          stripeSubscriptionId: doadores.stripeSubscriptionId,
        })
        .from(doadores)
        .where(eq(doadores.id, parseInt(doadorId)))
        .limit(1);

      if (!doador || !doador.stripeSubscriptionId) {
        return res.status(404).json({ error: "Doador sem subscription ID" });
      }

      const [user] = await db
        .select()
        .from(users)
        .where(eq(users.id, doador.userId))
        .limit(1);

      console.log(
        `💳 [FORCE BILLING] Cobrando doador ${user?.nome} (${doador.id})...`
      );

      // Fetch subscription from Stripe to get the correct customer ID and billing info
      const subscription = await stripe.subscriptions.retrieve(
        doador.stripeSubscriptionId
      );
      const correctCustomerId =
        typeof subscription.customer === "string"
          ? subscription.customer
          : subscription.customer.id;

      console.log(
        `🔍 [FORCE BILLING] Customer correto do Stripe: ${correctCustomerId}`
      );
      console.log(
        `🔍 [FORCE BILLING] Status da subscription: ${subscription.status}`
      );

      // Check if subscription is active
      if (subscription.status !== "active") {
        return res.status(400).json({
          error: `Subscription está ${subscription.status}, não pode ser cobrada.`,
          status: subscription.status,
        });
      }

      // Validação de ciclo de cobrança
      const currentPeriodEnd = subscription.current_period_end * 1000; // Convert to milliseconds
      const now = Date.now();
      const intervalCount =
        subscription.items.data[0]?.plan.interval_count || 1;
      const interval = subscription.items.data[0]?.plan.interval || "month";

      // Calcular meses do intervalo
      let intervalMonths = intervalCount;
      if (interval === "year") {
        intervalMonths = intervalCount * 12;
      } else if (interval === "month") {
        intervalMonths = intervalCount;
      }

      const cicloNome =
        intervalMonths === 1
          ? "Mensal"
          : intervalMonths === 3
          ? "Trimestral"
          : intervalMonths === 6
          ? "Semestral"
          : intervalMonths === 12
          ? "Anual"
          : `${intervalMonths} meses`;

      console.log(
        `📅 [FORCE BILLING] Ciclo: ${cicloNome} (${intervalMonths} meses)`
      );
      console.log(
        `📅 [FORCE BILLING] Próximo pagamento: ${new Date(
          currentPeriodEnd
        ).toLocaleDateString("pt-BR")}`
      );
      console.log(
        `📅 [FORCE BILLING] Hoje: ${new Date(now).toLocaleDateString("pt-BR")}`
      );

      // Bloquear cobrança antecipada para ciclos maiores que mensal
      if (intervalMonths > 1 && now < currentPeriodEnd) {
        const diasRestantes = Math.ceil(
          (currentPeriodEnd - now) / (1000 * 60 * 60 * 24)
        );
        return res.status(400).json({
          error: `Cobrança bloqueada: ciclo ${cicloNome} ainda não terminou.`,
          ciclo: cicloNome,
          proximoPagamento: new Date(currentPeriodEnd).toLocaleDateString(
            "pt-BR"
          ),
          diasRestantes: diasRestantes,
          mensagem: `Só é possível cobrar após ${new Date(
            currentPeriodEnd
          ).toLocaleDateString("pt-BR")} (faltam ${diasRestantes} dias)`,
        });
      }

      // Create an invoice for the subscription and charge immediately
      const invoice = await stripe.invoices.create({
        customer: correctCustomerId,
        subscription: doador.stripeSubscriptionId,
        auto_advance: true, // Automatically finalize and pay
      });

      console.log(`📄 [FORCE BILLING] Invoice criada: ${invoice.id}`);

      const paidInvoice = await stripe.invoices.pay(invoice.id);

      console.log(`✅ [FORCE BILLING] Invoice paga: ${paidInvoice.status}`);

      res.json({
        success: true,
        doadorId: doador.id,
        nome: user?.nome,
        ciclo: cicloNome,
        invoiceId: paidInvoice.id,
        amount: paidInvoice.amount_paid ? paidInvoice.amount_paid / 100 : 0,
        status: paidInvoice.status,
      });
    } catch (error: any) {
      console.error("❌ [FORCE BILLING] Erro:", error);
      res
        .status(500)
        .json({ error: error.message, details: error.raw?.message });
    }
  });

