  app.post("/auth/login-coordenador", async (req, res) => {
    try {
      const raw = String(req.body?.email || "").trim();
      if (!raw) return res.status(400).json({ error: "E-mail é obrigatório" });

      // normaliza
      const email = raw.toLowerCase();

      // busca coordenador ativo por email
      const [coord] = await db
        .select()
        .from(coordenadores)
        .where(
          and(ilike(coordenadores.email, email), eq(coordenadores.ativo, true))
        )
        .limit(1);

      if (!coord)
        return res.status(401).json({ error: "E-mail não autorizado" });

      // opcional: carregar dados do usuário vinculado
      let user: any = null;
      if (coord.userId) {
        const [u] = await db
          .select()
          .from(users)
          .where(eq(users.id, coord.userId))
          .limit(1);
        user = u || null;
      }

      return res.json({
        success: true,
        role: "coordenador",
        setor: coord.setor,
        redirectPath: coord.redirectPath, // já vem da tabela (vide sua screenshot)
        user: user
          ? {
              id: user.id,
              nome: user.nome || "Coordenador",
              email: user.email || email,
              telefone: user.telefone || "",
              papel: "coordenador",
              role: "coordenador",
            }
          : {
              id: 0,
              nome: "Coordenador",
              email,
              telefone: "",
              papel: "coordenador",
              role: "coordenador",
            },
      });
    } catch (e) {
      console.error(e);
      return res.status(500).json({ error: "Erro interno" });
    }
  });

 // Send login code via SMS
app.post("/api/send-login-code", async (req, res) => {
  try {
    const { telefone } = req.body;

    console.log(
      `📱 SEND LOGIN CODE - Phone: ${telefone}, Time: ${new Date().toISOString()}`
    );

    if (!telefone) {
      return res.status(400).json({ error: "Telefone é obrigatório" });
    }

    // Handle original test phone number
    if (telefone === "+5599999999999" || telefone.includes("99999999999")) {
      const codigo = "123456";
      verificationCodes.set(telefone, codigo);

      setTimeout(() => {
        verificationCodes.delete(telefone);
      }, 10 * 60 * 1000);

      return res.json({
        success: true,
        message: "Código de teste gerado",
        codigo: codigo,
      });
    }

    // 🔒 SECURITY CHECK: verificar se telefone está cadastrado
    let existingUser: any = null;

    try {
      const phoneForDB = telefone.replace(/\D/g, "");

      console.log(
        `🔍 SECURITY CHECK - Verificando se telefone ${phoneForDB} está cadastrado...`
      );

      existingUser = await storage.getUserByTelefone(phoneForDB);

      if (!existingUser) {
        console.log(
          `❌ SECURITY BLOCK - Telefone ${phoneForDB} não está cadastrado no sistema`
        );
        return res.status(401).json({
          error: "Telefone não cadastrado no sistema",
          message:
            "Este número não está registrado. Para se cadastrar, acesse a página inicial.",
        });
      }

      console.log(
        `✅ SECURITY OK - Telefone cadastrado para usuário: ${existingUser.nome} (ID: ${existingUser.id})`
      );
    } catch (dbError) {
      console.error("Erro ao verificar telefone no banco:", dbError);
      return res.status(500).json({ error: "Erro interno do servidor" });
    }

    // 🎯 INFLUENCIADOR: Não envia SMS, usa código do banco
    try {
      const phoneForInfluencer = telefone.replace(/\D/g, "");
      const phoneVariations = [
        phoneForInfluencer,
        phoneForInfluencer.startsWith("55")
          ? phoneForInfluencer
          : "55" + phoneForInfluencer,
        phoneForInfluencer.startsWith("55")
          ? phoneForInfluencer.substring(2)
          : phoneForInfluencer,
        "+" +
          (phoneForInfluencer.startsWith("55")
            ? phoneForInfluencer
            : "55" + phoneForInfluencer),
      ];

      const influencerCheck = await pool.query(
        `SELECT id, nome, influencer_code FROM users 
         WHERE influencer_code IS NOT NULL 
           AND influencer_code != ''
           AND (telefone = $1 OR telefone = $2 OR telefone = $3 OR telefone = $4)`,
        phoneVariations
      );

      if (influencerCheck.rows.length > 0) {
        const influencer = influencerCheck.rows[0];
        console.log(
          `🎯 [INFLUENCER] Detectado influenciador: ${influencer.nome} (ID: ${influencer.id})`
        );
        console.log(
          `🎯 [INFLUENCER] NÃO enviando SMS - código pré-definido será usado na verificação`
        );

        return res.json({
          success: true,
          message: "Digite seu código de acesso exclusivo",
          isInfluencer: true,
        });
      }
    } catch (influencerError) {
      console.log(
        "⚠️ [INFLUENCER] Erro ao verificar influenciador:",
        influencerError
      );
      // continua fluxo normal
    }

    // =====================================================
    // ✅ GATE: SEMPRE validar Stripe e NORMALIZAR banco
    // status no banco: paid | pending | canceled
    // =====================================================

    const userId = existingUser?.id;

    // 1) Puxa doadores (pega stripe ids)
    let doadorRow: any = null;
    try {
      const doadorQuery = await db
        .select({
          id: doadores.id,
          status: doadores.status,
          ativo: doadores.ativo,
          stripeCustomerId: doadores.stripeCustomerId,
          stripeSubscriptionId: doadores.stripeSubscriptionId,
          periodicidade: doadores.periodicidade,
          createdAt: doadores.createdAt,
          verificadoEm: doadores.verificadoEm,
        })
        .from(doadores)
        .where(eq(doadores.userId, userId))
        .orderBy(desc(doadores.createdAt))
        .limit(1);

      doadorRow = doadorQuery[0] || null;

      console.log("🔍 [LOGIN GATE] Banco (doadores) ->", {
        userId,
        found: !!doadorRow,
        status: doadorRow?.status,
        ativo: doadorRow?.ativo,
        stripeCustomerId: doadorRow?.stripeCustomerId,
        stripeSubscriptionId: doadorRow?.stripeSubscriptionId,
      });
    } catch (e: any) {
      console.log("⚠️ [LOGIN GATE] Falha ao checar doadores:", e.message);
      doadorRow = null;
    }

    const stripeCustomerId =
      doadorRow?.stripeCustomerId || existingUser?.stripeCustomerId || null;

    // Se não dá pra checar stripe, normaliza como canceled e bloqueia
    if (!stripeCustomerId || !stripe) {
      console.log(
        `⛔ [LOGIN GATE] Sem stripeCustomerId/Stripe (user ${userId}) -> bloqueando`
      );

      try {
        if (doadorRow?.id) {
          await db
            .update(doadores)
            .set({
              status: "canceled",
              ativo: false,
              verificadoEm: new Date(),
              updatedAt: new Date(),
              dataDesligamento: new Date(),
            } as any)
            .where(eq(doadores.id, doadorRow.id));
        } else {
          await db.insert(doadores).values({
            userId,
            plano: existingUser?.plano || "eco",
            valor: "0",
            stripeCustomerId: null,
            stripeSubscriptionId: null,
            status: "canceled",
            ativo: false,
            createdAt: new Date(),
            updatedAt: new Date(),
            verificadoEm: new Date(),
            dataDesligamento: new Date(),
          } as any);
        }
      } catch (e: any) {
        console.log("⚠️ [LOGIN GATE] Falha ao normalizar doadores:", e.message);
      }

      return res.status(402).json({
        success: false,
        error: "ASSINATURA_INEXISTENTE",
        reason: "SUBSCRIPTION_NOT_FOUND",
        message: "Não encontramos uma assinatura ativa para este número.",
      });
    }

    // 2) Stripe: buscar subs e decidir status
    let stripeDecision: {
      canLogin: boolean;
      dbStatus: "paid" | "pending" | "canceled";
      dbAtivo: boolean;
      reason: string;
      message: string;
      stripeSubId: string | null;
      stripeSubStatus: string | null;
      shouldSetDesligamento: boolean;
    } = {
      canLogin: false,
      dbStatus: "canceled",
      dbAtivo: false,
      reason: "SUBSCRIPTION_NOT_FOUND",
      message: "Não encontramos uma assinatura ativa para este número.",
      stripeSubId: null,
      stripeSubStatus: null,
      shouldSetDesligamento: true,
    };

    try {
      console.log(`🔍 [LOGIN GATE] Stripe check: customer=${stripeCustomerId}`);

      const subs = await stripe.subscriptions.list({
        customer: stripeCustomerId,
        status: "all",
        limit: 20,
      });

      // libera se active/trialing
      const activeSub = subs.data.find((s: any) =>
        ["active", "trialing"].includes(s.status)
      );

      if (activeSub) {
        stripeDecision = {
          canLogin: true,
          dbStatus: "paid",
          dbAtivo: true,
          reason: "SUBSCRIPTION_OK",
          message: "Assinatura ativa.",
          stripeSubId: activeSub.id,
          stripeSubStatus: activeSub.status,
          shouldSetDesligamento: false,
        };
      } else {
        // se existe alguma sub mas não ativa
        const anySub = subs.data[0] || null;

        if (!anySub) {
          stripeDecision = {
            canLogin: false,
            dbStatus: "canceled",
            dbAtivo: false,
            reason: "SUBSCRIPTION_NOT_FOUND",
            message: "Não encontramos uma assinatura para este número.",
            stripeSubId: null,
            stripeSubStatus: null,
            shouldSetDesligamento: true,
          };
        } else if (anySub.status === "paused") {
          stripeDecision = {
            canLogin: false,
            dbStatus: "pending",
            dbAtivo: false,
            reason: "SUBSCRIPTION_PAUSED",
            message: "Sua assinatura está pausada. Reative para continuar.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: false,
          };
        } else if (
          ["past_due", "incomplete", "incomplete_expired", "unpaid"].includes(
            anySub.status
          )
        ) {
          stripeDecision = {
            canLogin: false,
            dbStatus: "pending",
            dbAtivo: false,
            reason: "SUBSCRIPTION_PENDING",
            message: "Sua assinatura está pendente. Regularize para continuar.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: false,
          };
        } else if (anySub.status === "canceled") {
          stripeDecision = {
            canLogin: false,
            dbStatus: "canceled",
            dbAtivo: false,
            reason: "SUBSCRIPTION_CANCELED",
            message: "Sua assinatura foi cancelada. Reative para continuar.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: true,
          };
        } else {
          stripeDecision = {
            canLogin: false,
            dbStatus: "pending",
            dbAtivo: false,
            reason: "SUBSCRIPTION_PENDING",
            message: "Sua assinatura não está ativa no momento.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: false,
          };
        }
      }
    } catch (stripeErr: any) {
      console.log("⚠️ [LOGIN GATE] Stripe erro:", stripeErr.message);
      return res.status(503).json({
        success: false,
        error: "STRIPE_INDISPONIVEL",
        reason: "STRIPE_ERROR",
        message: "Erro ao validar assinatura. Tente novamente em instantes.",
      });
    }

    // 3) Normaliza banco SEMPRE com base na Stripe
    try {
      const baseUpdate: any = {
        stripeCustomerId: stripeCustomerId,
        stripeSubscriptionId: stripeDecision.stripeSubId,
        status: stripeDecision.dbStatus, // paid | pending | canceled
        ativo: stripeDecision.dbAtivo,
        verificadoEm: new Date(),
        updatedAt: new Date(),
      };

      if (stripeDecision.shouldSetDesligamento) {
        baseUpdate.dataDesligamento = new Date();
      } else {
        baseUpdate.dataDesligamento = null;
      }

      if (doadorRow?.id) {
        await db
          .update(doadores)
          .set(baseUpdate)
          .where(eq(doadores.id, doadorRow.id));
      } else {
        await db.insert(doadores).values({
          userId,
          plano: existingUser?.plano || "eco",
          valor: "0",
          stripeCustomerId: stripeCustomerId,
          stripeSubscriptionId: stripeDecision.stripeSubId,
          status: stripeDecision.dbStatus,
          ativo: stripeDecision.dbAtivo,
          createdAt: new Date(),
          updatedAt: new Date(),
          verificadoEm: new Date(),
          dataDesligamento: stripeDecision.shouldSetDesligamento
            ? new Date()
            : null,
        } as any);
      }

      await db
        .update(users)
        .set({
          stripeCustomerId: stripeCustomerId,
          stripeSubscriptionId: stripeDecision.stripeSubId,
          subscriptionStatus: stripeDecision.stripeSubStatus,
          ativo: stripeDecision.dbAtivo,
        } as any)
        .where(eq(users.id, userId));

      console.log("✅ [LOGIN GATE] Banco normalizado via Stripe:", {
        userId,
        dbStatus: stripeDecision.dbStatus,
        dbAtivo: stripeDecision.dbAtivo,
        stripeSubId: stripeDecision.stripeSubId,
        stripeSubStatus: stripeDecision.stripeSubStatus,
      });
    } catch (e: any) {
      console.log("⚠️ [LOGIN GATE] Falha ao atualizar banco:", e.message);
      // opcional: se quiser bloquear quando falhar update, aqui seria o lugar
    }

    // 4) Decide login
    if (!stripeDecision.canLogin) {
      return res.status(402).json({
        success: false,
        error:
          stripeDecision.dbStatus === "pending"
            ? "ASSINATURA_PENDENTE"
            : "ASSINATURA_INATIVA",
        reason: stripeDecision.reason,
        message: stripeDecision.message,
      });
    }

    // =====================================================
    // ✅ Só aqui gera e envia o código (assinatura OK)
    // =====================================================

    const codigo = Math.floor(100000 + Math.random() * 900000).toString();

    const phoneDigitsOnly = telefone.replace(/\D/g, "");
    const phoneWith55 = phoneDigitsOnly.startsWith("55")
      ? phoneDigitsOnly
      : "55" + phoneDigitsOnly;
    const phoneWithout55 = phoneDigitsOnly.startsWith("55")
      ? phoneDigitsOnly.substring(2)
      : phoneDigitsOnly;

    const allFormats = [
      telefone,
      phoneDigitsOnly,
      phoneWith55,
      phoneWithout55,
      "+" + phoneWith55,
      "+" + phoneDigitsOnly,
    ];

    allFormats.forEach((format) => {
      verificationCodes.set(format, codigo);
    });

    setTimeout(() => {
      allFormats.forEach((format) => {
        verificationCodes.delete(format);
      });
    }, 10 * 60 * 1000);

    try {
      let normalizedPhone = telefone.replace(/\D/g, "");
      if (!normalizedPhone.startsWith("55")) normalizedPhone = "55" + normalizedPhone;
      const twilioPhone = "+" + normalizedPhone;

      console.log(`📱 LOGIN SMS - Original: ${telefone}, Normalized: ${twilioPhone}`);
      console.log(`🔑 CÓDIGO GERADO: ${codigo}`);

      const client = getTwilioClient();
      await client.messages.create({
        body: `Seu código de acesso ao Clube do Grito é: ${codigo}`,
        from: process.env.TWILIO_PHONE_NUMBER || "+12345678901",
        to: twilioPhone,
      });

      console.log(`✅ LOGIN SMS SENT to ${twilioPhone} with code ${codigo}`);
      return res.json({ success: true, message: "Código enviado via SMS" });
    } catch (twilioError) {
      console.error("Twilio error:", twilioError);
      return res.json({
        success: true,
        message: "Código gerado (SMS indisponível)",
        codigo: codigo,
      });
    }
  } catch (error: any) {
    console.error("Error sending login code:", error);
    return res.status(500).json({ error: "Erro ao enviar código" });
  }
});


