  // Endpoint para verificar status real da assinatura no Stripe
  app.get("/api/users/:id/stripe-subscription-status", async (req, res) => {
    try {
      const userId = parseInt(req.params.id);
      console.log(
        `🔍 [SUBSCRIPTION STATUS] Verificando status para user ${userId}`
      );

      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      if (!user.stripeCustomerId) {
        console.log(
          `⚠️ [SUBSCRIPTION STATUS] User ${userId} não tem stripeCustomerId`
        );
        return res.json({
          hasSubscription: false,
          status: null,
          needsReactivation: false,
          message: "Usuário não tem conta no Stripe",
        });
      }

      const subscriptions = await stripe.subscriptions.list({
        customer: user.stripeCustomerId,
        limit: 10,
        expand: ["data.default_payment_method"],
      });

      console.log(
        `📋 [SUBSCRIPTION STATUS] User ${userId} tem ${subscriptions.data.length} assinaturas`
      );

      const activeSubscription = subscriptions.data.find((sub) =>
        ["active", "trialing"].includes(sub.status)
      );

      if (activeSubscription) {
        console.log(
          `✅ [SUBSCRIPTION STATUS] User ${userId} tem assinatura ativa: ${activeSubscription.status}`
        );
        return res.json({
          hasSubscription: true,
          status: activeSubscription.status,
          subscriptionId: activeSubscription.id,
          needsReactivation: false,
          currentPeriodEnd: activeSubscription.current_period_end,
          planAmount: activeSubscription.items.data[0]?.price?.unit_amount || 0,
          hasPaymentMethod: !!activeSubscription.default_payment_method,
        });
      }

      const problemSubscription = subscriptions.data.find((sub) =>
        ["past_due", "unpaid", "incomplete"].includes(sub.status)
      );

      if (problemSubscription) {
        console.log(
          `⚠️ [SUBSCRIPTION STATUS] User ${userId} tem problema de pagamento: ${problemSubscription.status}`
        );
        return res.json({
          hasSubscription: true,
          status: problemSubscription.status,
          subscriptionId: problemSubscription.id,
          needsReactivation: true,
          reactivationType: "payment_issue",
          message:
            problemSubscription.status === "past_due"
              ? "Sua assinatura está em atraso. Atualize seu método de pagamento."
              : "Há um problema com seu pagamento. Atualize seu cartão.",
          planAmount:
            problemSubscription.items.data[0]?.price?.unit_amount || 0,
        });
      }

      const canceledSubscription = subscriptions.data.find((sub) =>
        ["canceled", "incomplete_expired"].includes(sub.status)
      );

      if (canceledSubscription) {
        console.log(
          `❌ [SUBSCRIPTION STATUS] User ${userId} tem assinatura cancelada: ${canceledSubscription.status}`
        );
        return res.json({
          hasSubscription: false,
          status: canceledSubscription.status,
          subscriptionId: canceledSubscription.id,
          needsReactivation: true,
          reactivationType: "canceled",
          message:
            "Sua assinatura foi cancelada. Reative para continuar apoiando.",
          planAmount:
            canceledSubscription.items.data[0]?.price?.unit_amount || 0,
          canceledAt: canceledSubscription.canceled_at,
        });
      }

      console.log(
        `📭 [SUBSCRIPTION STATUS] User ${userId} não tem nenhuma assinatura`
      );
      return res.json({
        hasSubscription: false,
        status: null,
        needsReactivation: true,
        reactivationType: "none",
        message: "Você ainda não tem uma assinatura ativa.",
      });
    } catch (error: any) {
      console.error("❌ [SUBSCRIPTION STATUS] Erro:", error);
      res.status(500).json({ error: "Erro ao verificar status da assinatura" });
    }
  });

  // Endpoint para buscar múltiplos projetos apoiados baseado no plano do usuário
  app.get("/api/users/:id/supported-project", async (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Buscar plano atual do usuário
      const currentPlan =
        (await storage.getUserActiveDonationPlan(userId)) || "eco";

      // Buscar data da primeira doação do usuário para usar como período
      let period = "janeiro de 2025";
      try {
        const doadorResult = await db
          .select({
            dataDoacaoInicial: doadores.dataDoacaoInicial,
            dataCadastro: doadores.createdAt,
          })
          .from(doadores)
          .where(eq(doadores.userId, userId))
          .limit(1);

        if (doadorResult.length > 0) {
          const firstDate =
            doadorResult[0].dataDoacaoInicial || doadorResult[0].dataCadastro;
          if (firstDate) {
            const date = new Date(firstDate);
            const months = [
              "janeiro",
              "fevereiro",
              "março",
              "abril",
              "maio",
              "junho",
              "julho",
              "agosto",
              "setembro",
              "outubro",
              "novembro",
              "dezembro",
            ];
            const month = months[date.getMonth()];
            const year = date.getFullYear();
            period = `${month} de ${year}`;
          }
        }
      } catch (error) {
        console.log(
          `⚠️ [PROJETO APOIADO] Erro ao buscar data de doação: ${error}`
        );
        period = "janeiro de 2025"; // fallback
      }

      // Buscar dados do usuário para configurações específicas
      const user = await storage.getUser(userId);

      // Definição de todos os projetos disponíveis
      const allProjects = {
        culturaEsporte: {
          name: "Programa de Cultura e Esporte",
          description: "Transformando vidas através da cultura e esporte",
          period: period,
        },
        inclusaoProdutiva: {
          name: "Inclusão Produtiva",
          description: "Capacitação profissional e geração de renda",
          period: period,
        },
        favela3d: {
          name: "Favela 3D",
          description: "Mapeamento e urbanização de comunidades",
          period: period,
        },
        metodoGrito: {
          name: "Método Grito",
          description: "Metodologia completa de transformação social",
          period: period,
        },
      };

      // ✅ NOVA IMPLEMENTAÇÃO: Função para determinar projetos apoiados baseado no banco de dados
      const getSupportedProjects = async (
        userId: number,
        currentPlan: string,
        user: any
      ) => {
        try {
          // ✅ PRIORIDADE 1: Buscar projetos específicos do usuário no banco de dados
          const userProjects = await storage.getUserSupportedProjects(userId);

          if (userProjects && userProjects.length > 0) {
            console.log(
              `🎯 [DB PROJECTS] Usuário ${userId}: Encontrados projetos específicos no banco: [${userProjects.join(
                ", "
              )}]`
            );
            return userProjects.map(
              (projectKey) =>
                allProjects[projectKey as keyof typeof allProjects]
            );
          }

          // ✅ PRIORIDADE 2: Usar lógica baseada no plano (comportamento padrão)
          console.log(
            `🎯 [PLAN PROJECTS] Usuário ${userId}: Usando projetos baseados no plano "${currentPlan}"`
          );
          const planToProjects: { [key: string]: string[] } = {
            eco: ["culturaEsporte"],
            voz: ["culturaEsporte", "inclusaoProdutiva"],
            grito: ["culturaEsporte", "inclusaoProdutiva", "favela3d"],
            platinum: [
              "culturaEsporte",
              "inclusaoProdutiva",
              "favela3d",
              "metodoGrito",
            ],
          };

          const projectKeys = planToProjects[currentPlan] || planToProjects.eco;
          return projectKeys.map(
            (projectKey) => allProjects[projectKey as keyof typeof allProjects]
          );
        } catch (error) {
          console.error(
            `❌ [SUPPORTED PROJECTS] Erro ao buscar projetos para usuário ${userId}:`,
            error
          );
          // ✅ FALLBACK: Usar plano padrão em caso de erro
          const projectKeys = ["culturaEsporte"]; // plano eco
          return projectKeys.map(
            (projectKey) => allProjects[projectKey as keyof typeof allProjects]
          );
        }
      };

      const supportedProjects = await getSupportedProjects(
        userId,
        currentPlan,
        user
      );

      console.log(
        `🎯 [PROJETOS APOIADOS] Usuário ${userId} com plano "${currentPlan}" apoia ${
          supportedProjects.length
        } projeto(s): ${supportedProjects.map((p) => p.name).join(", ")}`
      );

      res.json({
        userId,
        currentPlan,
        supportedProject: supportedProjects[0] || null, // ✅ BACKWARD COMPATIBILITY: primeiro projeto para clientes antigos
        supportedProjects, // ✅ NOVA FUNCIONALIDADE: array completo de projetos
      });
    } catch (error: any) {
      console.error("Error getting user supported projects:", error);
      res.status(500).json({ error: "Erro ao buscar projetos apoiados" });
    }
  });

  // Endpoint para buscar dados de impacto dinâmicos baseados no valor real doado
  app.get("/api/users/:id/impact-data", async (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Buscar plano atual do usuário
      const currentPlan =
        (await storage.getUserActiveDonationPlan(userId)) || "eco";

      // Valores mensais baseados no plano
      const monthlyValues: { [key: string]: number } = {
        eco: 9.9,
        voz: 19.9,
        grito: 29.9,
        platinum: 31.0, // Plano Platinum mínimo = R$ 31/mês (qualquer valor acima de R$ 30)
      };

      // ✅ CORREÇÃO: Calcular valor REAL das doações efetivamente pagas
      const realDonationsTotal = await storage.getUserTotalDonations(userId);

      const currentDate = new Date();
      const currentMonth = currentDate.getMonth() + 1; // 1-12

      // ✅ Para plano Platinum, buscar valor real da última doação paga
      let monthlyContribution = monthlyValues[currentPlan] || monthlyValues.eco;
      if (currentPlan === "platinum") {
        const platinumDonation = await db
          .select({
            valor: doadores.valor,
          })
          .from(doadores)
          .where(
            and(
              eq(doadores.userId, userId),
              eq(doadores.plano, "platinum"),
              eq(doadores.status, "paid")
            )
          )
          .orderBy(desc(doadores.createdAt))
          .limit(1);

        if (platinumDonation.length > 0) {
          monthlyContribution = parseFloat(platinumDonation[0].valor);
          console.log(
            `🎯 [PLATINUM REAL] Usuário ${userId}: Valor real R$ ${monthlyContribution}`
          );
        }
      }

      // ✅ USAR VALOR REAL em vez de assumir 9 meses de doação
      const valueContributed = realDonationsTotal;
      const annualValue = monthlyContribution * 12;
      const valueRemaining = Math.max(0, annualValue - valueContributed);

      // ✅ Calcular progresso baseado no valor real doado vs meta anual
      const progressPercentage = Math.min(
        Math.round((valueContributed / annualValue) * 100),
        100
      );

      res.json({
        currentPlan,
        monthlyContribution,
        valueContributed,
        annualValue,
        valueRemaining,
        currentMonth,
        progressPercentage,
        realDonationsTotal, // ✅ Incluir valor real para transparência
      });
    } catch (error: any) {
      console.error("Error getting user impact data:", error);
      res
        .status(500)
        .json({ error: "Erro ao buscar dados de impacto do usuário" });
    }
  });

  // Resend verification code
  app.post("/api/resend-verification", async (req, res) => {
    try {
      const { telefone } = req.body;

      if (!telefone) {
        return res.status(400).json({ error: "Telefone é obrigatório" });
      }

      const user = await storage.getUserByTelefone(telefone);
      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Generate new verification code
      const verificationCode = Math.floor(
        100000 + Math.random() * 900000
      ).toString();

      try {
        // Try to send SMS via Twilio
        const client = getTwilioClient();
        await client.messages.create({
          body: `Seu código de verificação do Clube do Grito é: ${verificationCode}`,
          from: process.env.TWILIO_PHONE_NUMBER,
          to: `+55${telefone.replace(/\D/g, "")}`,
        });

        console.log(`SMS reenviado para ${telefone}: ${verificationCode}`);
      } catch (twilioError: any) {
        console.log(
          `DESENVOLVIMENTO - Código reenviado para ${telefone}: ${verificationCode}`
        );
        console.log("Erro Twilio:", twilioError.message);
      }

      // Update stored verification code
      verificationCodes.set(telefone, verificationCode);

      res.json({
        success: true,
        message: "Código de verificação reenviado",
        ...(process.env.NODE_ENV === "development" && {
          devCode: verificationCode,
        }),
      });
    } catch (error) {
      console.error("Error resending verification:", error);
      res.status(500).json({ error: "Erro ao reenviar código" });
    }
  });

