  // GET /api/admin/donors/subscription-report - Relatório completo de assinaturas
  app.get(
    "/api/admin/donors/subscription-report",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        console.log(
          "📊 [SUBSCRIPTION REPORT] Gerando relatório de assinaturas..."
        );

        const result = await db
          .select({
            id: doadores.id,
            userId: doadores.userId,
            nome: users.nome,
            email: users.email,
            telefone: users.telefone,
            plano: doadores.plano,
            valor: doadores.valor,
            stripeSubscriptionId: doadores.stripeSubscriptionId,
            stripePaymentIntentId: doadores.stripePaymentIntentId,
            status: doadores.status,
            ativo: doadores.ativo,
            dataDoacaoInicial: doadores.dataDoacaoInicial,
            createdAt: doadores.createdAt,
          })
          .from(doadores)
          .leftJoin(users, eq(doadores.userId, users.id))
          .where(and(eq(doadores.status, "paid"), eq(doadores.ativo, true)))
          .orderBy(desc(doadores.createdAt));

        const totalDoadores = result.length;
        const comSubscription = result.filter(
          (d) => d.stripeSubscriptionId !== null
        ).length;
        const semSubscription = totalDoadores - comSubscription;

        const doadoresComStatus = result.map((d) => ({
          ...d,
          hasRecurring: d.stripeSubscriptionId !== null,
        }));

        console.log(
          `✅ [SUBSCRIPTION REPORT] Total: ${totalDoadores}, Com subscription: ${comSubscription}, Sem subscription: ${semSubscription}`
        );

        res.json({
          totalDoadores,
          comSubscription,
          semSubscription,
          doadores: doadoresComStatus,
        });
      } catch (error) {
        console.error(
          "❌ [SUBSCRIPTION REPORT] Erro ao gerar relatório:",
          error
        );
        res.status(500).json({
          error: "Erro ao gerar relatório de assinaturas",
          details: error instanceof Error ? error.message : "Erro desconhecido",
        });
      }
    }
  );

  // =============================================================================
  // =============================================================================
  // =============================================================================
  // ENDPOINT DOADORES STATS - Dados empresariais completos do Stripe
  // =============================================================================
  app.get("/api/doadores/stats", async (req, res) => {
    try {
      // Parâmetro de filtro por mês (0 = Janeiro, 11 = Dezembro)
      const mesParam =
        req.query.mes !== undefined
          ? parseInt(req.query.mes as string)
          : undefined;
      const anoAtual = 2025;
      let inicioMes: number | undefined;
      let fimMes: number | undefined;

      if (mesParam !== undefined && mesParam >= 0 && mesParam <= 11) {
        const dataInicio = new Date(anoAtual, mesParam, 1);
        const dataFim = new Date(anoAtual, mesParam + 1, 0, 23, 59, 59);
        inicioMes = Math.floor(dataInicio.getTime() / 1000);
        fimMes = Math.floor(dataFim.getTime() / 1000);
        console.log(
          `📅 [DOADORES] Filtrando por mês ${
            mesParam + 1
          }/${anoAtual} (${dataInicio.toLocaleDateString(
            "pt-BR"
          )} - ${dataFim.toLocaleDateString("pt-BR")})`
        );
      }
      console.log("📊 [DOADORES] Buscando dados empresariais do Stripe...");

      if (!stripe) {
        return res.status(500).json({
          error: "Stripe não configurado",
          totalDoadores: 0,
        });
      }

      // Buscar subscriptions ativas, em teste, com pagamento pendente e canceladas
      const [activesSubs, trialingSubs, pastDueSubs, canceledSubs] =
        await Promise.all([
          stripe.subscriptions.list({
            status: "active",
            limit: 100,
            expand: ["data.customer", "data.items.data.price"],
          }),
          stripe.subscriptions.list({
            status: "trialing",
            limit: 100,
            expand: ["data.customer", "data.items.data.price"],
          }),
          stripe.subscriptions.list({
            status: "past_due",
            limit: 100,
            expand: ["data.customer", "data.items.data.price"],
          }),
          stripe.subscriptions.list({
            status: "canceled",
            limit: 100,
            expand: ["data.customer", "data.items.data.price"],
          }),
        ]);

      const allSubscriptions = [
        ...activesSubs.data,
        ...trialingSubs.data,
        ...pastDueSubs.data,
        ...canceledSubs.data,
      ];

      console.log(
        `✅ [DOADORES] ${activesSubs.data.length} active, ${trialingSubs.data.length} trialing, ${pastDueSubs.data.length} past_due, ${canceledSubs.data.length} canceled`
      );

      // Buscar dados locais dos usuários para complementar (email, telefone, nome)
      const localUsersData = await db
        .select({
          id: users.id,
          stripeCustomerId: users.stripeCustomerId,
          nome: users.nome,
          email: users.email,
          telefone: users.telefone,
          gritosTotal: users.gritosTotal,
        })
        .from(users)
        .where(isNotNull(users.stripeCustomerId));

      // Criar mapa para busca rápida
      const localUsersMap = new Map<
        string,
        {
          id: number;
          nome: string | null;
          email: string | null;
          telefone: string | null;
          gritosTotal: number | null;
        }
      >();
      localUsersData.forEach((u) => {
        if (u.stripeCustomerId) {
          localUsersMap.set(u.stripeCustomerId, {
            id: u.id,
            nome: u.nome,
            email: u.email,
            telefone: u.telefone,
            gritosTotal: u.gritosTotal,
          });
        }
      });

      console.log(
        `📊 [DOADORES] ${localUsersData.length} usuários locais com stripeCustomerId para cruzamento`
      );

      // Mapear para formato de doador - cruzando com dados locais
      const todosDoadoresRaw = allSubscriptions.map((sub) => {
        const customer = sub.customer as any;
        const customerId =
          typeof customer === "string"
            ? customer
            : customer?.id || sub.customer;
        const localUser = localUsersMap.get(customerId);

        const priceItem = sub.items.data[0];
        const valorTotal = priceItem?.price?.unit_amount
          ? priceItem.price.unit_amount / 100
          : 0;
        const interval = priceItem?.price?.recurring?.interval || "month";
        const intervalCount = priceItem?.price?.recurring?.interval_count || 1;
        // Calcular valor mensal real baseado na periodicidade
        let valor = valorTotal;
        if (interval === "month" && intervalCount > 1) {
          valor = valorTotal / intervalCount; // Ex: R$89,70 trimestral = R$29,90/mês
        } else if (interval === "year") {
          valor = valorTotal / 12; // Anual dividido por 12
        }

        // Determinar plano baseado no valor
        let plano = "eco";
        if (valor >= 30) plano = "platinum";
        else if (valor >= 20) plano = "grito";
        else if (valor > 10) plano = "voz";
        else plano = "eco";

        // Priorizar dados locais do banco de dados sobre dados do Stripe
        const finalName =
          localUser?.nome ||
          customer?.name ||
          customer?.email ||
          "Doador Anônimo";
        const finalEmail = localUser?.email || customer?.email || null;
        const finalPhone = localUser?.telefone || customer?.phone || null;

        return {
          customerId: customerId,
          id: customerId,
          name: finalName,
          email: finalEmail,
          phone: finalPhone,
          subscriptionId: sub.id,
          status: sub.status,
          valor: valor,
          valorTotal: valorTotal,
          intervalCount: intervalCount,
          plano: plano,
          interval: priceItem?.price?.recurring?.interval || "month",
          created: sub.created,
          createdDate: new Date(sub.created * 1000).toISOString(),
          currentPeriodStart: sub.current_period_start,
          currentPeriodEnd: sub.current_period_end,
          cancelAtPeriodEnd: sub.cancel_at_period_end,
          canceledAt: sub.canceled_at,
          gritos: localUser?.gritosTotal || 0,
          hasLocalUser: !!localUser,
        };
      });

      // DEDUPLICAR: Manter apenas a subscription mais recente por customer
      const doadoresPorCustomer = new Map<
        string,
        (typeof todosDoadoresRaw)[0]
      >();

      for (const doador of todosDoadoresRaw) {
        const existente = doadoresPorCustomer.get(doador.customerId);
        if (!existente || doador.created > existente.created) {
          doadoresPorCustomer.set(doador.customerId, doador);
        }
      }

      // Filtrar por período se mês foi especificado
      let doadoresAtivos = Array.from(doadoresPorCustomer.values()).filter(
        (d) => d.hasLocalUser
      );

      if (inicioMes !== undefined && fimMes !== undefined) {
        doadoresAtivos = doadoresAtivos.filter((d) => {
          // Assinatura criada antes ou durante o mês
          const criadaAntesFimMes = d.created <= fimMes;
          // Assinatura não cancelada ou cancelada depois do início do mês
          const naoCandeladaOuDepoisInicio =
            !d.canceledAt || d.canceledAt >= inicioMes;
          return criadaAntesFimMes && naoCandeladaOuDepoisInicio;
        });
        console.log(
          `📅 [DOADORES] Após filtro por período: ${doadoresAtivos.length} doadores`
        );
      }

      console.log(
        `📊 [DOADORES] Após filtro (só usuários do app): ${doadoresAtivos.length} doadores vinculados`
      );

      // ===== ESTATÍSTICAS EMPRESARIAIS =====

      // 1. Totais gerais
      const totalDoadores = doadoresAtivos.length;
      const arrecadacaoMensal = doadoresAtivos.reduce(
        (acc, d) => acc + d.valor,
        0
      );
      const doacaoMedia =
        totalDoadores > 0 ? arrecadacaoMensal / totalDoadores : 0;
      const arrecadacaoAnual = arrecadacaoMensal * 12;

      // 2. Distribuição por plano
      const porPlano: Record<string, { quantidade: number; valor: number }> = {
        "Eco (R$9,90)": { quantidade: 0, valor: 0 },
        "Voz (R$19,90)": { quantidade: 0, valor: 0 },
        "Grito (R$89,70)": { quantidade: 0, valor: 0 },
        "Platinum (R$30+)": { quantidade: 0, valor: 0 },
      };

      doadoresAtivos.forEach((d) => {
        if (d.valor <= 10) {
          porPlano["Eco (R$9,90)"].quantidade++;
          porPlano["Eco (R$9,90)"].valor += d.valor;
        } else if (d.valor <= 20) {
          porPlano["Voz (R$19,90)"].quantidade++;
          porPlano["Voz (R$19,90)"].valor += d.valor;
        } else if (d.valor < 30) {
          porPlano["Grito (R$89,70)"].quantidade++;
          porPlano["Grito (R$89,70)"].valor += d.valor;
        } else {
          porPlano["Platinum (R$30+)"].quantidade++;
          porPlano["Platinum (R$30+)"].valor += d.valor;
        }
      });

      // 3. Evolução mensal de adesões (por mês de criação)
      const mesesNomes = [
        "Jan",
        "Fev",
        "Mar",
        "Abr",
        "Mai",
        "Jun",
        "Jul",
        "Ago",
        "Set",
        "Out",
        "Nov",
        "Dez",
      ];
      const evolucaoMensal: Record<
        string,
        {
          novosDoadadores: number;
          valorTotal: number;
          acumuladoDoadores: number;
          acumuladoValor: number;
        }
      > = {};

      // Inicializar todos os meses do ano
      mesesNomes.forEach((mes) => {
        evolucaoMensal[mes] = {
          novosDoadadores: 0,
          valorTotal: 0,
          acumuladoDoadores: 0,
          acumuladoValor: 0,
        };
      });

      doadoresAtivos.forEach((d) => {
        const data = new Date(d.created * 1000);
        const mesIndex = data.getMonth();
        const mes = mesesNomes[mesIndex];
        evolucaoMensal[mes].novosDoadadores++;
        evolucaoMensal[mes].valorTotal += d.valor;
      });

      // Calcular acumulados
      let acumuladoDoadores = 0;
      let acumuladoValor = 0;
      mesesNomes.forEach((mes) => {
        acumuladoDoadores += evolucaoMensal[mes].novosDoadadores;
        acumuladoValor += evolucaoMensal[mes].valorTotal;
        evolucaoMensal[mes].acumuladoDoadores = acumuladoDoadores;
        evolucaoMensal[mes].acumuladoValor = acumuladoValor;
      });

      // 4. Distribuição por faixa de valor
      const distribuicaoPorValor: Record<string, number> = {
        "R$1-25": 0,
        "R$26-50": 0,
        "R$51-100": 0,
        "R$101-200": 0,
        "R$200+": 0,
      };

      doadoresAtivos.forEach((d) => {
        if (d.valor <= 25) distribuicaoPorValor["R$1-25"]++;
        else if (d.valor <= 50) distribuicaoPorValor["R$26-50"]++;
        else if (d.valor <= 100) distribuicaoPorValor["R$51-100"]++;
        else if (d.valor <= 200) distribuicaoPorValor["R$101-200"]++;
        else distribuicaoPorValor["R$200+"]++;
      });
      // 5. Status das assinaturas - buscar cancelados reais do banco
      // Só conta como cancelado quem NÃO tem nenhuma assinatura ativa
      let canceledFromDB: any[] = [];
      try {
        const canceledResult = await pool.query(`
          SELECT u.id, u.nome, u.telefone, u.email, u.plano, u.stripe_customer_id, u.motivo_cancelamento
          FROM users u
          WHERE u.subscription_status = 'canceled'
            AND u.stripe_customer_id IS NOT NULL
            AND NOT EXISTS (
              SELECT 1 FROM users u2 
              WHERE u2.stripe_customer_id = u.stripe_customer_id 
                AND u2.subscription_status IN ('active', 'trialing')
            )
          ORDER BY u.id
        `);
        canceledFromDB = canceledResult.rows;
      } catch (err) {
        console.log("⚠️ [DOADORES] Erro ao buscar cancelados do banco:", err);
      }

      const porStatus = {
        active: doadoresAtivos.filter((d) => d.status === "active").length,
        trialing: doadoresAtivos.filter((d) => d.status === "trialing").length,
        past_due: doadoresAtivos.filter((d) => d.status === "past_due").length,
        canceled: canceledFromDB.length,
      };

      // Lista de cancelados para exibição no dashboard
      const canceladosLista = canceledFromDB.map((u) => ({
        userId: u.id,
        id: u.id,
        nome: u.nome,
        telefone: u.telefone,
        email: u.email,
        plano: u.plano,
        status: "canceled",
      }));

      // 6. Taxa de retenção (doadores com mais de 1 mês)
      const agora = Date.now() / 1000;
      const doadoresAntigos = doadoresAtivos.filter(
        (d) => agora - d.created > 30 * 24 * 60 * 60
      );
      const taxaRetencao =
        totalDoadores > 0
          ? Math.round((doadoresAntigos.length / totalDoadores) * 100)
          : 0;

      // 7. Ticket médio e maior doador
      const maiorDoador = doadoresAtivos.reduce(
        (max, d) => (d.valor > max.valor ? d : max),
        { valor: 0, name: "" }
      );

      // 8. Projeção anual baseada no mês atual
      const mesAtual = new Date().getMonth();
      const mesesRestantes = 12 - mesAtual - 1;
      const projecaoAnual = arrecadacaoMensal * 12;

      console.log(
        `📊 [DOADORES] Total: ${totalDoadores}, Arrecadação: R$ ${arrecadacaoMensal.toFixed(
          2
        )}, Retenção: ${taxaRetencao}%`
      );

      res.json({
        // Totais
        totalDoadores,
        arrecadacaoMensal,
        doacaoMedia,
        arrecadacaoAnual,
        projecaoAnual,
        taxaRetencao,

        // Por status
        porStatus,

        // Por plano (para gráfico de pizza)
        porPlano: Object.entries(porPlano).map(([plano, dados]) => ({
          plano,
          quantidade: dados.quantidade,
          valor: dados.valor,
        })),

        // Evolução mensal (para gráfico de linha/barras)
        evolucaoMensal: mesesNomes.map((mes) => ({
          mes,
          novosDoadores: evolucaoMensal[mes].novosDoadadores,
          valorMensal: evolucaoMensal[mes].valorTotal,
          acumuladoDoadores: evolucaoMensal[mes].acumuladoDoadores,
          acumuladoValor: evolucaoMensal[mes].acumuladoValor,
        })),

        // Distribuição por valor (para gráfico de barras)
        distribuicaoPorValor: Object.entries(distribuicaoPorValor).map(
          ([faixa, quantidade]) => ({
            faixa,
            quantidade,
          })
        ),

        // Destaques
        maiorDoador: {
          nome: maiorDoador.name,
          valor: maiorDoador.valor,
        },

        // Lista completa de doadores (com telefone/email do banco de dados)
        doadores: [
          ...canceladosLista,
          ...(await Promise.all(
            doadoresAtivos
              .filter((d) => d.status !== "canceled")
              .map(async (d) => {
                // Buscar telefone e email do banco de dados Digital Ocean
                let telefoneDB = null;
                let emailDB = null;
                try {
                  const userResult = await pool.query(
                    `SELECT telefone, email FROM users WHERE stripe_customer_id = $1 LIMIT 1`,
                    [d.customerId]
                  );
                  if (userResult.rows.length > 0) {
                    telefoneDB = userResult.rows[0].telefone;
                    emailDB = userResult.rows[0].email;
                  }
                } catch (err) {
                  console.log(
                    `⚠️ [DOADORES] Erro ao buscar user para ${d.customerId}`
                  );
                }

                return {
                  id: d.id,
                  nome: d.name,
                  email: emailDB || d.email,
                  telefone: telefoneDB || d.phone,
                  valor: d.valor,
                  plano: d.plano,
                  valorTotal: d.valorTotal,
                  intervalCount: d.intervalCount,
                  periodicidade:
                    d.intervalCount === 1
                      ? "Mensal"
                      : d.intervalCount === 3
                      ? "Trimestral"
                      : d.intervalCount === 6
                      ? "Semestral"
                      : d.interval === "year"
                      ? "Anual"
                      : `${d.intervalCount}x`,
                  status: d.status,
                  dataAdesao: new Date(d.created * 1000).toLocaleDateString(
                    "pt-BR"
                  ),
                  gritos: d.gritos,
                  diasComoDoador: Math.floor(
                    (agora - d.created) / (24 * 60 * 60)
                  ),
                };
              })
          )),
        ],
      });
    } catch (error: any) {
      console.error("❌ [DOADORES] Erro ao buscar doadores do Stripe:", error);
      res.status(500).json({
        error: "Erro ao buscar doadores",
        message: error.message,
        totalDoadores: 0,
      });
    }
  });
  // =============================================================================
  // DOADORES EXTERNOS - Doadores que doam fora do aplicativo
  // =============================================================================
  app.get("/api/doadores-externos", async (req, res) => {
    try {
      console.log(
        "📊 [DOADORES EXTERNOS] Buscando doadores externos do banco DO..."
      );
      // Parâmetro de filtro por mês (0 = Janeiro, 11 = Dezembro)
      const mesParam =
        req.query.mes !== undefined
          ? parseInt(req.query.mes as string)
          : undefined;
      const anoAtual = 2025;
      let whereClause = "ativo = true";

      if (mesParam !== undefined && mesParam >= 0 && mesParam <= 11) {
        const dataInicio = new Date(anoAtual, mesParam, 1);
        const dataFim = new Date(anoAtual, mesParam + 1, 0);
        whereClause += ` AND (data_inicio IS NULL OR data_inicio <= '${
          dataFim.toISOString().split("T")[0]
        }')`;
        console.log(
          `📅 [DOADORES EXTERNOS] Filtrando por mês ${mesParam + 1}/${anoAtual}`
        );
      }

      // Buscar do banco Digital Ocean
      const doadoresExternosList = await pool.query(
        `SELECT * FROM doadores_externos WHERE ${whereClause} ORDER BY valor_mensal DESC`
      );
      const doadores = doadoresExternosList.rows || [];

      // Calcular totais
      const totalDoadores = doadores.length;
      const arrecadacaoMensal = doadores.reduce(
        (acc: number, d: any) => acc + parseFloat(d.valor_mensal || 0),
        0
      );
      const doacaoMedia =
        totalDoadores > 0 ? arrecadacaoMensal / totalDoadores : 0;

      console.log(
        `✅ [DOADORES EXTERNOS] ${totalDoadores} doadores, R$ ${arrecadacaoMensal.toFixed(
          2
        )}/mês`
      );

      res.json({
        success: true,
        totalDoadores,
        arrecadacaoMensal,
        doacaoMedia,
        doadores: doadores.map((d: any) => ({
          id: d.id,
          nome: d.nome,
          valorMensal: parseFloat(d.valor_mensal),
          formaPagamento: d.forma_pagamento || "pix",
          observacao: d.observacao,
          dataInicio: d.data_inicio
            ? new Date(d.data_inicio).toLocaleDateString("pt-BR")
            : null,
          status: d.status,
          ativo: d.ativo,
        })),
      });
    } catch (error: any) {
      console.error("❌ [DOADORES EXTERNOS] Erro:", error);
      res.status(500).json({
        success: false,
        error: "Erro ao buscar doadores externos",
        message: error.message,
      });
    }
  });

