  // ========= COLABORADORES STATS =========
  app.get("/api/colaboradores/stats", async (req, res) => {
    try {
      const mesParam =
        req.query.mes !== undefined
          ? parseInt(req.query.mes as string)
          : undefined;
      const anoAtual = 2025;
      const result = await pool.query(
        "SELECT * FROM colaboradores WHERE ativo = true"
      );
      let colaboradoresList = result.rows || [];
      if (mesParam !== undefined && mesParam >= 0 && mesParam <= 11) {
        const dataFimMes = new Date(anoAtual, mesParam + 1, 0);
        const dataInicioMes = new Date(anoAtual, mesParam, 1);
        colaboradoresList = colaboradoresList.filter((c: any) => {
          const dataAdmissao = c.data_admissao
            ? new Date(c.data_admissao)
            : c.created_at
            ? new Date(c.created_at)
            : new Date(0);
          const dataDesligamento = c.data_desligamento
            ? new Date(c.data_desligamento)
            : null;
          const admitidoAntesOuDuranteMes = dataAdmissao <= dataFimMes;
          const naoDesligadoAntes =
            !dataDesligamento || dataDesligamento >= dataInicioMes;
          return admitidoAntesOuDuranteMes && naoDesligadoAntes;
        });
        console.log(
          `📅 [COLABORADORES] Filtrado por mês ${mesParam + 1}/${anoAtual}: ${
            colaboradoresList.length
          }`
        );
      }
      const distribuicao = colaboradoresList.reduce((acc: any, c: any) => {
        const dept = c.departamento || "Outros";
        if (!acc[dept]) acc[dept] = 0;
        acc[dept]++;
        return acc;
      }, {});
      const distribuicaoArray = Object.entries(distribuicao).map(
        ([name, value]) => ({ name, value })
      );
      res.json({
        total: colaboradoresList.length,
        totalColaboradores: colaboradoresList.length,
        distribuicao: distribuicaoArray,
        items: colaboradoresList.map((c: any) => ({
          id: c.id,
          nome: c.nome,
          telefone: c.telefone,
          email: c.email,
          departamento: c.departamento,
          satisfacao: c.satisfacao,
          ativo: c.ativo,
          dataAdmissao: c.data_admissao,
          dataDesligamento: c.data_desligamento,
          createdAt: c.created_at,
        })),
      });
    } catch (error: any) {
      console.error("❌ [COLABORADORES] Erro:", error);
      res.status(500).json({
        error: "Erro ao buscar colaboradores",
        message: error.message,
      });
    }
  });

  app.get("/api/colaboradores", async (req, res) => {
    try {
      const page = parseInt(req.query.page as string) || 1;
      const pageSize = parseInt(req.query.pageSize as string) || 10;
      const offset = (page - 1) * pageSize;
      const mesParam =
        req.query.mes !== undefined
          ? parseInt(req.query.mes as string)
          : undefined;
      const anoAtual = 2025;
      const result = await pool.query(
        "SELECT * FROM colaboradores WHERE ativo = true ORDER BY nome"
      );
      let colaboradoresList = result.rows || [];
      if (mesParam !== undefined && mesParam >= 0 && mesParam <= 11) {
        const dataFimMes = new Date(anoAtual, mesParam + 1, 0);
        const dataInicioMes = new Date(anoAtual, mesParam, 1);
        colaboradoresList = colaboradoresList.filter((c: any) => {
          const dataAdmissao = c.data_admissao
            ? new Date(c.data_admissao)
            : c.created_at
            ? new Date(c.created_at)
            : new Date(0);
          const dataDesligamento = c.data_desligamento
            ? new Date(c.data_desligamento)
            : null;
          const admitidoAntesOuDuranteMes = dataAdmissao <= dataFimMes;
          const naoDesligadoAntes =
            !dataDesligamento || dataDesligamento >= dataInicioMes;
          return admitidoAntesOuDuranteMes && naoDesligadoAntes;
        });
      }
      const total = colaboradoresList.length;
      const paginatedList = colaboradoresList.slice(offset, offset + pageSize);
      res.json({
        total,
        items: paginatedList.map((c: any) => ({
          id: c.id,
          nome: c.nome,
          telefone: c.telefone,
          email: c.email,
          departamento: c.departamento,
          satisfacao: c.satisfacao,
          ativo: c.ativo,
        })),
      });
    } catch (error: any) {
      console.error("❌ [COLABORADORES] Erro:", error);
      res.status(500).json({
        error: "Erro ao buscar colaboradores",
        message: error.message,
      });
    }
  });

  // Update user profile
  app.put("/api/update-profile", async (req, res) => {
    try {
      const { telefone, nome, novoTelefone } = req.body;

      if (!telefone || !nome) {
        return res
          .status(400)
          .json({ error: "Telefone e nome são obrigatórios" });
      }

      // Get current user
      const user = await storage.getUserByTelefone(telefone);
      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Update user name
      const updatedUser = await storage.createOrUpdateUser({
        cpf: user.cpf || "00000000000", // Use existing CPF or placeholder
        nome,
        sobrenome: user.sobrenome,
        email: user.email,
        telefone: novoTelefone || telefone,
        plano: user.plano,
      });

      res.json({
        success: true,
        message: "Perfil atualizado com sucesso",
        user: {
          nome: updatedUser.nome,
          telefone: updatedUser.telefone,
          email: updatedUser.email,
        },
      });
    } catch (error: any) {
      console.error("Error updating profile:", error);
      res.status(500).json({ error: "Erro ao atualizar perfil" });
    }
  });

