  // POST /api/monitor/inclusao/participantes - Criar novo participante de Inclusão
  app.post("/api/monitor/inclusao/participantes", requireAuth, requireMonitor, async (req, res) => {
    try {
      const user = (req as any).user;
      const { turmaIds, ...participanteData } = req.body;

      console.log(`📝 [MONITOR INCLUSÃO] Monitor ${user.id} criando novo participante: ${participanteData.nome}`);

      if (!participanteData.nome || !participanteData.genero || !participanteData.idade) {
        return res.status(400).json({ 
          error: "Campos obrigatórios: nome, genero, idade" 
        });
      }

      if (participanteData.dataIngresso) {
        participanteData.dataIngresso = new Date(participanteData.dataIngresso)
      }

      // Converter dataEntrada para Date se for string
      if (participanteData.dataEntrada && typeof participanteData.dataEntrada === 'string') {
        participanteData.dataEntrada = new Date(participanteData.dataEntrada);
      }

      // Normalizar campos JSONB que vêm como strings vazias ou "[]"
      const jsonbArrayFields = [
        'telefonesAdicionais', 'contatosEmergencia', 'documentosPossui', 
        'demandas', 'turnoEscolar', 'trabalhosAtuais', 'experienciasProfissionais',
        'jaTeveOuCostumaTer', 'relacionamentosFamiliares', 'outrosRelacionamentos'
      ];
      jsonbArrayFields.forEach(field => {
        if (participanteData[field] === '[]' || participanteData[field] === '') {
          participanteData[field] = [];
        } else if (typeof participanteData[field] === 'string') {
          try {
            participanteData[field] = JSON.parse(participanteData[field]);
          } catch (e) {
            participanteData[field] = [];
          }
        }
      });

      ['email', 'cpf', 'telefone', 'codigoMatricula', 'identificador', 'dataIngresso', 'dataEntrada'].forEach(field => {
        if (participanteData[field] === '') {
          participanteData[field] = null;
        }
      });

      const validationResult = insertParticipanteInclusaoSchema.safeParse({
        ...participanteData,
        coordenadorId: user.id
      });

      if (!validationResult.success) {
        return res.status(400).json({
          error: "Dados inválidos",
          details: validationResult.error.errors
        });
      }

      const participante = await storage.createParticipante(validationResult.data, turmaIds);

      try {
        const vinculoExistente = await db.select()
          .from(psicoInclusaoVinculo)
          .where(eq(psicoInclusaoVinculo.participanteInclusaoId, participante.id))
          .limit(1);

        if (vinculoExistente.length === 0) {
          const [novaFamilia] = await db.insert(psicoFamilias).values({
            nomeResponsavel: participante.nome,
            numeroMembros: 1,
            telefone: participante.telefone || null,
            endereco: participante.endereco || null,
            status: 'ativo',
            coordenadorId: user.id,
            observacoes: `Família criada automaticamente - Monitor Inclusão: ${participante.nome}`
          }).returning();

          await db.insert(psicoInclusaoVinculo).values({
            participanteInclusaoId: participante.id,
            psicoFamiliaId: novaFamilia.id,
            papel: 'atendido',
            observacoes: 'Vínculo criado automaticamente ao cadastrar participante via Monitor'
          });

          console.log(`✅ [MONITOR INCLUSÃO→PSICO] Participante ${participante.id} vinculado à família ${novaFamilia.id}`);
        }
      } catch (vinculoError) {
        console.error('⚠️ [MONITOR INCLUSÃO→PSICO] Erro ao criar vínculo automático:', vinculoError);
      }

      console.log(`✅ [MONITOR INCLUSÃO] Participante criado com sucesso: ID ${participante.id}`);
      res.status(201).json(participante);
    } catch (error: any) {
      console.error("❌ [MONITOR INCLUSÃO] Erro ao criar participante:", error);
      res.status(500).json({ error: "Erro ao criar participante: " + error.message });
    }
  });


