  // GET /api/monitor/:monitorId/alunos - Lista alunos do monitor
  // GET /api/monitor/:monitorId/alunos - Lista alunos do monitor (PEC e Inclusão Produtiva)
  app.get("/api/monitor/:monitorId/alunos", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const user = (req as any).user;
      const programType = req.query.programType as string; // 'pec', 'inclusao' ou undefined (todos)

        const access = ensureSelfAccess(user, monitorId, "alunos");
        if (!access.allowed) {
          return res
            .status(access.error!.status)
            .json({ error: access.error!.message });
        }

        console.log(
          `📚 [MONITOR ALUNOS] Buscando alunos do monitor ${monitorId}, programa: ${
            programType || "todos"
          }`
        );

        // Buscar os participantes vinculados ao monitor com JOIN para ambas as fontes
        const alunosData = await db
          .select({
            id: monitorParticipantes.id,
            programType: monitorParticipantes.programType,

            // Dados de Inclusão Produtiva
            inclusaoId: monitorParticipantes.inclusaoParticipanteId,
            inclusaoNome: participantesInclusao.nome,
            inclusaoPrograma: participantesInclusao.programaAtual,

            // Dados de PEC
            pecCpf: monitorParticipantes.pecAlunoCpf,
            pecNome: aluno.nome_completo,
            pecMatricula: aluno.numero_matricula,

            // Campos de acompanhamento
            observacoesPrivadas: monitorParticipantes.observacoesPrivadas,
            acompanhamentoStatus: monitorParticipantes.acompanhamentoStatus,
            ultimaInteracao: monitorParticipantes.ultimaInteracao,
          })
          .from(monitorParticipantes)
          .leftJoin(
            participantesInclusao,
            eq(
              monitorParticipantes.inclusaoParticipanteId,
              participantesInclusao.id
            )
          )
          .leftJoin(aluno, eq(monitorParticipantes.pecAlunoCpf, aluno.cpf))
          .where(
            and(
              eq(monitorParticipantes.monitorUserId, monitorId),
              programType
                ? eq(monitorParticipantes.programType, programType)
                : undefined
            )
          );

        // Normalizar dados: unificar campos de ambas as fontes
        const alunosNormalizados = alunosData.map((aluno) => {
          const isPec = aluno.programType === "pec";

          return {
            id: aluno.id,
            programType: aluno.programType,
            studentId: isPec ? aluno.pecCpf : aluno.inclusaoId,
            nome: isPec ? aluno.pecNome : aluno.inclusaoNome,
            grupo: isPec ? aluno.pecMatricula : aluno.inclusaoPrograma,
            observacoesPrivadas: aluno.observacoesPrivadas,
            acompanhamentoStatus: aluno.acompanhamentoStatus,
            ultimaInteracao: aluno.ultimaInteracao,
            frequencia: 0, // TODO: calcular frequência por programa
          };
        });

        console.log(
          `✅ [MONITOR ALUNOS] ${alunosNormalizados.length} alunos encontrados para monitor ${monitorId}`
        );
        res.json(alunosNormalizados);
      } catch (error: any) {
        console.error("❌ [MONITOR ALUNOS] Erro ao buscar alunos:", error);
        res
          .status(500)
          .json({ error: "Falha ao buscar alunos: " + error.message });
      }
    }
  );

  // PATCH /api/monitor/alunos/:id - Atualizar informações de acompanhamento de aluno
  app.patch(
    "/api/monitor/alunos/:id",
    requireAuth,
    requireMonitor,
    async (req, res) => {
      try {
        const monitorParticipanteId = parseInt(req.params.id);
        const user = (req as any).user;

        console.log(
          `📝 [MONITOR ALUNOS] Monitor ${user.id} atualizando registro ${monitorParticipanteId}`
        );

        // Validar body com schema
        const validationResult = updateMonitorParticipanteSchema.safeParse(
          req.body
        );
        if (!validationResult.success) {
          console.warn(
            `⚠️ [MONITOR ALUNOS] Validação falhou:`,
            validationResult.error
          );
          return res.status(400).json({
            error: "Dados inválidos",
            details: validationResult.error.errors,
          });
        }

        const updateData = validationResult.data;

        // Verificar se o registro existe e pertence ao monitor autenticado
        const existingRecord = await db
          .select()
          .from(monitorParticipantes)
          .where(eq(monitorParticipantes.id, monitorParticipanteId))
          .limit(1);

        if (!existingRecord || existingRecord.length === 0) {
          console.warn(
            `⚠️ [MONITOR ALUNOS] Registro ${monitorParticipanteId} não encontrado`
          );
          return res.status(404).json({ error: "Registro não encontrado" });
        }

        if (existingRecord[0].monitorUserId !== user.id) {
          console.warn(
            `🚨 [SECURITY] Monitor ${user.id} tentou atualizar registro de outro monitor`
          );
          return res.status(403).json({
            error: "Acesso negado - este registro não pertence a você",
          });
        }

      // Atualizar o registro
      const updated = await db
        .update(monitorParticipantes)
        .set({
          ...updateData,
          updatedAt: new Date(),
        })
        .where(eq(monitorParticipantes.id, monitorParticipanteId))
        .returning();

        console.log(
          `✅ [MONITOR ALUNOS] Registro ${monitorParticipanteId} atualizado com sucesso`
        );
        res.json(updated[0]);
      } catch (error: any) {
        console.error("❌ [MONITOR ALUNOS] Erro ao atualizar registro:", error);
        res
          .status(500)
          .json({ error: "Falha ao atualizar registro: " + error.message });
      }
    }
  );

  // POST /api/monitor/:monitorId/alunos - Assign aluno to monitor
  app.post("/api/monitor/:monitorId/alunos", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'alunos');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      const { participanteId } = req.body;
      
      // Check if already assigned
      const existing = await db.select()
        .from(monitorParticipantes)
        .where(eq(monitorParticipantes.participanteId, participanteId))
        .limit(1);
      
      if (existing.length > 0) {
        return res.status(400).json({ error: 'Participante já atribuído' });
      }
      
      const newAssignment = await db.insert(monitorParticipantes)
        .values({
          monitorUserId: monitorId,
          participanteId: participanteId,
          acompanhamentoStatus: 'ativo',
          observacoesPrivadas: ''
        })
        .returning();
      
      console.log(`[RBAC MONITOR] Aluno ${participanteId} atribuido ao monitor ${monitorId}`);
      res.json(newAssignment[0]);
    } catch (error: any) {
      console.error("Error assigning aluno:", error);
      res.status(500).json({ error: "Failed to assign aluno" });
    }
  });

  // GET /api/monitor/:monitorId/participantes-disponiveis - List unassigned participantes
  app.get("/api/monitor/:monitorId/participantes-disponiveis", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'participantes-disponiveis');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      // Get participantes not assigned to this monitor
      const allParticipantes = await db.select({
        id: participantesInclusao.id,
        nome: participantesInclusao.nome,
        grupo: participantesInclusao.programaAtual
      })
      .from(participantesInclusao)
      .orderBy(participantesInclusao.nome);
      
      // Get already assigned IDs
      const assignedIds = await db.select({ id: monitorParticipantes.participanteId })
        .from(monitorParticipantes)
        .where(eq(monitorParticipantes.monitorUserId, monitorId));
      
      const assignedSet = new Set(assignedIds.map(a => a.id));
      const available = allParticipantes.filter(p => !assignedSet.has(p.id));
      
      res.json(available);
    } catch (error: any) {
      console.error("Error fetching available participantes:", error);
      res.status(500).json({ error: "Failed to fetch participantes" });
    }

  });
  // GET /api/monitor/:monitorId/atividades - List monitor's activities
  app.get("/api/monitor/:monitorId/atividades", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const vertente = req.query.vertente as string | undefined;
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'atividades');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      // Buscar atividades da tabela atividadesMonitor
      const atividadesLegacy = await db.select()
        .from(atividadesMonitor)
        .where(vertente 
          ? and(eq(atividadesMonitor.monitorUserId, monitorId), eq(atividadesMonitor.vertente, vertente)) 
          : eq(atividadesMonitor.monitorUserId, monitorId))
        .orderBy(desc(atividadesMonitor.data));
      
      // Se vertente for 'pec', também buscar sessões da tabela sessions
      if (vertente === 'pec') {
        const staffAssigns = await db.select({
          instanceId: staffAssignments.activity_instance_id,
          instanceTitle: activityInstances.title
        })
          .from(staffAssignments)
          .innerJoin(activityInstances, eq(staffAssignments.activity_instance_id, activityInstances.id))
          .where(eq(staffAssignments.person_id, monitorId));
        
        const pecInstanceIds = staffAssigns.map(s => s.instanceId);
        
        let pecSessions: any[] = [];
        if (pecInstanceIds.length > 0) {
          pecSessions = await db.select().from(sessions)
            .where(inArray(sessions.activity_instance_id, pecInstanceIds))
            .orderBy(desc(sessions.date));
        }
        
        // Filtrar para excluir chamadas
        pecSessions = pecSessions.filter(s => !s.title?.startsWith("Chamada"));
        
        // Converter sessões para formato compatível
        const atividadesSessions = pecSessions.map(sess => {
          const instance = staffAssigns.find(s => s.instanceId === sess.activity_instance_id);
          return {
            id: sess.id,
            monitorUserId: monitorId,
            titulo: sess.title || 'Atividade - ' + (instance?.instanceTitle || ''),
            descricao: sess.description,
            data: sess.date,
            horarioInicio: null,
            horarioFim: null,
            tipo: 'aula',
            local: sess.location,
            vertente: 'pec',
            turmaId: sess.activity_instance_id,
            turmaNome: instance?.instanceTitle,
            criadoEm: sess.createdAt,
            source: 'sessions'
          };
        });
        
        // Combinar e ordenar por data
        const todasAtividades = [...atividadesLegacy, ...atividadesSessions].sort((a, b) => {
          const dateA = new Date(a.data || 0).getTime();
          const dateB = new Date(b.data || 0).getTime();
          return dateB - dateA;
        });
        
        return res.json(todasAtividades);
      }
      
      res.json(atividadesLegacy);
    } catch (error: any) {
      console.error("Error fetching atividades:", error);
      res.status(500).json({ error: "Failed to fetch atividades" });
    }
  });

  // POST /api/monitor/:monitorId/atividades - Create new activity
  app.post("/api/monitor/:monitorId/atividades", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const vertente = req.query.vertente as string | undefined;
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'atividades');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      // Se vertente for 'pec', criar sessão na tabela sessions
      if (vertente === 'pec') {
        const { titulo, descricao, data, turmaId, local, horarioInicio, horarioFim } = req.body;
        
        if (!turmaId) {
          return res.status(400).json({ error: 'turmaId é obrigatório para atividades PEC' });
        }
        
        // Calcular horas se horários fornecidos
        let hours = "2.00";
        if (horarioInicio && horarioFim) {
          const inicio = new Date(`1970-01-01T${horarioInicio}:00`);
          const fim = new Date(`1970-01-01T${horarioFim}:00`);
          const diff = (fim.getTime() - inicio.getTime()) / (1000 * 60 * 60);
          hours = diff.toFixed(2);
        }
        
        const [session] = await db.insert(sessions).values({
          activity_instance_id: turmaId,
          date: data,
          hours: hours,
          title: titulo,
          description: descricao || '',
          observations: '',
          status: 'realizado',
          location: local
        }).returning();
        
        console.log(`[RBAC MONITOR] Atividade PEC criada por monitor ${monitorId} para turma ${turmaId}`);
        return res.json({
          id: session.id,
          monitorUserId: monitorId,
          titulo: session.title,
          descricao: session.description,
          data: session.date,
          vertente: 'pec',
          turmaId: session.activity_instance_id
        });
      }
      
      // Caso contrário, criar na tabela atividadesMonitor (legacy)
      const dataConverted = req.body.data ? new Date(req.body.data) : undefined;

      const validated = insertAtividadeMonitorSchema.parse({
        ...req.body,
        data: dataConverted,
        monitorUserId: monitorId,
        vertente: vertente || req.body.vertente
      });
      
      const newAtividade = await db.insert(atividadesMonitor)
        .values(validated)
        .returning();
      
      console.log(`[RBAC MONITOR] Atividade criada por monitor ${monitorId}`);
      res.json(newAtividade[0]);
    } catch (error: any) {
      console.error("Error creating atividade:", error);
      res.status(500).json({ error: "Failed to create atividade" });
    }
  });

  // PUT /api/monitor/atividades/:atividadeId - Update activity
  app.put("/api/monitor/atividades/:atividadeId", requireAuth, requireMonitor, async (req, res) => {
    try {
      const atividadeId = parseInt(req.params.atividadeId);
      const user = (req as any).user;
      const { titulo, descricao, data, horarioInicio, horarioFim, tipo, local } = req.body;
      
      // Verificar se a atividade existe
      const [atividade] = await db.select()
        .from(atividadesMonitor)
        .where(eq(atividadesMonitor.id, atividadeId))
        .limit(1);
      
      if (!atividade) {
        return res.status(404).json({ error: "Atividade não encontrada" });
      }
      
      // Permitir acesso para o próprio monitor, devs e admins
      const isOwner = atividade.monitorUserId === user.id;
      const isPrivileged = user.role && ['dev', 'admin', 'leo', 'monitor'].includes(user.role);
      if (!isOwner && !isPrivileged) {
        return res.status(403).json({ error: "Acesso negado" });
      }
      
      // Converter data string para Date
      let dataToSave = atividade.data;
      if (data) {
        dataToSave = new Date(data + 'T12:00:00');
      }
      
      const [updated] = await db.update(atividadesMonitor)
        .set({
          titulo: titulo || atividade.titulo,
          descricao: descricao !== undefined ? descricao : atividade.descricao,
          data: dataToSave,
          horarioInicio: horarioInicio || atividade.horarioInicio,
          horarioFim: horarioFim || atividade.horarioFim,
          tipo: tipo || atividade.tipo,
          local: local !== undefined ? local : atividade.local,
        })
        .where(eq(atividadesMonitor.id, atividadeId))
        .returning();
      
      console.log("[RBAC MONITOR] Atividade " + atividadeId + " atualizada por usuário " + user.id);
      res.json(updated);
    } catch (error: any) {
      console.error("Error updating atividade:", error);
      res.status(500).json({ error: "Failed to update atividade" });
    }
  });

  // DELETE /api/monitor/atividades/:atividadeId - Delete activity
  app.delete("/api/monitor/atividades/:atividadeId", requireAuth, requireMonitor, async (req, res) => {
    try {
      const atividadeId = parseInt(req.params.atividadeId);
      const user = (req as any).user;
      
      // Verificar se a atividade pertence ao monitor
      const [atividade] = await db.select()
        .from(atividadesMonitor)
        .where(eq(atividadesMonitor.id, atividadeId))
        .limit(1);
      
      if (!atividade) {
        return res.status(404).json({ error: "Atividade não encontrada" });
      }
      
      // Permitir acesso para o próprio monitor, devs e admins
      const isOwner = atividade.monitorUserId === user.id;
      const isPrivileged = user.role && ['dev', 'admin', 'leo', 'monitor'].includes(user.role);
      console.log("[DELETE ATIVIDADE] user.id=" + user.id + ", user.role=" + user.role + ", atividade.monitorUserId=" + atividade.monitorUserId + ", isOwner=" + isOwner + ", isPrivileged=" + isPrivileged);
      if (!isOwner && !isPrivileged) {
        return res.status(403).json({ error: "Acesso negado" });
      }
      
      await db.delete(atividadesMonitor)
        .where(eq(atividadesMonitor.id, atividadeId));
      
      console.log(`[RBAC MONITOR] Atividade ${atividadeId} excluída por monitor ${user.id}`);
      res.json({ success: true, message: "Atividade excluída com sucesso" });
    } catch (error: any) {
      console.error("Error deleting atividade:", error);
      res.status(500).json({ error: "Failed to delete atividade" });
    }
  });


  // GET /api/monitor/:monitorId/grupos - List monitor's groups
  app.get("/api/monitor/:monitorId/grupos", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const vertente = req.query.vertente as string | undefined; // 'pec' ou 'inclusao'
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'grupos');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      // Para PEC: buscar da tabela activityInstances via staffAssignments
      if (vertente === 'pec') {
        // Buscar turmas PEC onde o monitor está atribuído
        const assignments = await db.select({
          instanceId: staffAssignments.activity_instance_id,
          role: staffAssignments.role
        })
          .from(staffAssignments)
          .where(eq(staffAssignments.person_id, monitorId));
        
        if (assignments.length === 0) {
          return res.json([]);
        }
        
        const instanceIds = assignments.map(a => a.instanceId);
        
        // Buscar detalhes das turmas
        // Buscar detalhes das turmas
        const turmas = await db.select()
          .from(activityInstances)
          .where(inArray(activityInstances.id, instanceIds))
          .orderBy(activityInstances.created_at);
        
        // Buscar nomes das atividades
        const activityIds = [...new Set(turmas.map(t => t.activity_id).filter(Boolean))];
        const activities = activityIds.length > 0 
          ? await db.select().from(pecActivities).where(inArray(pecActivities.id, activityIds))
          : [];
        const activityMap = new Map(activities.map(a => [a.id, a.name || a.title]));
        
        // Calcular frequência e contar participantes (enrollments)
        const turmasComFrequencia = await Promise.all(turmas.map(async (turma) => {
          try {
            // Contar participantes vinculados à turma (enrollments)
            const participantesVinculados = await db.select()
              .from(instanceEnrollments)
              .where(and(eq(instanceEnrollments.activity_instance_id, turma.id), eq(instanceEnrollments.active, true)));
            const qtdParticipantes = participantesVinculados.length;
            console.log(`📊 Turma ${turma.id}: ${qtdParticipantes} alunos encontrados em instanceEnrollments`);
            
            // Buscar sessões para calcular frequência
            const sessoes = await db.select()
              .from(sessions)
              .where(eq(sessions.activity_instance_id, turma.id));
            
            if (sessoes.length === 0) {
              return { 
                id: turma.id,
                nome: turma.title,
                codigo: turma.code,
                local: turma.location,
                status: turma.situation || 'ativo',
                horarioInicio: turma.start_time,
                horarioFim: turma.end_time,
                dataInicio: turma.occurrence_start,
                dataFim: turma.occurrence_end,
                createdAt: turma.created_at,
                frequencia: null, 
                qtdParticipantes,
                alunos: qtdParticipantes,
                vertente: 'pec',
                atividade: activityMap.get(turma.activity_id) || 'PEC'
              };
            }
            
            // Calcular frequência média das sessões
            let totalPresentes = 0;
            let totalRegistros = 0;
            
            for (const sessao of sessoes) {
              if (sessao.attendance && typeof sessao.attendance === 'object') {
                const att = sessao.attendance as any;
                if (Array.isArray(att)) {
                  totalRegistros += att.length;
                  totalPresentes += att.filter((a: any) => a.present || a.presente).length;
                }
              }
            }
            
            const frequencia = totalRegistros > 0 ? Math.round((totalPresentes / totalRegistros) * 100) : null;
            return { 
              id: turma.id,
              nome: turma.title,
              codigo: turma.code,
              local: turma.location,
              status: turma.situation || 'ativo',
              horarioInicio: turma.start_time,
              horarioFim: turma.end_time,
              dataInicio: turma.occurrence_start,
              dataFim: turma.occurrence_end,
              createdAt: turma.created_at,
              frequencia, 
              qtdParticipantes,
                alunos: qtdParticipantes,
              vertente: 'pec',
              atividade: activityMap.get(turma.activity_id) || 'PEC'
            };
          } catch (e) {
            return { 
              id: turma.id,
              nome: turma.title,
              codigo: turma.code,
              local: turma.location,
              status: turma.situation || 'ativo',
              frequencia: null, 
              qtdParticipantes: 0,
              vertente: 'pec',
              atividade: activityMap.get(turma.activity_id) || 'PEC'
            };
          }
        }));

        return res.json(turmasComFrequencia);
      }
      // Para Inclusão: buscar de turmas_inclusao onde professorId = monitorId
      if (vertente === 'inclusao') {
        const turmas = await db.select()
          .from(turmasInclusao)
          .orderBy(turmasInclusao.createdAt);
        
        // Calcular frequência e contar participantes
        const turmasComFrequencia = await Promise.all(turmas.map(async (turma) => {
          try {
            // Contar participantes vinculados à turma
            const participantesVinculados = await db.select()
              .from(participantesTurmas)
              .where(and(
                eq(participantesTurmas.turmaId, turma.id),
                eq(participantesTurmas.status, 'ativo')
              ));
            const qtdParticipantes = participantesVinculados.length;
            console.log(`📊 Turma Inclusão ${turma.id}: ${qtdParticipantes} participantes em participantesTurmas`);
            
            // Buscar presenças para calcular frequência
            const presencas = await db.select()
              .from(presencasInclusao)
              .where(eq(presencasInclusao.turmaId, turma.id));
            
            if (presencas.length === 0) {
              return { 
                id: turma.id,
                nome: turma.nome,
                codigo: turma.codigo,
                local: turma.local,
                status: turma.status || 'ativo',
                horarioInicio: turma.horarioEntrada,
                horarioFim: turma.horarioSaida,
                dataInicio: turma.dataInicio,
                dataFim: turma.dataFim,
                createdAt: turma.createdAt,
                frequencia: null, 
                qtdParticipantes,
                alunos: qtdParticipantes,
                vertente: 'inclusao',
                descricao: turma.descricao
              };
            }
            
            // Calcular frequência média
            const totalPresentes = presencas.filter(p => p.presente).length;
            const frequencia = presencas.length > 0 ? Math.round((totalPresentes / presencas.length) * 100) : null;
            
            return { 
              id: turma.id,
              nome: turma.nome,
              codigo: turma.codigo,
              local: turma.local,
              status: turma.status || 'ativo',
              horarioInicio: turma.horarioEntrada,
              horarioFim: turma.horarioSaida,
              dataInicio: turma.dataInicio,
              dataFim: turma.dataFim,
              createdAt: turma.createdAt,
              frequencia, 
              qtdParticipantes,
              alunos: qtdParticipantes,
              vertente: 'inclusao',
              descricao: turma.descricao
            };
          } catch (e) {
            console.error(`Erro ao processar turma inclusão ${turma.id}:`, e);
            return { 
              id: turma.id,
              nome: turma.nome,
              codigo: turma.codigo,
              local: turma.local,
              status: turma.status || 'ativo',
              frequencia: null, 
              qtdParticipantes: 0,
              alunos: 0,
              vertente: 'inclusao',
              descricao: turma.descricao
            };
          }
        }));

        return res.json(turmasComFrequencia);
      }
      
      // Fallback: manter comportamento original com monitorGrupos para outros casos
      // Para Inclusão ou sem vertente: manter comportamento original com monitorGrupos
      const grupos = await db.select()
        .from(monitorGrupos)
        .where(vertente ? and(eq(monitorGrupos.monitorUserId, monitorId), eq(monitorGrupos.vertente, vertente)) : eq(monitorGrupos.monitorUserId, monitorId))
        .orderBy(monitorGrupos.createdAt);
      
      // Calcular frequência e contar participantes
      const gruposComFrequencia = await Promise.all(grupos.map(async (grupo) => {
        try {
          // Contar participantes vinculados ao grupo
          const participantesVinculados = await db.select()
            .from(monitorGrupoAlunos)
            .where(eq(monitorGrupoAlunos.grupoId, grupo.id));
          const qtdParticipantes = participantesVinculados.length;
            console.log(`📊 Turma ${turma.id}: ${qtdParticipantes} alunos encontrados em instanceEnrollments`);
          
          // Buscar registros de chamada do grupo
          const registros = await db.select()
            .from(registrosAtividades)
            .where(and(
              eq(registrosAtividades.monitorUserId, monitorId),
              like(registrosAtividades.titulo, `Chamada - ${grupo.nome}`)
            ));
          
          if (registros.length === 0) {
            return { ...grupo, frequencia: null, qtdParticipantes };
          }
          
          // Calcular frequência média
          let totalPresentes = 0;
          let totalAlunos = 0;
          
          for (const reg of registros) {
            try {
              const obs = reg.resultadosObservacoes ? JSON.parse(reg.resultadosObservacoes) : null;
              if (obs?.presencas && Array.isArray(obs.presencas)) {
                totalAlunos += obs.presencas.length;
                totalPresentes += obs.presencas.filter((p: any) => p.presente).length;
              }
            } catch (e) {
              // Ignorar erro de parse
            }
          }
          
          const frequencia = totalAlunos > 0 ? Math.round((totalPresentes / totalAlunos) * 100) : null;
          return { ...grupo, frequencia, qtdParticipantes };
        } catch (e) {
          // Contar participantes mesmo em caso de erro
          const participantesVinculados = await db.select()
            .from(monitorGrupoAlunos)
            .where(eq(monitorGrupoAlunos.grupoId, grupo.id));
          return { ...grupo, frequencia: null, qtdParticipantes: participantesVinculados.length };
        }
      }));
      
      res.json(gruposComFrequencia);
    } catch (error: any) {
      console.error("Error fetching grupos:", error);
      res.status(500).json({ error: "Failed to fetch grupos" });
    }
  });

  // POST /api/monitor/:monitorId/grupos - Create new group
  app.post("/api/monitor/:monitorId/grupos", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const user = (req as any).user;
      const role = String((user as any)?.role || "").toLowerCase();
      
      // ✅ fallback pelo programa do monitor (garante inclusão mesmo se role vier vazio)
    const monitorRow = await db
      .select({ programa: monitores.programa })
      .from(monitores)
      .where(eq(monitores.id, monitorId))
      .limit(1);

    const programaMonitor = String(monitorRow?.[0]?.programa || "").toLowerCase();

    const vertente =
      role.includes("inclusao") || programaMonitor.includes("inclusao")
        ? "inclusao"
        : role.includes("pec") || programaMonitor.includes("pec")
          ? "pec"
          : "legacy";

      const access = ensureSelfAccess(user, monitorId, 'grupos');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      // Para Inclusão: criar em turmas_inclusao
      if (vertente === 'inclusao') {
        const { nome, codigo, local, horarioInicio, horarioFim, dataInicio, dataFim, descricao, programaId } = req.body;
        
        // Buscar ou usar o primeiro programa de inclusão como fallback
        let progId = programaId;
        if (!progId) {
          const programas = await db.select().from(programasInclusao).limit(1);
          progId = programas.length > 0 ? programas[0].id : 1;
        }
        
        const [newTurma] = await db.insert(turmasInclusao).values({
          programaId: progId,
          professorId: monitorId,
          nome: nome,
          codigo: codigo,
          local: local,
          horarioEntrada: horarioInicio || null,
          horarioSaida: horarioFim || null,
          dataInicio: dataInicio,
          dataFim: dataFim,
          descricao: descricao,
          status: 'emandamento'
        }).returning();
        
        console.log(`[RBAC MONITOR] Turma Inclusão criada por monitor ${monitorId}: ${newTurma.nome}`);
        return res.json({
          id: newTurma.id,
          nome: newTurma.nome,
          codigo: newTurma.codigo,
          local: newTurma.local,
          horarioInicio: newTurma.horarioEntrada,
          horarioFim: newTurma.horarioSaida,
          dataInicio: newTurma.dataInicio,
          dataFim: newTurma.dataFim,
          status: newTurma.status,
          vertente: 'inclusao',
          descricao: newTurma.descricao,
          createdAt: newTurma.createdAt
        });
      }
      
      // Fallback: criar em monitorGrupos (legacy)
      const validated = insertMonitorGrupoSchema.parse({
        ...req.body,
        monitorUserId: monitorId
      });
      
      const newGrupo = await db.insert(monitorGrupos)
        .values(validated)
        .returning();
      
      console.log(`[RBAC MONITOR] Grupo criado por monitor ${monitorId}: ${newGrupo[0].nome}`);
      res.json(newGrupo[0]);
    } catch (error: any) {
      console.error("Error creating grupo:", error);
      res.status(500).json({ error: "Failed to create grupo" });
    }
  });

  // PATCH /api/monitor/:monitorId/grupos/:grupoId - Update group
  app.patch("/api/monitor/:monitorId/grupos/:grupoId", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const vertente = req.query.vertente as string | undefined; // 'pec' ou 'inclusao'
      const grupoId = parseInt(req.params.grupoId);
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'grupos');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      const { nome, nivel, atividade, status, horarioInicio, horarioFim, diasSemana, local, descricao, dataInicio, dataFim, codigo } = req.body;
      
      // Para Inclusão: atualizar em turmas_inclusao
      // Para PEC: atualizar em activityInstances
      if (vertente === 'pec') {
        const updated = await db.update(activityInstances)
          .set({
            title: nome,
            code: codigo,
            location: local,
            start_time: horarioInicio || null,
            end_time: horarioFim || null,
            occurrence_start: dataInicio || null,
            occurrence_end: dataFim || null,
            situation: status || 'ativo',
            updated_at: new Date()
          })
          .where(eq(activityInstances.id, grupoId))
          .returning();
        
        if (updated.length === 0) {
          return res.status(404).json({ error: 'Turma não encontrada' });
        }
        
        console.log(`[RBAC MONITOR] Turma PEC ${grupoId} atualizada por monitor ${monitorId}`);
        return res.json({
          id: updated[0].id,
          nome: updated[0].title,
          codigo: updated[0].code,
          local: updated[0].location,
          horarioInicio: updated[0].start_time,
          horarioFim: updated[0].end_time,
          dataInicio: updated[0].occurrence_start,
          dataFim: updated[0].occurrence_end,
          status: updated[0].situation,
          vertente: 'pec'
        });
      }

      if (vertente === 'inclusao') {
        const updated = await db.update(turmasInclusao)
          .set({
            nome,
            codigo,
            local,
            horarioEntrada: horarioInicio || null,
            horarioSaida: horarioFim || null,
            dataInicio,
            dataFim,
            descricao,
            status: status || 'emandamento',
            updatedAt: new Date()
          })
          .where(eq(turmasInclusao.id, grupoId))
          .returning();
        
        if (updated.length === 0) {
          return res.status(404).json({ error: 'Turma não encontrada' });
        }
        
        console.log(`[RBAC MONITOR] Turma Inclusão ${grupoId} atualizada por monitor ${monitorId}`);
        return res.json({
          id: updated[0].id,
          nome: updated[0].nome,
          codigo: updated[0].codigo,
          local: updated[0].local,
          horarioInicio: updated[0].horarioEntrada,
          horarioFim: updated[0].horarioSaida,
          dataInicio: updated[0].dataInicio,
          dataFim: updated[0].dataFim,
          status: updated[0].status,
          vertente: 'inclusao',
          descricao: updated[0].descricao
        });
      }
      
      // Fallback: atualizar em monitorGrupos (legacy)
      const updated = await db.update(monitorGrupos)
        .set({
          horarioInicio,
          horarioFim,
          diasSemana,
          nome,
          nivel,
          atividade,
          status,
          updatedAt: new Date()
        })
        .where(and(eq(monitorGrupos.id, grupoId), eq(monitorGrupos.monitorUserId, monitorId)))
        .returning();
      
      if (updated.length === 0) {
        return res.status(404).json({ error: 'Grupo não encontrado' });
      }
      
      console.log(`[RBAC MONITOR] Grupo ${grupoId} atualizado por monitor ${monitorId}`);
      res.json(updated[0]);
    } catch (error: any) {
      console.error("Error updating grupo:", error);
      res.status(500).json({ error: "Failed to update grupo" });
    }
  });
