  app.post("/api/dev/stripe/update-keys", async (req, res) => {
    try {
      // Verificar se é request de desenvolvedor
      if (!(req as any).isDeveloper) {
        return res
          .status(403)
          .json({ error: "Acesso negado - apenas desenvolvedor" });
      }

      const { secretKey, publicKey } = req.body;

      // Validações básicas
      if (!secretKey || !publicKey) {
        return res
          .status(400)
          .json({ error: "Secret Key e Public Key são obrigatórios" });
      }

      if (!secretKey.startsWith("sk_")) {
        return res
          .status(400)
          .json({ error: "Secret Key deve começar com 'sk_'" });
      }

      if (!publicKey.startsWith("pk_")) {
        return res
          .status(400)
          .json({ error: "Public Key deve começar com 'pk_'" });
      }

      // ⚠️ IMPORTANTE: Este método atualiza as variáveis de ambiente em runtime
      // mas elas NÃO persistem após restart. Para persistência, você precisa
      // atualizar manualmente no painel do Replit ou usar secrets management
      process.env.STRIPE_SECRET_KEY = secretKey;
      process.env.VITE_STRIPE_PUBLIC_KEY = publicKey;

      // Recriar instância do Stripe com nova chave
      const newStripe = new Stripe(secretKey);

      // Testar se a chave funciona
      try {
        await newStripe.customers.list({ limit: 1 });
      } catch (stripeError: any) {
        return res.status(400).json({
          error: "Chave da Stripe inválida: " + stripeError.message,
        });
      }

      // Log de auditoria
      console.log(
        `🔑 STRIPE KEYS UPDATED by developer at ${new Date().toISOString()}`
      );
      console.log(
        `   Secret Key: ${secretKey.substring(0, 7)}...${secretKey.substring(
          -4
        )}`
      );
      console.log(
        `   Public Key: ${publicKey.substring(0, 7)}...${publicKey.substring(
          -4
        )}`
      );

      res.json({
        success: true,
        message: "Chaves da Stripe atualizadas com sucesso!",
        warning:
          "⚠️ ATENÇÃO: Estas chaves são temporárias e serão perdidas no restart. Atualize também no painel do Replit para persistência permanente.",
        updatedAt: new Date().toISOString(),
      });
    } catch (error: any) {
      console.error("❌ Error updating Stripe keys:", error);
      res
        .status(500)
        .json({ error: "Erro ao atualizar chaves: " + error.message });
    }
  });

