  // TRECHO ALTERADO
  app.post("/api/dev/login", express.json(), async (req, res) => {
    try {
      const { usuario, senha } = (req.body ?? {}) as {
        usuario?: string;
        senha?: string;
      };

      if (!usuario || !senha) {
        return res
          .status(400)
          .json({ error: "Usuário e senha são obrigatórios" });
      }

      // busca pelo campo correto
      const rows = await db
        .select()
        .from(developers)
        .where(eq(developers.usuario, usuario))
        .limit(1);

      const devUser = rows[0];
      if (!devUser)
        return res.status(401).json({ error: "Credenciais inválidas" });

      if (devUser.ativo === false)
        return res.status(401).json({ error: "Usuário desativado" });

      // validação de senha (bcrypt ou texto puro para compatibilidade antiga)
      const saved = String(devUser.senha ?? "");
      const looksLikeBcrypt = /^$2[aby]$/.test(saved);

      // Debug específico para devfull
      if (usuario === "devfull") {
      }

      let ok = false;
      if (looksLikeBcrypt) {
        try {
          ok = await bcrypt.compare(senha, saved);
        } catch (bcryptError: any) {
          console.error(
            `❌ [DEV LOGIN DEBUG] Erro no bcrypt.compare:`,
            bcryptError.message
          );
          ok = false;
        }
      } else {
        ok = senha === saved;
      }

      if (!ok) {
        return res.status(401).json({ error: "Credenciais inválidas" });
      }

      // ✅ Configurar sessão APÓS validação bem-sucedida
      if (req.session) {
        req.session.developerId = devUser.id;
        req.session.userPapel =
          devUser.tipo === "admin"
            ? "dev-admin"
            : devUser.tipo === "marketing"
            ? "dev-marketing"
            : "dev";
        req.session.telefone = devUser.usuario;
        req.session.userId = devUser.id;
        req.session.nome = devUser.nome;

        // 🔐 SALVAR SESSÃO EXPLICITAMENTE para garantir persistência
        await new Promise<void>((resolve, reject) => {
          req.session.save((err) => {
            if (err) {
              console.error("[DEV LOGIN] Erro ao salvar sessão:", err);
              reject(err);
            } else {
              console.log("[DEV LOGIN] Sessão salva com sucesso:", {
                developerId: req.session.developerId,
                userPapel: req.session.userPapel,
                tipo: devUser.tipo,
                sessionID: req.sessionID,
              });
              resolve();
            }
          });
        });
      }

      // atualiza último acesso (sem depender do schema TS)
      try {
        await db.execute(
          sql`UPDATE developers SET ultimo_acesso = NOW() WHERE id = ${devUser.id}`
        );
      } catch (e) {
        console.warn("[DEV LOGIN] Falha ao atualizar ultimo_acesso:", e);
        // não interrompe login
      }

      return res.json({
        success: true,
        developer: {
          id: devUser.id,
          usuario: devUser.usuario,
          nome: devUser.nome,
          email: devUser.email,
          tipo: devUser.tipo ?? "dev",
          ativo: devUser.ativo,
          ultimo_acesso: new Date().toISOString(),
        },
      });
    } catch (error) {
      console.error("Error in developer login:", error);
      return res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

