  // PUT /api/coordenador/me - Atualizar dados do coordenador autenticado
app.put(
  "/api/coordenador/me",
  requireCoordinatorAuth, // ✅ TROCOU AQUI
  express.json(),
  async (req: any, res) => {
    try {
      const coordenadorId = req.user.id;
      const coordenadorEmailAtual = req.user.email;

      const { nome, email, telefone } = req.body;

      if (!nome || !nome.trim()) {
        return res.status(400).json({ error: "Nome é obrigatório" });
      }

      if (!email || !email.trim()) {
        return res.status(400).json({ error: "Email é obrigatório" });
      }

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        return res.status(400).json({ error: "Email inválido" });
      }

      // Verificar se o email já existe (em outro coordenador)
      if (email.trim().toLowerCase() !== coordenadorEmailAtual?.toLowerCase()) {
        const emailExiste = await db
          .select()
          .from(coordenadores)
          .where(
            and(
              eq(coordenadores.email, email.trim().toLowerCase()),
              not(eq(coordenadores.id, coordenadorId))
            )
          )
          .limit(1);

        if (emailExiste && emailExiste.length > 0) {
          return res.status(400).json({
            error: "Este email já está em uso por outro coordenador",
          });
        }
      }

      await db
        .update(coordenadores)
        .set({
          nome: nome.trim(),
          email: email.trim().toLowerCase(),
          telefone: telefone?.trim() || null,
          updatedAt: new Date(),
        })
        .where(eq(coordenadores.id, coordenadorId));

      // (Opcional) atualizar users se existir
      const oldEmail = coordenadorEmailAtual;
      if (email.trim().toLowerCase() !== oldEmail?.toLowerCase()) {
        const userToUpdate = await db
          .select()
          .from(users)
          .where(eq(users.email, oldEmail))
          .limit(1);

        if (userToUpdate && userToUpdate.length > 0) {
          await db
            .update(users)
            .set({
              nome: nome.trim(),
              email: email.trim().toLowerCase(),
            })
            .where(eq(users.id, userToUpdate[0].id));
        }
      }

      const coordAtualizado = await db
        .select()
        .from(coordenadores)
        .where(eq(coordenadores.id, coordenadorId))
        .limit(1);

      const { passwordHash, ...coordSemSenha } = coordAtualizado[0];

      res.json({
        success: true,
        message: "Perfil atualizado com sucesso",
        data: coordSemSenha,
      });
    } catch (error: any) {
      console.error("❌ [PUT /api/coordenador/me] Erro:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  }
);

  // ================ LOGIN DE MONITOR ================
 app.post("/api/login/monitor", express.json(), async (req, res) => {
  try {
    const { email, senha } = req.body;

    if (!email || !email.trim()) return res.status(400).json({ error: "Email é obrigatório" });
    if (!senha || !senha.trim()) return res.status(400).json({ error: "Senha é obrigatória" });

    const normalizedEmail = email.toLowerCase().trim();

    console.log(`🔑 [MONITOR LOGIN] Tentativa de login: ${normalizedEmail}`);

    const monitorResult = await db
      .select()
      .from(monitores)
      .where(eq(monitores.email, normalizedEmail))
      .limit(1);

    if (!monitorResult?.length) {
      console.log(`❌ [MONITOR LOGIN] Monitor não encontrado: ${normalizedEmail}`);
      return res.status(401).json({ error: "Email ou senha incorretos" });
    }

    const monitor = monitorResult[0];

    if (!monitor.ativo) {
      console.log(`❌ [MONITOR LOGIN] Monitor desativado: ${normalizedEmail}`);
      return res.status(401).json({ error: "Email ou senha incorretos" });
    }

    if (!monitor.passwordHash) {
      console.log(`❌ [MONITOR LOGIN] Monitor sem passwordHash: ${normalizedEmail}`);
      return res.status(401).json({ error: "Email ou senha incorretos" });
    }

    const senhaValida = await bcrypt.compare(senha, monitor.passwordHash);
    if (!senhaValida) {
      console.log(`❌ [MONITOR LOGIN] Senha incorreta para: ${normalizedEmail}`);
      return res.status(401).json({ error: "Email ou senha incorretos" });
    }

    let role = "monitor";
    switch (monitor.programa) {
      case "pec": role = "monitor_pec"; break;
      case "inclusao_produtiva": role = "monitor_inclusao"; break;
      case "psicossocial": role = "monitor_psico"; break;
    }

    const existingUser = await db
      .select()
      .from(users)
      .where(eq(users.email, normalizedEmail))
      .limit(1);

    let userId: number;

    if (existingUser?.length) {
      await db
        .update(users)
        .set({ nome: monitor.nome, role, ativo: true, tipo: "monitor" })
        .where(eq(users.id, existingUser[0].id));

      userId = existingUser[0].id;
    } else {
      const newUser = await db
        .insert(users)
        .values({
          email: normalizedEmail,
          nome: monitor.nome,
          telefone: monitor.telefone || "",
          role,
          ativo: true,
          tipo: "monitor",
          verificado: true,
        })
        .returning();

      userId = newUser[0].id;
    }

    return res.json({
      success: true,
      monitor: {
        id: monitor.id,
        nome: monitor.nome,
        email: monitor.email,
        programa: monitor.programa,
        role,
        redirectPath: monitor.redirectPath || "/monitor",
      },
      userId,
    });
  } catch (error: any) {
    console.error("❌ [MONITOR LOGIN] Erro:", error?.stack || error);
    return res.status(500).json({ error: "Erro interno do servidor" });
  }
});

