  // Obter status de participação do usuário
  app.get("/api/sorteio/:sorteioId/usuario/:userId", async (req, res) => {
    try {
      const sorteioId = parseInt(req.params.sorteioId);
      const userId = parseInt(req.params.userId);

      if (isNaN(sorteioId) || isNaN(userId)) {
        return res.status(400).json({ error: "IDs inválidos" });
      }

      // Buscar dados do usuário
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Verificar participação existente
      const participacao = await storage.getParticipacaoUsuario(
        sorteioId,
        userId
      );

      // Calcular número de chances baseado no plano (novas regras)
      const planoChances = {
        eco: 1,
        voz: 2,
        grito: 3,
        platinum: 5,
      };

      const numeroChances =
        planoChances[user.plano as keyof typeof planoChances] || 1;

      // Verificar elegibilidade (pagamento em dia)
      const elegivel = user.subscriptionStatus === "active";

      const status = {
        elegivel,
        numeroChances,
        plano: user.plano,
        participacao: participacao || null,
        motivoInelegibilidade: !elegivel
          ? "Pagamento pendente ou plano inativo"
          : null,
      };

      res.json(status);
    } catch (error) {
      console.error("Error getting user sorteio status:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // Confirmar participação no sorteio
  app.post("/api/sorteio/:sorteioId/participar", async (req, res) => {
    try {
      const sorteioId = parseInt(req.params.sorteioId);
      const { userId } = req.body;

      if (isNaN(sorteioId) || !userId) {
        return res.status(400).json({ error: "Dados inválidos" });
      }

      // Verificar se já existe participação
      const participacaoExistente = await storage.getParticipacaoUsuario(
        sorteioId,
        userId
      );
      if (participacaoExistente) {
        return res.json({
          message: "Usuário já está participando do sorteio",
          participacao: participacaoExistente,
        });
      }

      // Buscar dados do usuário
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Verificar elegibilidade
      const elegivel = user.subscriptionStatus === "active";
      if (!elegivel) {
        return res
          .status(400)
          .json({ error: "Usuário não elegível para o sorteio" });
      }

      // Calcular chances e números atribuídos (novas regras)
      const planoChances = { eco: 1, voz: 2, grito: 3, platinum: 5 };
      const numeroChances =
        planoChances[user.plano as keyof typeof planoChances] || 1;

      // Gerar números únicos para o usuário (simplificado)
      const numerosAtribuidos = Array.from(
        { length: numeroChances },
        (_, i) => Math.floor(Math.random() * 100000) + i
      );

      const participacao = await storage.createParticipacao({
        sorteioId,
        userId,
        numeroChances,
        numerosAtribuidos,
        elegivel: true,
        planoAtual: user.plano,
        valorPlano:
          user.plano === "eco"
            ? "9.90"
            : user.plano === "voz"
            ? "19.90"
            : user.plano === "grito"
            ? "29.90"
            : "49.90",
        participacaoConfirmada: true,
      });

      res.json({
        message: "Participação confirmada com sucesso!",
        participacao,
      });
    } catch (error) {
      console.error("Error confirming sorteio participation:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

