  // Adicionar novo payment method
  app.post("/api/users/:userId/payment-methods", async (req, res) => {
    try {
      const { userId } = req.params;
      const { paymentMethodId } = req.body;

      console.log(
        `💳 [ADD PAYMENT METHOD] Iniciando para usuário ${userId}, PM: ${paymentMethodId}`
      );

      // Validar paymentMethodId
      if (!paymentMethodId || typeof paymentMethodId !== "string") {
        console.log(
          `❌ [ADD PAYMENT METHOD] paymentMethodId inválido ou ausente`
        );
        return res.status(400).json({
          success: false,
          error: "paymentMethodId é obrigatório",
        });
      }

      // Buscar usuário no banco para pegar stripeCustomerId
      const user = await storage.getUser(parseInt(userId));
      if (!user || !user.stripeCustomerId) {
        console.log(
          `❌ [ADD PAYMENT METHOD] Usuário ou customer não encontrado`
        );
        return res.status(400).json({
          success: false,
          message: "User not found or no Stripe customer",
        });
      }

      // Anexar payment method ao customer
      await stripe.paymentMethods.attach(paymentMethodId, {
        customer: user.stripeCustomerId,
      });

      console.log(
        `✅ [ADD PAYMENT METHOD] Payment method ${paymentMethodId} anexado ao customer ${user.stripeCustomerId}`
      );

      // Definir como método de pagamento padrão
      await stripe.customers.update(user.stripeCustomerId, {
        invoice_settings: {
          default_payment_method: paymentMethodId,
        },
      });

      console.log(
        `✅ [ADD PAYMENT METHOD] Payment method ${paymentMethodId} definido como padrão`
      );

      // Buscar lista atualizada de payment methods
      const paymentMethods = await stripe.paymentMethods.list({
        customer: user.stripeCustomerId,
        type: "card",
      });

      // Filtrar duplicatas e ordenar (mesmo que endpoint GET)
      const seenCards = new Map();
      const sortedPaymentMethods = [...paymentMethods.data].sort((a, b) => {
        if (a.id === paymentMethodId) return -1;
        if (b.id === paymentMethodId) return 1;
        return 0;
      });

      const uniquePaymentMethods = sortedPaymentMethods.filter((pm) => {
        const visualKey = `${pm.card?.brand}-${pm.card?.last4}-${pm.card?.exp_month}-${pm.card?.exp_year}`;
        if (seenCards.has(visualKey)) {
          return false;
        }
        seenCards.set(visualKey, pm.id);
        return true;
      });

      console.log(
        `📊 [ADD PAYMENT METHOD] Retornando ${uniquePaymentMethods.length} payment methods`
      );

      res.json({
        success: true,
        paymentMethods: uniquePaymentMethods.map((pm) => ({
          id: pm.id,
          brand: pm.card?.brand,
          last4: pm.card?.last4,
          exp_month: pm.card?.exp_month,
          exp_year: pm.card?.exp_year,
          funding: pm.card?.funding,
          isDefault: pm.id === paymentMethodId,
        })),
      });
    } catch (error: any) {
      console.error(`❌ [ADD PAYMENT METHOD] Erro:`, error);
      res.status(500).json({
        success: false,
        message: "Error adding payment method: " + error.message,
      });
    }
  });

  // Remover payment method (COM VALIDAÇÃO DE SEGURANÇA)
  app.delete(
    "/api/users/:userId/payment-methods/:paymentMethodId",
    async (req, res) => {
      try {
        const { userId, paymentMethodId } = req.params;

        // Buscar usuário para pegar customer ID
        const user = await storage.getUser(parseInt(userId));
        if (!user || !user.stripeCustomerId) {
          return res.status(404).json({ error: "Usuário não encontrado" });
        }

        const customerId = user.stripeCustomerId;

        // ✅ VALIDAÇÃO 1: Verificar se há subscriptions ativas
        const subscriptions = await stripe.subscriptions.list({
          customer: customerId,
          status: "active",
          limit: 10,
        });

        // ✅ VALIDAÇÃO 2: Contar payment methods disponíveis
        const paymentMethods = await stripe.paymentMethods.list({
          customer: customerId,
          type: "card",
          limit: 10,
        });

        // ❌ BLOQUEAR remoção do último cartão se há subscription ativa
        if (subscriptions.data.length > 0 && paymentMethods.data.length <= 1) {
          return res.status(400).json({
            error: "Não é possível remover o último método de pagamento",
            message:
              "Você tem uma assinatura ativa. Adicione outro cartão antes de remover este.",
          });
        }

        // ✅ OK para remover: ou não tem subscription, ou tem outros cartões
        await stripe.paymentMethods.detach(paymentMethodId);

        console.log(
          `✅ Payment method ${paymentMethodId} removido com segurança do customer ${customerId}`
        );
        res.json({ success: true });
      } catch (error: any) {
        console.error("❌ Erro ao remover payment method:", error);
        res
          .status(500)
          .json({ message: "Error removing payment method: " + error.message });
      }
    }
  );

  // Sincronizar usuário com Stripe (buscar/criar customer e importar cartões)
  app.post("/api/users/:userId/sync-stripe", async (req, res) => {
    try {
      const { userId } = req.params;

      console.log(
        `🔄 [SYNC STRIPE] Sincronizando usuário ${userId} com Stripe`
      );

      // Buscar usuário no banco
      const user = await storage.getUser(parseInt(userId));
      if (!user) {
        console.log(`❌ [SYNC STRIPE] Usuário ${userId} não encontrado`);
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Se usuário não tem customer_id, criar ou buscar no Stripe
      let customerId = user.stripeCustomerId;

      // Se usuário não tem customer_id, criar ou buscar no Stripe
      if (!customerId) {
        console.log(
          `🔍 [SYNC STRIPE] Buscando customer no Stripe por email: ${user.email}`
        );

        const customers = await stripe.customers.list({
          email: user.email,
          limit: 1,
        });

        if (customers.data.length > 0) {
          customerId = customers.data[0].id;
          console.log(
            `✅ [SYNC STRIPE] Customer existente encontrado: ${customerId}`
          );
        } else {
          console.log(`➕ [SYNC STRIPE] Criando novo customer no Stripe`);
          const customer = await stripe.customers.create({
            email: user.email || undefined,
            name: user.nome || undefined,
            phone: user.telefone || undefined,
            metadata: {
              userId: userId.toString(),
              source: "clube_do_grito",
            },
          });
          customerId = customer.id;
          console.log(`✅ [SYNC STRIPE] Novo customer criado: ${customerId}`);
        }

        await storage.updateUser(parseInt(userId), {
          stripeCustomerId: customerId,
        });
        console.log(
          `✅ [SYNC STRIPE] stripeCustomerId salvo no banco: ${customerId}`
        );
      } else {
        console.log(
          `ℹ️ [SYNC STRIPE] Usuário já possui customer_id: ${customerId}`
        );

        // ⚠️ Validar se o customer ainda existe no Stripe
        try {
          await stripe.customers.retrieve(customerId);
        } catch (err: any) {
          if (err.code === "resource_missing" && err.param === "customer") {
            console.warn(
              `⚠️ [SYNC STRIPE] Customer ${customerId} não existe mais no Stripe. Recriando...`
            );

            // zera no banco para não ficar ID podre
            await storage.updateUser(parseInt(userId), {
              stripeCustomerId: null,
              stripeSubscriptionId: null,
            });

            // cria um novo customer
            const newCustomer = await stripe.customers.create({
              email: user.email || undefined,
              name: user.nome || undefined,
              phone: user.telefone || undefined,
              metadata: {
                userId: userId.toString(),
                source: "clube_do_grito",
              },
            });

            customerId = newCustomer.id;
            console.log(`✅ [SYNC STRIPE] Novo customer criado: ${customerId}`);

            await storage.updateUser(parseInt(userId), {
              stripeCustomerId: customerId,
            });
            console.log(
              `✅ [SYNC STRIPE] stripeCustomerId atualizado no banco`
            );
          } else {
            // outro tipo de erro: repassa pra ser tratado no catch geral
            throw err;
          }
        }
      }

      // 🔐 A partir daqui, customerId é garantido válido
      const paymentMethods = await stripe.paymentMethods.list({
        customer: customerId,
        type: "card",
      });

      console.log(
        `📊 [SYNC STRIPE] ${paymentMethods.data.length} payment methods encontrados`
      );

      const customer = await stripe.customers.retrieve(customerId);
      const defaultPaymentMethodId = (customer as any).invoice_settings
        ?.default_payment_method;

      // Filtrar duplicatas
      const seenCards = new Map();
      const sortedPaymentMethods = [...paymentMethods.data].sort((a, b) => {
        if (a.id === defaultPaymentMethodId) return -1;
        if (b.id === defaultPaymentMethodId) return 1;
        return 0;
      });

      const uniquePaymentMethods = sortedPaymentMethods.filter((pm) => {
        const visualKey = `${pm.card?.brand}-${pm.card?.last4}-${pm.card?.exp_month}-${pm.card?.exp_year}`;
        if (seenCards.has(visualKey)) {
          return false;
        }
        seenCards.set(visualKey, pm.id);
        return true;
      });

      res.json({
        success: true,
        customerId,
        paymentMethods: uniquePaymentMethods.map((pm) => ({
          id: pm.id,
          brand: pm.card?.brand,
          last4: pm.card?.last4,
          exp_month: pm.card?.exp_month,
          exp_year: pm.card?.exp_year,
          funding: pm.card?.funding,
          isDefault: pm.id === defaultPaymentMethodId,
        })),
        message: `Customer ${customerId} sincronizado com sucesso. ${uniquePaymentMethods.length} cartões encontrados.`,
      });
    } catch (error: any) {
      console.error(`❌ [SYNC STRIPE] Erro:`, error);
      res.status(500).json({
        success: false,
        error: "Erro ao sincronizar com Stripe: " + error.message,
      });
    }
  });

