  app.post("/api/admin/complete-checkin-mission/:userId", async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);
      const missaoId = req.body.missaoId || 5;
      
      console.log(`🔧 [ADMIN] Completando missão ${missaoId} retroativamente para usuário ${userId}`);
      
      const [user] = await db.select({ diasConsecutivos: users.diasConsecutivos }).from(users).where(eq(users.id, userId)).limit(1);
      
      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }
      
      const diasConsecutivos = user.diasConsecutivos || 0;
      
      const [missao] = await db.select().from(missoesSemanais).where(eq(missoesSemanais.id, missaoId)).limit(1);
      
      if (!missao) {
        return res.status(404).json({ error: "Missão não encontrada" });
      }
      
      const [jaConcluida] = await db.select().from(missoesConcluidas)
        .where(and(eq(missoesConcluidas.userId, userId), eq(missoesConcluidas.missaoId, missaoId)))
        .limit(1);
      
      if (jaConcluida) {
        return res.status(400).json({ error: "Missão já foi completada" });
      }
      
      const diasNecessarios = missao.diasNecessarios || missao.quantidadeAmigos || 3;
      
      if (diasConsecutivos < diasNecessarios) {
        return res.status(400).json({ error: `Dias insuficientes: ${diasConsecutivos}/${diasNecessarios}` });
      }
      
      // Usar storage para adicionar gritos
      await storage.addGritosToUser(userId, missao.recompensaGritos || 150);
      await db.insert(gritosHistorico).values({ userId, tipo: "missao_checkin", gritosGanhos: missao.recompensaGritos || 150, descricao: `Missão check-in completada retroativamente: "${missao.titulo}"` });
      
      await db.insert(missoesConcluidas).values({
        userId: userId,
        missaoId: missaoId,
        gritosRecebidos: missao.recompensaGritos || 150,
        fotoComprovante: null,
        evidenciaTexto: `Check-in automático retroativo: ${diasConsecutivos} dias consecutivos`,
        evidenceType: "automatico" as any
      });
      
      console.log(`✅ [ADMIN] Missão ${missaoId} completada para usuário ${userId}! +${missao.recompensaGritos || 150} gritos`);
      
      res.json({
        success: true,
        message: `Missão completada para usuário ${userId}`,
        gritosAdicionados: missao.recompensaGritos || 150,
        diasConsecutivos
      });
    } catch (error: any) {
      console.error("❌ [ADMIN] Erro ao completar missão:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // 🔧 ROTA ADMINISTRATIVA: Reset completo de check-in para um usuário
  app.post("/api/admin/users/:userId/reset-checkin", async (req, res) => {
    try {
      const { userId } = req.params;
      const userIdInt = parseInt(userId);

      console.log(
        `🔧 [ADMIN RESET] Iniciando reset completo para usuário ${userIdInt}`
      );

      // 1. Deletar TODOS os check-ins do usuário
      await db.delete(checkins).where(eq(checkins.userId, userIdInt));
      console.log(`✅ [ADMIN RESET] Deletados todos os check-ins`);

      // 2. Deletar TODOS os gritos de check-in do histórico
      const gritosRemovidos = await db
        .delete(gritosHistorico)
        .where(
          and(
            eq(gritosHistorico.userId, userIdInt),
            eq(gritosHistorico.tipo, "checkin_diario")
          )
        )
        .returning();
      console.log(
        `✅ [ADMIN RESET] Removidos ${gritosRemovidos.length} registros de gritos de check-in`
      );

      // 3. Recalcular gritos totais baseado no histórico restante
      const [{ total }] = await db
        .select({
          total: sql<string>`COALESCE(SUM(${gritosHistorico.gritosGanhos}), 0)`,
        })
        .from(gritosHistorico)
        .where(eq(gritosHistorico.userId, userIdInt));

      console.log(`📊 [ADMIN RESET] Total de gritos recalculado: ${total}`);

      // 4. Resetar campos do usuário e atualizar gritos_total
      await db.update(users)
        .set({ 
          ultimoCheckin: null, 
          diasConsecutivos: 0,
          gritosTotal: total,
        })
        .where(eq(users.id, userIdInt));
      console.log(
        `✅ [ADMIN RESET] Resetados campos do usuário e gritos atualizados para ${total}`
      );

      // 5. Verificar estado final
      const [userData] = await db
        .select()
        .from(users)
        .where(eq(users.id, userIdInt))
        .limit(1);
      const checkinsTableCount = await db
        .select()
        .from(checkins)
        .where(eq(checkins.userId, userIdInt));

      console.log(
        `📊 [ADMIN RESET] Estado final - gritos: ${userData.gritosTotal}, ultimo_checkin: ${userData.ultimoCheckin}, dias: ${userData.diasConsecutivos}, checkins na tabela: ${checkinsTableCount.length}`
      );

      res.json({
        success: true,
        message: "Reset completo realizado",
        estado: {
          gritosTotal: userData.gritosTotal,
          ultimoCheckin: userData.ultimoCheckin,
          diasConsecutivos: userData.diasConsecutivos,
          checkinsNaTabela: checkinsTableCount.length,
          gritosRemovidos: gritosRemovidos.length,
        },
      });
    } catch (error) {
      console.error("❌ [ADMIN RESET] Erro:", error);
      res.status(500).json({ error: "Erro ao resetar check-in" });
    }
  });

