  // Gerar QR Code
  app.get("/api/mkt/links/:id/qr", async (req, res) => {
    try {
      const link = await storage.getMarketingLink(parseInt(req.params.id));
      if (!link) {
        return res.status(404).json({ error: "Link não encontrado" });
      }

      // Construir URL completa
      const baseUrl =
        process.env.NODE_ENV === "production"
          ? "https://clubedogrito.institutoogrito.com.br"
          : `http://localhost:${process.env.PORT || 5000}`;
      const shortUrl = `${baseUrl}/l/${link.code}`;

      // Importar QR code dynamically
      const QRCode = (await import("qrcode")).default;

      const qrDataUrl = await QRCode.toDataURL(shortUrl, {
        errorCorrectionLevel: "H",
        type: "image/png",
        width: 400,
        margin: 2,
      });

      // Converter data URL para buffer
      const base64Data = qrDataUrl.replace(/^data:image\/png;base64,/, "");
      const buffer = Buffer.from(base64Data, "base64");

      res.setHeader("Content-Type", "image/png");
      res.setHeader(
        "Content-Disposition",
        `inline; filename="qr-${link.code}.png"`
      );
      res.send(buffer);
    } catch (error) {
      console.error("❌ [MKT-QR] Erro:", error);
      res.status(500).json({ error: "Erro ao gerar QR code" });
    }
  });

  // Exportar CSV
  app.get("/api/mkt/links/export.csv", async (req, res) => {
    try {
      const { campaignId } = req.query;
      const filters = campaignId
        ? { campaignId: parseInt(campaignId as string) }
        : undefined;
      const links = await storage.getMarketingLinks(filters);

      // Gerar CSV
      const baseUrl =
        process.env.NODE_ENV === "production"
          ? "https://clubedogrito.institutoogrito.com.br"
          : `http://localhost:${process.env.PORT || 5000}`;

      const rows = await Promise.all(
        links.map(async (link) => {
          const stats = await storage.getMarketingLinkStats(link.id);
          return {
            code: link.code,
            short_url: `${baseUrl}/l/${link.code}`,
            qr_url: `${baseUrl}/api/mkt/links/${link.id}/qr`,
            campaign_id: link.campaignId,
            medium: link.medium || "",
            source: link.source || "",
            clicks: stats.clicks,
            cadastros: stats.cadastros,
            conversoes: stats.conversoes,
            taxa: stats.taxa.toFixed(2) + "%",
            is_active: link.isActive ? "Sim" : "Não",
            created_at: link.createdAt
              ? new Date(link.createdAt).toISOString()
              : "",
          };
        })
      );

      // Cabeçalhos CSV
      const headers = [
        "code",
        "short_url",
        "qr_url",
        "campaign_id",
        "medium",
        "source",
        "clicks",
        "cadastros",
        "conversoes",
        "taxa",
        "is_active",
        "created_at",
      ];
      const csvContent = [
        headers.join(","),
        ...rows.map((row) =>
          headers.map((h) => `"${row[h as keyof typeof row]}"`).join(",")
        ),
      ].join("\n");

      res.setHeader("Content-Type", "text/csv; charset=utf-8");
      res.setHeader(
        "Content-Disposition",
        `attachment; filename="marketing-links-${Date.now()}.csv"`
      );
      res.send("\uFEFF" + csvContent); // BOM para UTF-8
    } catch (error) {
      console.error("❌ [MKT-EXPORT-CSV] Erro:", error);
      res.status(500).json({ error: "Erro ao exportar CSV" });
    }
  });

