  app.get("/api/beneficios/:id/imagem", async (req, res) => {
    try {
      const beneficioId = Number(req.params.id);
      const tipoReq = String(req.query.tipo || "").toLowerCase();

      const imagens = await storage.getBeneficioImagensByBeneficio(beneficioId);
      if (!imagens?.length)
        return res.status(404).send("Imagem não encontrada");

      let chosen: any =
        (tipoReq &&
          imagens.find((i: any) => (i.tipo ?? "").toLowerCase() === tipoReq)) ||
        imagens.find((i: any) => (i.tipo ?? "").toLowerCase() === "card") ||
        imagens[0];

      const bruto =
        chosen?.caminhoCompleto ??
        chosen?.caminho_completo ??
        chosen?.nomeArquivo ??
        chosen?.nome_arquivo ??
        chosen?.imagem ??
        "";

      const key = normalizeObjectKey(String(bruto));
      if (!key) return res.status(404).send("Imagem não encontrada");

      console.log("[IMG] bruto=", bruto, "-> key=", key);
      console.log("[IMG] bruto=", bruto, "-> key=", key);

      try {
        await streamSignedObjectToResponse(key, res, 300);
      } catch (gcsErr: any) {
        console.warn(
          "⚠️ [IMG] GCS falhou, retornando placeholder:",
          gcsErr?.code || gcsErr?.message
        );
        res.redirect(
          302,
          "https://via.placeholder.com/400x300?text=Imagem+Indispon%C3%ADvel"
        );
      }
    } catch (e) {
      console.error("❌ [/api/beneficios/:id/imagem] erro:", e);
      res.status(500).send("Erro interno");
    }
  });
  // ✨ ENDPOINT SEGURO PARA SALVAR REFERÊNCIA DA IMAGEM APÓS UPLOAD COMPLETADO
  // REQUER AUTENTICAÇÃO E PRIVILÉGIOS ADMINISTRATIVOS
  app.post(
    "/api/beneficios/:id/imagem-object-storage",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        const { id } = req.params;
        const {
          uploadedURL,
          originalName,
          fileSize,
          tipo = "card",
          largura,
          altura,
        } = req.body;

        if (!uploadedURL) {
          return res.status(400).json({ error: "URL da imagem é obrigatória" });
        }

        // Validação de segurança: verificar se URL é do bucket autorizado
        const bucketId = process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID;
        if (!uploadedURL.includes(bucketId || "repl-storage")) {
          console.warn(
            `🚨 [SECURITY] Tentativa de uso de URL não autorizada por admin ${req.session?.user?.id}: ${uploadedURL}`
          );
          return res.status(403).json({
            error: "URL não autorizada - deve ser do bucket oficial",
            details: "Use apenas URLs geradas pelo sistema de upload oficial",
          });
        }

        // Validar tipo
        if (!["card", "detalhes"].includes(tipo)) {
          return res
            .status(400)
            .json({ error: "Tipo deve ser 'card' ou 'detalhes'" });
        }

        // Validação de dimensões obrigatórias
        if (
          !largura ||
          !altura ||
          largura < 100 ||
          altura < 100 ||
          largura > 2000 ||
          altura > 2000
        ) {
          return res.status(400).json({
            error: "Dimensões inválidas ou ausentes",
            details: "Largura e altura devem estar entre 100px e 2000px",
          });
        }

        // Validação de tamanho de arquivo
        if (fileSize && fileSize > 5 * 1024 * 1024) {
          // 5MB máximo
          return res.status(400).json({
            error: "Arquivo muito grande",
            details: "Tamanho máximo permitido: 5MB",
          });
        }

        const beneficioId = parseInt(id);
        console.log(
          `✅ [SECURE OBJECT STORAGE] Admin ${req.session?.user?.id} salvando imagem ${tipo} para benefício ${beneficioId}: ${uploadedURL}`
        );

        // Verificar se benefício existe
        const beneficio = await storage.getBeneficio(beneficioId);
        if (!beneficio) {
          return res.status(404).json({ error: "Benefício não encontrado" });
        }

        // Validação de dimensões recomendadas
        const dimensoesRecomendadas = {
          card: { largura: 400, altura: 300, ratio: 4 / 3 },
          detalhes: { largura: 800, altura: 600, ratio: 4 / 3 },
        };

        const recomendado = dimensoesRecomendadas[tipo as "card" | "detalhes"];
        const ratioAtual = largura / altura;
        const ratioDiff = Math.abs(ratioAtual - recomendado.ratio);

        if (ratioDiff > 0.2) {
          // Tolerância de 20% no ratio (mais flexível)
          console.warn(
            `⚠️  [VALIDATION] Dimensões fora da recomendação para ${tipo}: ${largura}x${altura} (ratio: ${ratioAtual.toFixed(
              2
            )}). Recomendado: ${recomendado.largura}x${
              recomendado.altura
            } (ratio: ${recomendado.ratio.toFixed(2)})`
          );
        }

        // Remover imagem anterior do mesmo tipo se existir
        const imagensExistentes = await storage.getBeneficioImagensByBeneficio(
          beneficioId
        );
        const imagemAnteriorTipo = imagensExistentes.find(
          (img) => img.tipo === tipo
        );
        if (imagemAnteriorTipo) {
          await storage.deleteBeneficioImagem(imagemAnteriorTipo.id);
          console.log(
            `🗑️  [CLEANUP] Imagem ${tipo} anterior removida para benefício ${beneficioId}`
          );
        }

        // Extrair nome do arquivo da URL
        const fileName = uploadedURL.split("/").pop() || "unknown";

        // Criar registro da nova imagem
        const novaImagem = await storage.createBeneficioImagem({
          beneficioId,
          tipo,
          nomeArquivo: fileName,
          caminhoCompleto: uploadedURL,
          nomeOriginal: originalName || fileName,
          tipoMime: "image/jpeg", // Assumir JPEG por padrão (object storage converte)
          tamanhoBytes: fileSize || 0,
          largura: parseInt(largura),
          altura: parseInt(altura),
          ativo: true,
        });

        console.log(
          `✅ [SUCCESS] Imagem ${tipo} salva para benefício ${beneficioId} (${largura}x${altura}) por admin ${req.session?.user?.id}`
        );

        res.json({
          success: true,
          imagem: novaImagem,
          imagemCardUrl:
            tipo === "card"
              ? `/api/beneficios/${beneficioId}/imagem?tipo=card`
              : null,
          imagemDetalhesUrl:
            tipo === "detalhes"
              ? `/api/beneficios/${beneficioId}/imagem?tipo=detalhes`
              : null,
          securityNote: "Upload validado e autorizado",
        });
      } catch (error) {
        console.error(
          "❌ [SECURE OBJECT STORAGE] Erro ao salvar imagem do benefício:",
          error
        );
        res.status(500).json({ error: "Erro ao salvar imagem do benefício" });
      }
    }
  );

  // 🔧 ENDPOINT ADMINISTRATIVO: Tornar todas as imagens de benefícios públicas no GCS
  app.post(
    "/api/admin/beneficios/fix-permissions",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        console.log(
          `🔧 [FIX PERMISSIONS] Admin ${req.session?.user?.id} iniciando correção de permissões de imagens`
        );

        // Buscar todas as imagens de benefícios do banco
        const todasImagens = await db
          .select()
          .from(beneficioImagens)
          .where(eq(beneficioImagens.ativo, true));

        console.log(
          `📋 [FIX PERMISSIONS] Encontradas ${todasImagens.length} imagens ativas no banco`
        );

        const results = [];
        let sucessos = 0;
        let erros = 0;

        for (const imagem of todasImagens) {
          // Verificar se a imagem é do GCS
          if (imagem.caminhoCompleto.includes("storage.googleapis.com")) {
            try {
              // Extrair o caminho do arquivo da URL
              const filePath = imagem.caminhoCompleto
                .replace(`https://storage.googleapis.com/${BUCKET_NAME}/`, "")
                .replace(/^\//, "");

              const file = bucket.file(filePath);

              // Verificar se o arquivo existe
              const [exists] = await file.exists();

              if (exists) {
                // Tornar o arquivo público
                await file.makePublic();
                console.log(
                  `✅ [FIX PERMISSIONS] Imagem tornada pública: ${filePath}`
                );

                results.push({
                  beneficioId: imagem.beneficioId,
                  tipo: imagem.tipo,
                  url: imagem.caminhoCompleto,
                  status: "success",
                });
                sucessos++;
              } else {
                console.log(
                  `⚠️  [FIX PERMISSIONS] Arquivo não encontrado no GCS: ${filePath}`
                );
                results.push({
                  beneficioId: imagem.beneficioId,
                  tipo: imagem.tipo,
                  url: imagem.caminhoCompleto,
                  status: "not_found",
                });
                erros++;
              }
            } catch (error: any) {
              console.error(
                `❌ [FIX PERMISSIONS] Erro ao processar ${imagem.caminhoCompleto}:`,
                error.message
              );
              results.push({
                beneficioId: imagem.beneficioId,
                tipo: imagem.tipo,
                url: imagem.caminhoCompleto,
                status: "error",
                error: error.message,
              });
              erros++;
            }
          } else {
            // Imagem local, pular
            results.push({
              beneficioId: imagem.beneficioId,
              tipo: imagem.tipo,
              url: imagem.caminhoCompleto,
              status: "skipped_local",
            });
          }
        }

        console.log(
          `🎉 [FIX PERMISSIONS] Processo concluído: ${sucessos} sucessos, ${erros} erros`
        );

        res.json({
          success: true,
          message: `Permissões corrigidas: ${sucessos} imagens tornadas públicas`,
          total: todasImagens.length,
          sucessos,
          erros,
          results,
        });
      } catch (error: any) {
        console.error(
          "❌ [FIX PERMISSIONS] Erro ao corrigir permissões:",
          error
        );
        res.status(500).json({
          success: false,
          error: "Erro ao corrigir permissões das imagens",
          details: error.message,
        });
      }
    }
  );

