  // ===== REGULARIZAR SUBSCRIPTIONS COM PRODUTO ERRADO =====
  // Corrigir subscriptions que foram criadas com "Doação Clube do Grito" em vez do plano correto
  app.post("/api/admin/regularize-subscriptions", async (req, res) => {
    try {
      console.log(
        "🔧 [REGULARIZE] Iniciando regularização de subscriptions..."
      );

      if (!stripe) {
        return res.status(500).json({ error: "Stripe não configurado" });
      }

      // Buscar produto "Doação Clube do Grito"
      const products = await stripe.products.list({ active: true, limit: 100 });
      const donationProduct = products.data.find(
        (p) =>
          p.name === "Doação Clube do Grito" || p.metadata?.type === "donation"
      );

      if (!donationProduct) {
        return res.json({
          success: true,
          message:
            'Produto "Doação Clube do Grito" não encontrado - nada a regularizar',
          regularizados: 0,
        });
      }

      console.log(
        `📦 [REGULARIZE] Produto de doação encontrado: ${donationProduct.id}`
      );

      // Buscar subscriptions ativas
      const allSubs = await stripe.subscriptions.list({
        status: "active",
        limit: 100,
        expand: ["data.customer", "data.items.data.price"],
      });

      const subsParaCorrigir = allSubs.data.filter((sub) => {
        const productId = sub.items.data[0]?.price?.product;
        return productId === donationProduct.id;
      });

      console.log(
        `🔍 [REGULARIZE] ${subsParaCorrigir.length} subscriptions com produto "Doação" encontradas`
      );

      const resultados: any[] = [];

      for (const sub of subsParaCorrigir) {
        try {
          const customer = sub.customer as any;
          const priceItem = sub.items.data[0];
          const valorTotal = priceItem?.price?.unit_amount || 0;
          const interval = priceItem?.price?.recurring?.interval || "month";
          const intervalCount =
            priceItem?.price?.recurring?.interval_count || 1;

          // Calcular valor mensal
          let valorMensal = valorTotal / 100;
          if (interval === "month" && intervalCount > 1) {
            valorMensal = valorTotal / 100 / intervalCount;
          } else if (interval === "year") {
            valorMensal = valorTotal / 100 / 12;
          }

          // Determinar plano correto baseado no valor
          let planoCorreto = "platinum";
          if (valorMensal < 15) planoCorreto = "eco";
          else if (valorMensal < 25) planoCorreto = "voz";
          else if (valorMensal < 35) planoCorreto = "grito";

          // Determinar periodicidade
          let periodicidade = "mensal";
          if (interval === "year") periodicidade = "anual";
          else if (intervalCount === 3) periodicidade = "trimestral";
          else if (intervalCount === 6) periodicidade = "semestral";

          // Atualizar metadata da subscription
          await stripe.subscriptions.update(sub.id, {
            metadata: {
              ...sub.metadata,
              plan: planoCorreto,
              tier: planoCorreto,
              periodicity: periodicidade,
              periodicityLabel:
                periodicidade.charAt(0).toUpperCase() + periodicidade.slice(1),
              regularized: "true",
              regularizedAt: new Date().toISOString(),
              valorMensalCalculado: valorMensal.toFixed(2),
              flowVersion: "3.0-regularized",
            },
          });

          resultados.push({
            subscriptionId: sub.id,
            customer: customer?.name || customer?.email || "Desconhecido",
            valorTotal: valorTotal / 100,
            valorMensal: valorMensal,
            planoAnterior: sub.metadata?.plan || "indefinido",
            planoCorreto: planoCorreto,
            periodicidade: periodicidade,
            status: "regularizado",
          });

          console.log(
            `✅ [REGULARIZE] ${sub.id}: ${customer?.name} -> ${planoCorreto} (${periodicidade})`
          );
        } catch (error: any) {
          console.error(
            `❌ [REGULARIZE] Erro ao regularizar ${sub.id}:`,
            error.message
          );
          resultados.push({
            subscriptionId: sub.id,
            status: "erro",
            erro: error.message,
          });
        }
      }

      res.json({
        success: true,
        message: `${
          resultados.filter((r) => r.status === "regularizado").length
        } subscriptions regularizadas`,
        totalAnalisadas: subsParaCorrigir.length,
        regularizados: resultados.filter((r) => r.status === "regularizado")
          .length,
        erros: resultados.filter((r) => r.status === "erro").length,
        detalhes: resultados,
      });
    } catch (error: any) {
      console.error("❌ [REGULARIZE] Erro geral:", error);
      res.status(500).json({
        success: false,
        error: "Erro ao regularizar subscriptions",
        message: error.message,
      });
    }
  });

  // ===== SINCRONIZAÇÃO COM STRIPE =====
  // Buscar todos os pagamentos confirmados no Stripe e recriar registros
  app.post("/api/admin/sync-stripe-payments", async (req, res) => {
    try {
      console.log("🔄 [STRIPE SYNC] Iniciando sincronização com Stripe...");

      // Buscar TODOS os PaymentIntents (sem filtro de data para testar)
      const paymentIntents = await stripe.paymentIntents.list({
        limit: 100,
        expand: ["data.charges"],
      });

      console.log(
        `📋 [STRIPE SYNC] Encontrados ${paymentIntents.data.length} PaymentIntents nos últimos 30 dias`
      );

      let totalSyncronized = 0;
      let totalConfirmed = 0;

      for (const pi of paymentIntents.data) {
        console.log(
          `🔍 [STRIPE SYNC] Analisando PaymentIntent: ${pi.id} - Status: ${
            pi.status
          } - Amount: ${pi.amount / 100} - Metadata:`,
          pi.metadata
        );
        console.log(
          `🔍 [STRIPE SYNC] Status check: '${pi.status}' === 'succeeded' ? ${
            pi.status === "succeeded"
          }`
        );

        // Apenas processar pagamentos que foram confirmados
        if (pi.status === "succeeded") {
          totalConfirmed++;

          // Extrair metadados do usuário do payment intent
          const userId = pi.metadata?.userId;
          const valor = pi.amount / 100; // Converter de centavos para reais

          console.log(
            `✅ [STRIPE SYNC] Payment confirmado: ${
              pi.id
            } - User: ${userId} - Valor: R$ ${valor.toFixed(2)}`
          );

          if (userId) {
            console.log(
              `🔍 [STRIPE SYNC] Processando userId: ${userId} (type: ${typeof userId})`
            );
            try {
              // Verificar se já existe registro com este payment intent
              const existingDonation = await db
                .select()
                .from(doadores)
                .where(eq(doadores.stripePaymentIntentId, pi.id))
                .limit(1);

              console.log(
                `🔍 [STRIPE SYNC] Existing donations found: ${existingDonation.length}`
              );

              if (existingDonation.length === 0) {
                console.log(
                  `💾 [STRIPE SYNC] Inserindo nova doação: User ${userId} - R$ ${valor.toFixed(
                    2
                  )}`
                );

                // Criar novo registro apenas se não existir
                const newDonation = await db
                  .insert(doadores)
                  .values({
                    userId: parseInt(userId),
                    valor: valor,
                    valorTotal: valorTotal,
                    intervalCount: intervalCount,
                    plano: pi.metadata?.plano || "eco", // Pegar plano dos metadados
                    status: "paid", // ✅ Confirmado pelo Stripe
                    ativo: true,
                    stripePaymentIntentId: pi.id,
                    createdAt: new Date(pi.created * 1000), // Converter timestamp do Stripe
                  })
                  .returning();

                console.log(`✅ [STRIPE SYNC] Doação inserida:`, newDonation);

                totalSyncronized++;
                console.log(
                  `✅ [STRIPE SYNC] Pagamento sincronizado: User ${userId} - R$ ${valor.toFixed(
                    2
                  )} - ${pi.id}`
                );
              } else {
                console.log(`⏭️ [STRIPE SYNC] Pagamento já existe: ${pi.id}`);
              }
            } catch (error) {
              console.error(
                `❌ [STRIPE SYNC] Erro ao processar payment ${pi.id}:`,
                error
              );
            }
          } else {
            console.log(`⚠️ [STRIPE SYNC] Payment sem userId: ${pi.id}`);
          }
        }
      }

      console.log(
        `🎯 [STRIPE SYNC] Concluído: ${totalSyncronized} pagamentos sincronizados de ${totalConfirmed} confirmados`
      );

      res.json({
        success: true,
        message: `Sincronização concluída: ${totalSyncronized} pagamentos adicionados`,
        totalConfirmed,
        totalSyncronized,
      });
    } catch (error) {
      console.error("❌ [STRIPE SYNC] Erro na sincronização:", error);
      res.status(500).json({ error: "Erro ao sincronizar com Stripe" });
    }
  });

