  // 🔗 NOVA ROTA: Buscar missões de referral com informações completas
  app.get("/api/referrals/missions/:userId", async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);

      if (isNaN(userId)) {
        return res.status(400).json({ error: "ID de usuário inválido" });
      }

      // Buscar missões que permitem link de compartilhamento
      const missoesReferral = await db
        .select()
        .from(missoesSemanais)
        .where(
          and(
            eq(missoesSemanais.ativo, true),
            eq(missoesSemanais.habilitarLinkCompartilhamento, true)
          )
        )
        .orderBy(desc(missoesSemanais.recompensaGritos));

      // Para cada missão, buscar o progresso do usuário
      const missoesComProgresso = await Promise.all(
        missoesReferral.map(async (missao) => {
          // Verificar se já foi concluída
          const jaConcluida = await db
            .select()
            .from(missoesConcluidas)
            .where(
              and(
                eq(missoesConcluidas.userId, userId),
                eq(missoesConcluidas.missaoId, missao.id)
              )
            )
            .limit(1);

          // Contar referrals completos
          const referralsCompletos = await db
            .select()
            .from(referrals)
            .where(
              and(
                eq(referrals.referrerUserId, userId),
                eq(referrals.missaoId, missao.id),
                eq(referrals.status, "completo")
              )
            );

          const quantidadeNecessaria = missao.quantidadeAmigos || 1;
          const cadastrosCompletos = referralsCompletos.length;
          const progresso = Math.min(
            (cadastrosCompletos / quantidadeNecessaria) * 100,
            100
          );

          return {
            id: missao.id,
            titulo: missao.titulo,
            descricao: missao.descricao,
            recompensaGritos: missao.recompensaGritos,
            quantidadeAmigos: quantidadeNecessaria,
            tipoMissao: missao.tipoMissao,
            imagemUrl: missao.imagemUrl,

            // Progresso do usuário
            concluida: jaConcluida.length > 0,
            concluidaEm: jaConcluida[0]?.createdAt || null,
            cadastrosCompletos,
            progresso: parseFloat(progresso.toFixed(1)),
            podeCompletar:
              cadastrosCompletos >= quantidadeNecessaria &&
              jaConcluida.length === 0,
            // Links dos referrals para esta missão
            referrals: referralsCompletos.map((r) => ({
              id: r.id,
              linkConvite: r.linkConvite,
              codigoConvite: r.codigoConvite,
              completadoEm: r.completadoEm,
              referredUserId: r.referredUserId,
            })),
          };
        })
      );

      console.log(
        `📊 [REFERRAL MISSIONS] Usuário ${userId}: ${missoesComProgresso.length} missões de referral encontradas`
      );

      res.json({
        success: true,
        missoes: missoesComProgresso,
        summary: {
          totalMissoes: missoesComProgresso.length,
          concluidas: missoesComProgresso.filter((m) => m.concluida).length,
          emProgresso: missoesComProgresso.filter(
            (m) => !m.concluida && m.cadastrosCompletos > 0
          ).length,
          disponiveis: missoesComProgresso.filter(
            (m) => !m.concluida && m.cadastrosCompletos === 0
          ).length,
        },
      });
    } catch (error) {
      console.error("Erro ao buscar missões de referral:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // ================ APIS DE INDICAÇÃO NO PERFIL ================

  // API para aplicar código de referral (usuário indica que foi convidado)
  app.post("/api/aplicar-codigo-referral", async (req, res) => {
    try {
      const { userId, codigoReferral: codigoRaw } = req.body;

      // Extrair código do link se for URL completa
      let codigoReferral = codigoRaw.trim();

      // Se contém "ref=" ou "?ref=", extrair o código
      if (codigoReferral.includes("ref=")) {
        const match = codigoReferral.match(/[?&]ref=([^&]+)/);
        if (match) {
          codigoReferral = decodeURIComponent(match[1]);
          console.log(
            `🔗 [APLICAR REFERRAL] Código extraído do link: ${codigoReferral}`
          );
        }
      }

      // Se é uma URL mas não tem ref=, tentar extrair última parte do path
      if (codigoReferral.includes("://") && !codigoReferral.includes("ref=")) {
        try {
          const url = new URL(codigoReferral);
          const pathParts = url.pathname.split("/").filter(Boolean);
          if (pathParts.length > 0) {
            codigoReferral = pathParts[pathParts.length - 1];
            console.log(
              `🔗 [APLICAR REFERRAL] Código extraído do path: ${codigoReferral}`
            );
          }
        } catch (e) {
          // Não é URL válida, usar como está
        }
      }

      if (!userId || !codigoRaw) {
        return res
          .status(400)
          .json({ error: "userId e codigoReferral são obrigatórios" });
      }

      console.log(
        `🔗 [APLICAR REFERRAL] Usuário ${userId} tentando aplicar código: ${codigoReferral}`
      );

      // Verificar se o usuário já tem um código aplicado em referrals
      const jaIndicadoReferral = await db
        .select()
        .from(referrals)
        .where(eq(referrals.referredUserId, parseInt(userId)))
        .limit(1);

      // Também verificar na tabela indicacoes
      const jaIndicadoIndicacoes = await db
        .select()
        .from(indicacoes)
        .where(eq(indicacoes.indicadoId, parseInt(userId)))
        .limit(1);

      if (jaIndicadoReferral[0] || jaIndicadoIndicacoes[0]) {
        console.log(
          `⚠️ [APLICAR REFERRAL] Usuário ${userId} já foi indicado antes`
        );
        return res
          .status(400)
          .json({ error: "Você já possui um código de indicação aplicado" });
      }

      // PRIMEIRO: Tentar buscar na tabela referrals (códigos tipo REF_xxx das missões)
      const referralData = await db
        .select()
        .from(referrals)
        .where(eq(referrals.codigoConvite, codigoReferral))
        .limit(1);

      if (referralData[0]) {
        // É um código de missão (referral)
        const referral = referralData[0];

        // Verificar se o referral já foi usado
        if (referral.referredUserId) {
          console.log(
            `⚠️ [APLICAR REFERRAL] Código já foi usado por outro usuário`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação já foi utilizado" });
        }

        // Verificar se não está expirado
        if (referral.expiradoEm && new Date(referral.expiradoEm) < new Date()) {
          console.log(
            `⏰ [APLICAR REFERRAL] Código expirado: ${codigoReferral}`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação expirou" });
        }

        // Verificar se o usuário não está tentando usar seu próprio código
        if (referral.referrerUserId === parseInt(userId)) {
          console.log(
            `🚫 [APLICAR REFERRAL] Usuário tentando usar próprio código`
          );
          return res.status(400).json({
            error: "Você não pode usar seu próprio código de indicação",
          });
        }

        // Atualizar o referral com o usuário indicado
        await db
          .update(referrals)
          .set({
          horarioInicio,
          horarioFim,
          diasSemana,
            referredUserId: parseInt(userId),
            status: "cadastrou",
            cadastrouEm: new Date(),
          })
          .where(eq(referrals.id, referral.id));

        // Buscar nome de quem indicou
        const indicador = await db
          .select({ nome: users.nome, sobrenome: users.sobrenome })
          .from(users)
          .where(eq(users.id, referral.referrerUserId))
          .limit(1);

        const nomeIndicador = indicador[0]
          ? `${indicador[0].nome || ""} ${
              indicador[0].sobrenome || ""
            }`.trim() || "Um amigo"
          : "Um amigo";

        console.log(
          `✅ [APLICAR REFERRAL] Código de missão aplicado! Usuário ${userId} foi indicado por ${referral.referrerUserId}`
        );

        return res.json({
          success: true,
          message: `Parabéns! Você foi indicado por ${nomeIndicador}`,
          indicadorNome: nomeIndicador,
          indicadorId: referral.referrerUserId,
          tipo: "missao",
        });
      }

      // SEGUNDO: Tentar buscar na tabela marketing_links (códigos de campanhas de marketing)
      const marketingLinkData = await db
        .select()
        .from(marketingLinks)
        .where(eq(marketingLinks.code, codigoReferral))
        .limit(1);

      if (marketingLinkData[0]) {
        // É um código de marketing
        const marketingLink = marketingLinkData[0];

        // Verificar se está ativo
        if (!marketingLink.isActive) {
          console.log(
            `❌ [APLICAR REFERRAL] Link de marketing inativo: ${codigoReferral}`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação não está mais ativo" });
        }

        // Verificar se não está expirado
        if (
          marketingLink.expiresAt &&
          new Date(marketingLink.expiresAt) < new Date()
        ) {
          console.log(
            `⏰ [APLICAR REFERRAL] Link de marketing expirado: ${codigoReferral}`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação expirou" });
        }

        // Verificar se o usuário não está tentando usar seu próprio código
        if (marketingLink.rewardToUserId === parseInt(userId)) {
          console.log(
            `🚫 [APLICAR REFERRAL] Usuário tentando usar próprio código de marketing`
          );
          return res.status(400).json({
            error: "Você não pode usar seu próprio código de indicação",
          });
        }

        // Registrar a indicação na tabela indicacoes (se tiver rewardToUserId)
        if (marketingLink.rewardToUserId) {
          const validade = new Date();
          validade.setDate(validade.getDate() + 30);

          await db.insert(indicacoes).values({
            indicouId: marketingLink.rewardToUserId,
            indicadoId: parseInt(userId),
            refCode: codigoReferral,
            status: "CONFIRMADA",
            criadaEm: new Date(),
            confirmadaEm: new Date(),
            validade: validade,
          });
        }

        // Buscar nome de quem criou o link (se tiver rewardToUserId)
        let nomeIndicador = "Campanha do Clube do Grito";
        if (marketingLink.rewardToUserId) {
          const indicador = await db
            .select({ nome: users.nome, sobrenome: users.sobrenome })
            .from(users)
            .where(eq(users.id, marketingLink.rewardToUserId))
            .limit(1);

          if (indicador[0]) {
            nomeIndicador =
              `${indicador[0].nome || ""} ${
                indicador[0].sobrenome || ""
              }`.trim() || "Um amigo";
          }
        }

        console.log(
          `✅ [APLICAR REFERRAL] Código de marketing aplicado! Usuário ${userId} veio do link ${marketingLink.id}`
        );

        return res.json({
          success: true,
          message: `Parabéns! Você foi indicado por ${nomeIndicador}`,
          indicadorNome: nomeIndicador,
          indicadorId: marketingLink.rewardToUserId || null,
          tipo: "marketing",
        });
      }

      // Se não encontrou em nenhuma das duas tabelas
      console.log(
        `❌ [APLICAR REFERRAL] Código não encontrado em nenhuma tabela: ${codigoReferral}`
      );
      return res
        .status(404)
        .json({ error: "Código de indicação não encontrado" });
    } catch (error) {
      console.error("❌ [APLICAR REFERRAL] Erro:", error);
      res.status(500).json({ error: "Erro ao aplicar código de indicação" });
    }
  });

  // API para listar quem o usuário indicou
  app.get("/api/minhas-indicacoes-referral/:userId", async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);

      if (isNaN(userId)) {
        return res.status(400).json({ error: "ID de usuário inválido" });
      }

      console.log(
        `📋 [MINHAS INDICAÇÕES] Buscando indicações do usuário ${userId}`
      );

      // Buscar todos os referrals onde este usuário é o referrer
      const minhasIndicacoes = await db
        .select({
          id: referrals.id,
          referredUserId: referrals.referredUserId,
          codigoConvite: referrals.codigoConvite,
          linkConvite: referrals.linkConvite,
          status: referrals.status,
          cadastrouEm: referrals.cadastrouEm,
          doouEm: referrals.doouEm,
          completadoEm: referrals.completadoEm,
          createdAt: referrals.createdAt,
          gritosRecompensa: referrals.gritosRecompensa,
          indicadoNome: users.nome,
          indicadoSobrenome: users.sobrenome,
          indicadoTelefone: users.telefone,
        })
        .from(referrals)
        .leftJoin(users, eq(referrals.referredUserId, users.id))
        .where(eq(referrals.referrerUserId, userId))
        .orderBy(desc(referrals.createdAt));

      // Formatar dados para resposta
      const indicacoes = minhasIndicacoes.map((ind) => ({
        id: ind.id,
        codigo: ind.codigoConvite,
        link: ind.linkConvite,
        status: ind.status,
        indicado: ind.referredUserId
          ? {
              id: ind.referredUserId,
              nome:
                `${ind.indicadoNome || ""} ${
                  ind.indicadoSobrenome || ""
                }`.trim() || "Usuário",
              telefone: ind.indicadoTelefone
                ? `****${ind.indicadoTelefone.slice(-4)}`
                : null,
            }
          : null,
        cadastrouEm: ind.cadastrouEm,
        doouEm: ind.doouEm,
        completadoEm: ind.completadoEm,
        criadoEm: ind.createdAt,
        gritosRecompensa: ind.gritosRecompensa,
      }));

      // Estatísticas
      const stats = {
        total: indicacoes.length,
        pendentes: indicacoes.filter((i) => i.status === "pendente").length,
        cadastrados: indicacoes.filter((i) => i.status === "cadastrou").length,
        completos: indicacoes.filter((i) => i.status === "completo").length,
      };

      console.log(
        `📊 [MINHAS INDICAÇÕES] Usuário ${userId}: ${stats.total} indicações (${stats.completos} completas)`
      );

      res.json({
        success: true,
        indicacoes,
        stats,
      });
    } catch (error) {
      console.error("❌ [MINHAS INDICAÇÕES] Erro:", error);
      res.status(500).json({ error: "Erro ao buscar indicações" });
    }
  });

  // API para verificar se usuário já tem código aplicado
  app.get("/api/meu-indicador/:userId", async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);

      if (isNaN(userId)) {
        return res.status(400).json({ error: "ID de usuário inválido" });
      }

      // Buscar se este usuário foi indicado por alguém
      const indicacao = await db
        .select({
          referralId: referrals.id,
          indicadorId: referrals.referrerUserId,
          codigoConvite: referrals.codigoConvite,
          cadastrouEm: referrals.cadastrouEm,
          indicadorNome: users.nome,
          indicadorSobrenome: users.sobrenome,
        })
        .from(referrals)
        .leftJoin(users, eq(referrals.referrerUserId, users.id))
        .where(eq(referrals.referredUserId, userId))
        .limit(1);

      if (!indicacao[0]) {
        // Não encontrou em referrals, buscar na tabela indicacoes (marketing)
        const indicacaoMkt = await db
          .select({
            indicouId: indicacoes.indicouId,
            refCode: indicacoes.refCode,
            criadaEm: indicacoes.criadaEm,
            indicadorNome: users.nome,
            indicadorSobrenome: users.sobrenome,
          })
          .from(indicacoes)
          .leftJoin(users, eq(indicacoes.indicouId, users.id))
          .where(eq(indicacoes.indicadoId, userId))
          .limit(1);

        if (!indicacaoMkt[0]) {
          return res.json({
            temIndicador: false,
            indicador: null,
          });
        }

        const indMkt = indicacaoMkt[0];
        return res.json({
          temIndicador: true,
          indicador: {
            id: indMkt.indicouId,
            nome:
              `${indMkt.indicadorNome || ""} ${
                indMkt.indicadorSobrenome || ""
              }`.trim() || "Um amigo",
            codigoUsado: indMkt.refCode,
            dataIndicacao: indMkt.criadaEm,
          },
        });
      }

      const ind = indicacao[0];
      res.json({
        temIndicador: true,
        indicador: {
          id: ind.indicadorId,
          nome:
            `${ind.indicadorNome || ""} ${
              ind.indicadorSobrenome || ""
            }`.trim() || "Um amigo",
          codigoUsado: ind.codigoConvite,
          dataIndicacao: ind.cadastrouEm,
        },
      });
    } catch (error) {
      console.error("❌ [MEU INDICADOR] Erro:", error);
      res.status(500).json({ error: "Erro ao buscar indicador" });
    }
  });
  // ================ MONDAY.COM GV API ================

  // Função para mapear dados raw do Monday.com para formato estruturado
  function mapMondayDataToGVFormat(rawData: any): GVApiResponse {
    console.log("🔄 [MONDAY GV] Mapeando dados do Monday.com para formato GV");

    // Definir mapeamento de boards reais para programas GV
    const boardToProgram: Record<
      string,
      { slug: string; workstreams: string[] }
    > = {
      // Marketing
      "Painel de Seguidores e Post": {
        slug: "marketing",
        workstreams: ["seguidores", "posts"],
      },

      // Esporte e Cultura
      "Painel de Polo de Gloria": {
        slug: "esporte-cultura",
        workstreams: ["polo-gloria"],
      },
      "Painel de Casa Sonhar": {
        slug: "esporte-cultura",
        workstreams: ["casa-sonhar"],
      },
      "Sala Serenata": {
        slug: "esporte-cultura",
        workstreams: ["serenata"],
      },

      // Inclusão Produtiva
      "Painel Vozes do Futuro": {
        slug: "inclusao-produtiva",
        workstreams: ["vozes-futuro"],
      },
      "Cursos 30h": {
        slug: "inclusao-produtiva",
        workstreams: ["cursos-30h"],
      },
      "Cursos EAD": {
        slug: "inclusao-produtiva",
        workstreams: ["cursos-ead"],
      },

      // Psicossocial
      "Atividade transversal": {
        slug: "psicossocial",
        workstreams: ["atividade-transversal"],
      },
      "Caravana do Grito": {
        slug: "psicossocial",
        workstreams: ["caravana-grito"],
      },

      // Favela 3D
      "Painel Decolagem": {
        slug: "favela-3d",
        workstreams: ["decolagem"],
      },
      "Painel Desenvolvimento Social": {
        slug: "favela-3d",
        workstreams: ["desenvolvimento-social"],
      },
      "Painel de Emprego e Renda": {
        slug: "favela-3d",
        workstreams: ["emprego-renda"],
      },
    };

    // Estrutura base para resposta
    const mappedData: GVApiResponse = {
      period:
        new Date().getFullYear() +
        "-Q" +
        Math.ceil((new Date().getMonth() + 1) / 3),
      programs: [],
    };

    // Verificar se há boards disponíveis
    if (!rawData || !rawData.boards || rawData.boards.length === 0) {
      console.log(
        "⚠️ [MONDAY GV] Nenhum board encontrado - retornando estrutura de configuração pendente"
      );

      // Retornar estrutura indicando que a configuração está pendente
      mappedData.programs = [
        {
          slug: "setup-pending",
          workstreams: [
            {
              slug: "configuracao-necessaria",
              indicators: [
                {
                  indicator: "Status da Integração",
                  value: 0,
                  unit: "configurado",
                  target: 1,
                },
              ],
            },
          ],
        },
      ];

      return mappedData;
    }

    console.log(
      `📋 [MONDAY GV] Processando ${rawData.boards.length} boards encontrados`
    );

    // Agrupar boards por programa
    const programsMap = new Map<string, { workstreams: Map<string, any[]> }>();

    for (const board of rawData.boards) {
      console.log(
        `🔍 [MONDAY GV] Processando board: "${board.name}" (ID: ${board.id})`
      );

      // Verificar se o board é reconhecido
      const programInfo = boardToProgram[board.name];
      if (!programInfo) {
        console.log(
          `⚠️ [MONDAY GV] Board "${board.name}" não reconhecido - ignorando`
        );
        continue;
      }

      console.log(
        `✅ [MONDAY GV] Board "${board.name}" mapeado para programa "${programInfo.slug}"`
      );

      // Inicializar programa se não existir
      if (!programsMap.has(programInfo.slug)) {
        programsMap.set(programInfo.slug, { workstreams: new Map() });
      }

      const program = programsMap.get(programInfo.slug)!;

      // Processar workstreams do board
      for (const workstreamSlug of programInfo.workstreams) {
        if (!program.workstreams.has(workstreamSlug)) {
          program.workstreams.set(workstreamSlug, []);
        }

        // Extrair indicadores dos items do board
        const indicators: any[] = [];

        if (board.items_page && board.items_page.items) {
          console.log(
            `📊 [MONDAY GV] Processando ${board.items_page.items.length} items do board "${board.name}"`
          );

          for (const item of board.items_page.items) {
            if (!item.column_values) continue;

            // Processar cada coluna como um possível indicador
            for (const columnValue of item.column_values) {
              if (!columnValue.column || !columnValue.text) continue;

              const indicatorName = columnValue.column.title;
              const textValue = columnValue.text;

              // Tentar extrair valor numérico
              let numericValue = 0;
              let unit = "unidade";

              // Detectar diferentes tipos de valores
              if (textValue.includes("%")) {
                numericValue = parseFloat(textValue.replace("%", "")) / 100;
                unit = "%";
              } else if (textValue.includes("R$")) {
                numericValue = parseFloat(
                  textValue.replace(/[R$\s,]/g, "").replace(".", "")
                );
                unit = "R$";
              } else {
                const parsed = parseFloat(
                  textValue.replace(/[^\d.,]/g, "").replace(",", ".")
                );
                if (!isNaN(parsed)) {
                  numericValue = parsed;

                  // Inferir unidade baseada no nome do indicador
                  if (
                    indicatorName.toLowerCase().includes("pessoa") ||
                    indicatorName.toLowerCase().includes("usuário")
                  ) {
                    unit = "pessoas";
                  } else if (indicatorName.toLowerCase().includes("evento")) {
                    unit = "eventos";
                  } else if (indicatorName.toLowerCase().includes("curso")) {
                    unit = "cursos";
                  } else {
                    unit = "unidade";
                  }
                }
              }

              // Adicionar indicador se tiver valor válido
              if (
                numericValue > 0 ||
                textValue.toLowerCase().includes("zero") ||
                textValue === "0"
              ) {
                indicators.push({
                  indicator: indicatorName,
                  value: numericValue,
                  unit: unit,
                  target: numericValue * 1.2, // Target 20% maior como padrão
                });

                console.log(
                  `📈 [MONDAY GV] Indicador extraído: ${indicatorName} = ${numericValue} ${unit}`
                );
              }
            }
          }
        }

        // Adicionar indicadores ao workstream se houver algum
        if (indicators.length > 0) {
          program.workstreams.get(workstreamSlug)!.push(...indicators);
          console.log(
            `✅ [MONDAY GV] ${indicators.length} indicadores adicionados ao workstream "${workstreamSlug}"`
          );
        }
      }
    }

    // Converter mapa para estrutura final
    for (const [programSlug, programData] of programsMap) {
      const workstreams: any[] = [];

      for (const [workstreamSlug, indicators] of programData.workstreams) {
        if (indicators.length > 0) {
          workstreams.push({
            slug: workstreamSlug,
            indicators: indicators,
          });
        }
      }

      if (workstreams.length > 0) {
        mappedData.programs.push({
          slug: programSlug,
          workstreams: workstreams,
        });
      }
    }

    console.log(
      `✅ [MONDAY GV] Mapeamento concluído: ${mappedData.programs.length} programas processados`
    );

    return mappedData;
  }

  // Função para buscar dados do Monday.com
  async function fetchMondayGVData(): Promise<GVApiResponse> {
    const mondayApiKey = process.env.MONDAY_API_KEY;

    if (!mondayApiKey) {
      throw new Error("Monday.com API key not configured");
    }

    // API oficial do Monday.com
    const mondayApiUrl = "https://api.monday.com/v2";

    console.log(
      `🔗 [MONDAY GV] Conectando com Monday.com API: ${mondayApiUrl}`
    );

    try {
      // Query GraphQL para buscar boards específicos da organização
      const query = `
        query {
          boards(limit: 50) {
            id
            name
            description
            state
            type
            items_page(limit: 20) {
              items {
                id
                name
                column_values {
                  column {
                    title
                    type
                  }
                  text
                  value
                }
              }
            }
          }
        }
      `;

      const response = await fetch(mondayApiUrl, {
        method: "POST",
        headers: {
          Authorization: mondayApiKey,
          "Content-Type": "application/json",
          "API-Version": "2024-10",
        },
        body: JSON.stringify({ query }),
      });

      if (!response.ok) {
        throw new Error(
          `Monday.com API failed: ${response.status} ${response.statusText}`
        );
      }

      const result = await response.json();

      if (result.errors) {
        throw new Error(
          `Monday.com GraphQL errors: ${JSON.stringify(result.errors)}`
        );
      }

      // Mapear os dados raw do Monday.com para o formato estruturado esperado
      const mappedData = mapMondayDataToGVFormat(result.data);

      return mappedData;
    } catch (error) {
      console.error("❌ [MONDAY GV] Erro ao buscar dados:", error);
      throw error;
    }
  }

