  // Endpoint para buscar data da primeira doação do usuário
  app.get("/api/users/:id/first-donation-date", async (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      if (isNaN(userId)) {
        return res.status(400).json({ error: "ID de usuário inválido" });
      }

      // Buscar primeira doação do usuário
      const firstDonation = await db
        .select({
          createdAt: doadores.createdAt,
          status: doadores.status,
        })
        .from(doadores)
        .where(and(eq(doadores.userId, userId), eq(doadores.status, "paid")))
        .orderBy(doadores.createdAt)
        .limit(1);

      // Se não encontrar doação, usar data atual como fallback
      const donationDate = firstDonation[0]?.createdAt || new Date();

      // Normalizar formato da data
      const isoDate = donationDate.toISOString();
      const day = donationDate.getDate();
      const month = donationDate.getMonth() + 1; // JavaScript months are 0-indexed
      const year = donationDate.getFullYear();

      const monthNames = [
        "",
        "janeiro",
        "fevereiro",
        "março",
        "abril",
        "maio",
        "junho",
        "julho",
        "agosto",
        "setembro",
        "outubro",
        "novembro",
        "dezembro",
      ];

      const monthNamePt = monthNames[month];

      console.log(
        `📅 [FIRST DONATION] Usuário ${userId}: ${day} de ${monthNamePt} de ${year}`
      );

      res.json({
        isoDate,
        day,
        month,
        year,
        monthNamePt,
      });
    } catch (error) {
      console.error("❌ Erro ao buscar data da primeira doação:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // 💰 Endpoint para buscar estatísticas de doações do Stripe
  app.get("/api/users/:userId/donation-stats", async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);

      if (isNaN(userId)) {
        return res.status(400).json({ error: "ID de usuário inválido" });
      }

      console.log(
        `💰 [DONATION STATS] Buscando estatísticas para usuário ${userId}...`
      );

      // 1. Buscar Stripe Customer ID e Subscription ID do usuário
      const user = await db
        .select({
          stripeCustomerId: users.stripeCustomerId,
          stripeSubscriptionId: users.stripeSubscriptionId,
        })
        .from(users)
        .where(eq(users.id, userId))
        .limit(1);

      if (!user || user.length === 0) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      const stripeCustomerId = user[0].stripeCustomerId;
      const stripeSubscriptionId = user[0].stripeSubscriptionId;

      if (!stripeCustomerId) {
        console.log(
          `⚠️ [DONATION STATS] Usuário ${userId} não tem Stripe Customer ID`
        );
        return res.json({
          totalDoado: 0,
          metaAnual: 0,
          progresso: 0,
          valorMensal: 0,
          periodicidade: "monthly",
          mesesFaltando: 12,
          primeiraDoacao: null,
        });
      }

      console.log(
        `🔍 [DONATION STATS] Stripe Customer ID: ${stripeCustomerId}`
      );
      console.log(
        `🔍 [DONATION STATS] Stripe Subscription ID: ${
          stripeSubscriptionId || "Nenhuma"
        }`
      );

      // 2. Buscar CHARGES (ao invés de invoices) para capturar todas as cobranças
      // Charges incluem pagamentos avulsos que não aparecem em invoices
      console.log(
        `💳 [DONATION STATS] Buscando charges por customer: ${stripeCustomerId}`
      );
      const charges = await stripe.charges.list({
        customer: stripeCustomerId,
        limit: 100,
      });

      console.log(
        `📊 [DONATION STATS] Encontradas ${charges.data.length} charges`
      );

      // 3. Calcular total usando amount_refunded do Stripe
      // Para charges, amount_refunded contém o valor exato reembolsado
      let totalPagoCentavos = 0;
      let totalReembolsadoCentavos = 0;

      for (const charge of charges.data) {
        // Só contar charges bem-sucedidas
        if (charge.status === "succeeded") {
          const amountPaid = charge.amount || 0;
          const refundedAmount = charge.amount_refunded || 0;

          totalPagoCentavos += amountPaid;
          totalReembolsadoCentavos += refundedAmount;
        }
      }

      console.log(
        `💸 [DONATION STATS] Total reembolsado: R$ ${(
          totalReembolsadoCentavos / 100
        ).toFixed(2)}`
      );
      console.log(
        `💵 [DONATION STATS] Total bruto (antes refunds): R$ ${(
          totalPagoCentavos / 100
        ).toFixed(2)}`
      );

      // Total líquido = total pago - total reembolsado
      const totalDoado = (totalPagoCentavos - totalReembolsadoCentavos) / 100;

      console.log(
        `💵 [DONATION STATS] Total líquido (após refunds): R$ ${totalDoado.toFixed(
          2
        )}`
      );

      // 4. Buscar assinatura ativa para determinar meta anual
      const subscriptions = await stripe.subscriptions.list({
        customer: user.stripeCustomerId,
        status: "active",
        limit: 1,
      });

      let metaAnual = 0;
      let valorMensal = 0;
      let periodicidade = "monthly";
      let mesesFaltando = 12;

      if (subscriptions.data.length > 0) {
        const subscription = subscriptions.data[0];

        // Pegar o valor da assinatura (primeiro item)
        if (subscription.items.data.length > 0) {
          const item = subscription.items.data[0];
          const valorCentavos = item.price.unit_amount || 0;
          valorMensal = valorCentavos / 100;

          // Determinar periodicidade
          const interval = item.price.recurring?.interval || "month";
          const intervalCount = item.price.recurring?.interval_count || 1;

          if (interval === "month") {
            periodicidade =
              intervalCount === 1
                ? "monthly"
                : intervalCount === 3
                ? "quarterly"
                : intervalCount === 6
                ? "semiannual"
                : "custom";
          } else if (interval === "year") {
            periodicidade = "annual";
          }

          // Calcular meta anual (assumindo 12 meses)
          if (periodicidade === "monthly") {
            metaAnual = valorMensal * 12;
          } else if (periodicidade === "quarterly") {
            metaAnual = valorMensal * 4;
          } else if (periodicidade === "semiannual") {
            metaAnual = valorMensal * 2;
          } else if (periodicidade === "annual") {
            metaAnual = valorMensal;
          }

          console.log(
            `🎯 [DONATION STATS] Meta anual: R$ ${metaAnual.toFixed(
              2
            )} (${periodicidade})`
          );
        }
      } else {
        console.log(
          `⚠️ [DONATION STATS] Usuário ${userId} não tem assinatura ativa`
        );
      }

      // 5. Calcular progresso e meses faltando
      const progresso =
        metaAnual > 0 ? Math.min((totalDoado / metaAnual) * 100, 100) : 0;

      // Calcular meses faltando baseado no total doado vs meta anual
      // IMPORTANTE: Considerar periodicidade para calcular meses pagos corretamente
      if (metaAnual > 0 && valorMensal > 0) {
        let mesesPagos = 0;

        if (periodicidade === "monthly") {
          // Cada pagamento = 1 mês
          mesesPagos = Math.floor(totalDoado / valorMensal);
        } else if (periodicidade === "quarterly") {
          // Cada pagamento trimestral = 3 meses
          const pagosTrimestres = Math.floor(totalDoado / valorMensal);
          mesesPagos = pagosTrimestres * 3;
        } else if (periodicidade === "semiannual") {
          // Cada pagamento semestral = 6 meses
          const pagosSemestres = Math.floor(totalDoado / valorMensal);
          mesesPagos = pagosSemestres * 6;
        } else if (periodicidade === "annual") {
          // Cada pagamento anual = 12 meses
          const pagosAnos = Math.floor(totalDoado / valorMensal);
          mesesPagos = pagosAnos * 12;
        }

        mesesFaltando = Math.max(12 - mesesPagos, 0);
      }

      // 6. Buscar data da primeira doação
      const primeiraDoacao =
        charges.data.length > 0
          ? charges.data[charges.data.length - 1].created * 1000 // Converter timestamp Unix para ms
          : null;

      console.log(
        `✅ [DONATION STATS] Progresso: ${progresso.toFixed(
          1
        )}%, Meses faltando: ${mesesFaltando}`
      );

      // Desabilitar cache HTTP para evitar problemas com 304 Not Modified
      res.set("Cache-Control", "no-store, no-cache, must-revalidate, private");
      res.set("Pragma", "no-cache");
      res.set("Expires", "0");

      res.json({
        totalDoado: parseFloat(totalDoado.toFixed(2)),
        metaAnual: parseFloat(metaAnual.toFixed(2)),
        progresso: parseFloat(progresso.toFixed(1)),
        valorMensal: parseFloat(valorMensal.toFixed(2)),
        periodicidade,
        mesesFaltando,
        primeiraDoacao,
      });
    } catch (error: any) {
      console.error("❌ [DONATION STATS] Erro ao buscar estatísticas:", error);
      res.status(500).json({
        error: "Erro ao buscar estatísticas de doações",
        message: error?.message,
      });
    }
  });

