  // PUT /api/pec/instances/:id - Atualizar turma
  app.put("/api/pec/instances/:id", async (req, res) => {
    try {
      const id = parseInt(req.params.id);
      const instanceData = req.body;
      console.log(`📋 Updating PEC instance ${id}:`, instanceData);

      // Verificar se a turma existe
      const existing = await db
        .select()
        .from(activityInstances)
        .where(eq(activityInstances.id, id))
        .limit(1);
      if (existing.length === 0) {
        return res.status(404).json({ error: "Turma não encontrada" });
      }

      // Atualizar turma
      const [updated] = await db
        .update(activityInstances)
        .set({
          horarioInicio,
          horarioFim,
          diasSemana,
          title: instanceData.title,
          code: instanceData.code,
          location: instanceData.location,
          situation: instanceData.situation,
          period_label: instanceData.period_label,
          start_time: instanceData.start_time,
          end_time: instanceData.end_time,
          age_min: instanceData.age_min,
          age_max: instanceData.age_max,
          occurrence_start: instanceData.occurrence_start,
          occurrence_end: instanceData.occurrence_end,
          expected_total_hours: instanceData.expected_total_hours,
          notes: instanceData.notes,
          control_mode: instanceData.control_mode,
          intelbras_group_id: instanceData.intelbras_group_id,
          updated_at: new Date(),
        })
        .where(eq(activityInstances.id, id))
        .returning();

      console.log(`✅ PEC instance ${id} updated successfully`);
      res.json({
        success: true,
        message: "Turma atualizada com sucesso",
        instance: updated,
      });
    } catch (error: any) {
      console.error("❌ Error updating PEC instance:", error);
      res
        .status(500)
        .json({ error: "Erro ao atualizar turma", details: error.message });
    }
  });

