  // ===== INTEGRAÇÃO CIELO - FUNÇÕES AUXILIARES =====

  // Consultar status de transação por PaymentId (API E-commerce Cielo)
  async function consultarTransacaoCieloEcommerce(
    paymentId: string
  ): Promise<any> {
    try {
      const merchantId = process.env.MERCHANT_ID_CIELO;
      const merchantKey = process.env.MERCHANT_KEY_CIELO;

      if (!merchantId || !merchantKey) {
        console.error("❌ [CIELO] Credenciais não configuradas");
        return null;
      }

      // API E-commerce usa MerchantId e MerchantKey direto nos headers
      const url = `https://apiquery.cieloecommerce.cielo.com.br/1/sales/${paymentId}`;

      const response = await fetch(url, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          MerchantId: merchantId,
          MerchantKey: merchantKey,
        },
      });

      if (!response.ok) {
        if (response.status === 404) {
          return null; // Transação não encontrada
        }
        const errorText = await response.text();
        console.error(
          `❌ [CIELO QUERY] Erro HTTP ${response.status} para PaymentId ${paymentId}: ${errorText}`
        );
        return null;
      }

      const data = await response.json();
      return data;
    } catch (error) {
      console.error(
        `❌ [CIELO QUERY] Erro ao consultar transação ${paymentId}:`,
        error
      );
      return null;
    }
  }

  // ===== ATUALIZAR STATUS CIELO MANUAL (em lote) =====
  app.post(
    "/api/admin/cielo/atualizar-status-manual",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        const { ingressoIds, novoStatus } = req.body;

        if (
          !ingressoIds ||
          !Array.isArray(ingressoIds) ||
          ingressoIds.length === 0
        ) {
          return res.status(400).json({
            success: false,
            error: "IDs de ingressos inválidos",
          });
        }

        if (!["confirmado", "cancelado", "negado"].includes(novoStatus)) {
          return res.status(400).json({
            success: false,
            error: "Status inválido. Use: confirmado, cancelado ou negado",
          });
        }

        console.log(
          `🔄 [CIELO MANUAL] Atualizando ${ingressoIds.length} ingressos para status: ${novoStatus}`
        );

      // Atualizar em lote
      await db
        .update(ingressos)
        .set({ status: novoStatus })
        .where(
          and(
            inArray(ingressos.id, ingressoIds),
            eq(ingressos.gateway, 'cielo_checkout_link')
          )
        );

        console.log(
          `✅ [CIELO MANUAL] ${ingressoIds.length} ingressos atualizados`
        );

        res.json({
          success: true,
          atualizados: ingressoIds.length,
          novoStatus,
        });
      } catch (error) {
        console.error("❌ [CIELO MANUAL] Erro:", error);
        res
          .status(500)
          .json({ success: false, error: "Erro ao atualizar status" });
      }
    }
  );

