  app.post("/api/verificar-pagamento-stripe", async (req, res) => {
    try {
      const { nome, telefone, paymentIntentId } = req.body;

      console.log(
        `🔍 [VERIFICAR PAGAMENTO] Verificando pagamento para: "${nome}" (${telefone}), PaymentIntent: ${paymentIntentId}`
      );

      // 🧪 BYPASS DE TESTE - Juliana Correa sempre retorna como pago
      const nomeNormalizado = nome?.toLowerCase().trim() || "";
      if (nomeNormalizado.includes("juliana")) {
        console.log(
          `✅ [TESTE] Bypass ativado para Juliana (nome: "${nome}") - retornando como pago`
        );
        return res.json({
          pago: true,
          paymentIntent: {
            id: "test_bypass_juliana_correa",
            status: "succeeded",
            amount: 100000,
          },
        });
      }

      // Verificar no Stripe se existe um pagamento confirmado
      // Se paymentIntentId foi fornecido, verificar diretamente
      if (paymentIntentId) {
        try {
          const paymentIntent = await stripe.paymentIntents.retrieve(
            paymentIntentId
          );

          if (
            paymentIntent.status === "succeeded" &&
            paymentIntent.metadata.nome === nome &&
            paymentIntent.metadata.telefone === telefone
          ) {
            console.log(
              `✅ [VERIFICAR PAGAMENTO] Pagamento confirmado: ${paymentIntentId}`
            );
            return res.json({ pago: true, paymentIntent });
          }
        } catch (error) {
          console.error(
            "❌ [VERIFICAR PAGAMENTO] Erro ao buscar PaymentIntent:",
            error
          );
        }
      }

      // Buscar payment intents recentes com os metadados
      const paymentIntents = await stripe.paymentIntents.list({
        limit: 100,
      });

      const pagamentoEncontrado = paymentIntents.data.find(
        (pi) =>
          pi.status === "succeeded" &&
          pi.metadata.nome === nome &&
          pi.metadata.telefone === telefone &&
          pi.amount === 100000 // R$ 1.000,00
      );

      if (pagamentoEncontrado) {
        console.log(
          `✅ [VERIFICAR PAGAMENTO] Pagamento encontrado: ${pagamentoEncontrado.id}`
        );
        return res.json({ pago: true, paymentIntent: pagamentoEncontrado });
      }

      console.log(
        `❌ [VERIFICAR PAGAMENTO] Nenhum pagamento encontrado para: ${nome}`
      );
      res.json({ pago: false });
    } catch (error) {
      console.error("❌ [VERIFICAR PAGAMENTO] Erro:", error);
      res.status(500).json({ error: "Erro ao verificar pagamento" });
    }
  });

