  // GET /api/mkt/active-campaign - Pegar campanha ativa com TODOS os links
  app.get("/api/mkt/active-campaign", async (req, res) => {
    try {
      // Buscar campanha ativa mais recente
      const campaigns = await storage.getMarketingCampaigns({ isActive: true });

      if (campaigns.length === 0) {
        return res.json({ campaign: null, links: [] });
      }

      const activeCampaign = campaigns[0];

      // Buscar APENAS links de usuários que já pagaram pelo menos uma vez
      // FIX: Usar subquery para evitar duplicatas quando usuário tem múltiplas doações

      // Pegar IDs únicos de usuários que pagaram
      const paidUserIds = await db
        .selectDistinct({ userId: doadores.userId })
        .from(doadores)
        .where(eq(doadores.status, "paid"));

      const paidIds = paidUserIds
        .map((row) => row.userId)
        .filter((id) => id !== null);

      // Buscar links apenas desses usuários (sem duplicatas)
      const linksData = await db
        .select({
          id: marketingLinks.id,
          campaignId: marketingLinks.campaignId,
          code: marketingLinks.code,
          medium: marketingLinks.medium,
          source: marketingLinks.source,
          utmSource: marketingLinks.utmSource,
          utmMedium: marketingLinks.utmMedium,
          utmCampaign: marketingLinks.utmCampaign,
          isActive: marketingLinks.isActive,
          rewardToUserId: marketingLinks.rewardToUserId,
          createdAt: marketingLinks.createdAt,
        })
        .from(marketingLinks)
        .where(
          and(
            eq(marketingLinks.campaignId, activeCampaign.id),
            or(
              inArray(marketingLinks.rewardToUserId, paidIds),
              eq(marketingLinks.source, "manual"),
              eq(marketingLinks.source, "doador")
            )
          )
        )
        .orderBy(desc(marketingLinks.createdAt));

      // Enriquecer com dados do dono e estatísticas
      const linksWithDetails = await Promise.all(
        linksData.map(async (link) => {
          let ownerName = "Sistema";
          let ownerPhone = null;

          if (link.rewardToUserId) {
            const user = await storage.getUser(link.rewardToUserId);
            if (user) {
              ownerName = user.nome || `Usuário #${user.id}`;
              ownerPhone = user.telefone || null;
            }
          }

          const stats = await storage.getMarketingLinkStats(link.id);

          return {
            ...link,
            ownerName,
            ownerPhone,
            stats,
          };
        })
      );

      res.json({
        campaign: activeCampaign,
        links: linksWithDetails,
      });
    } catch (error) {
      console.error("❌ [MKT-ACTIVE-CAMPAIGN] Erro:", error);
      res.status(500).json({ error: "Erro ao buscar campanha ativa" });
    }
  });
