  // Função para criar eventos
  async function createEvent(data: {
    eventName: string;
    userId: number;
    source: string;
    payload?: Record<string, any>;
    idempotencyKey?: string;
  }): Promise<GritoEvent | null> {
    try {
      const eventData: InsertGritoEvent = {
        eventName: data.eventName,
        userId: data.userId,
        source: data.source,
        payload: data.payload || {},
        idempotencyKey: data.idempotencyKey,
      };

      const [event] = await db
        .insert(gritoEvents)
        .values(eventData)
        .returning();

      console.log(
        `🎯 [EVENT CREATED] ${data.eventName} for user ${data.userId} from ${data.source}`
      );

      // Enfileirar webhooks
      await enqueueWebhooks(event);

      // Processar automações
      await processAutomations(event);

      return event;
    } catch (error: any) {
      if (
        error.code === "23505" &&
        error.constraint?.includes("idempotency_key")
      ) {
        console.log(
          `🔄 [EVENT DUPLICATE] Evento ignorado por idempotência: ${data.idempotencyKey}`
        );
        return null;
      }
      throw error;
    }
  }

  // Função para enfileirar webhooks
  async function enqueueWebhooks(event: GritoEvent): Promise<void> {
    const subscriptions = await db
      .select()
      .from(gritoWebhookSubscriptions)
      .where(
        and(
          eq(gritoWebhookSubscriptions.isActive, true),
          sql`${gritoWebhookSubscriptions.eventFilter} @> ARRAY[${event.eventName}]::text[]`
        )
      );

    for (const subscription of subscriptions) {
      await db.insert(gritoWebhookDeliveries).values({
        eventId: event.id,
        subscriptionId: subscription.id,
        status: "PENDING",
        nextAttemptAt: new Date(),
      });

      console.log(
        `📤 [WEBHOOK QUEUED] ${event.eventName} → ${subscription.destinationName}`
      );
    }
  }

  // Função para processar automações
  async function processAutomations(event: GritoEvent): Promise<void> {
    const automations = await db
      .select()
      .from(gritoAutomations)
      .where(
        and(
          eq(gritoAutomations.matchEvent, event.eventName),
          eq(gritoAutomations.isActive, true)
        )
      );

    for (const automation of automations) {
      try {
        // Verificar condição SQL se especificada
        if (automation.conditionSql) {
          const conditionQuery = automation.conditionSql.replace(
            /\{\{payload\.(\w+)\}\}/g,
            (_, key) => {
              const value = (event.payload as any)?.[key];
              return typeof value === "string" ? `'${value}'` : String(value);
            }
          );

          const conditionResult = await db.execute(
            sql.raw(`SELECT EXISTS(${conditionQuery}) as meets_condition`)
          );
          if (!(conditionResult.rows[0] as any)?.meets_condition) {
            console.log(
              `⏭️ [AUTOMATION SKIP] ${automation.name}: condição não atendida`
            );
            continue;
          }
        }

        // Executar ação
        if (automation.action.type === "email") {
          const to = automation.action.to?.replace(
            /\{\{payload\.(\w+)\}\}/g,
            (_, key) => {
              return (event.payload as any)?.[key] || "";
            }
          );

          const variables = { ...automation.action.variables };
          for (const [key, value] of Object.entries(variables)) {
            variables[key] = value.replace(
              /\{\{payload\.(\w+)\}\}/g,
              (_, payloadKey) => {
                return (event.payload as any)?.[payloadKey] || "";
              }
            );
          }

          await emailService.send(
            automation.action.template_id!,
            to!,
            variables
          );
          console.log(
            `📧 [AUTOMATION EMAIL] ${automation.name} enviado para ${to}`
          );
        } else if (automation.action.type === "webhook") {
          const subscription = await db
            .select()
            .from(gritoWebhookSubscriptions)
            .where(
              eq(
                gritoWebhookSubscriptions.destinationName,
                automation.action.endpoint_ref!
              )
            )
            .limit(1);

          if (subscription[0]) {
            await db.insert(gritoWebhookDeliveries).values({
              eventId: event.id,
              subscriptionId: subscription[0].id,
              status: "PENDING",
              nextAttemptAt: new Date(),
            });
            console.log(
              `🔗 [AUTOMATION WEBHOOK] ${automation.name} → ${automation.action.endpoint_ref}`
            );
          }
        }
      } catch (error) {
        console.error(`❌ [AUTOMATION ERROR] ${automation.name}:`, error);
      }
    }
  }

  // =========  POST /events  =========
  app.post("/events", async (req, res) => {
    try {
      // Verificar API key
      const apiKey = req.headers["x-api-key"];
      if (!apiKey || apiKey !== process.env.EVENTS_API_KEY) {
        return res.status(401).json({ error: "Invalid API key" });
      }

      const { event_name, user_id, source, payload, idempotency_key } =
        req.body;

      // Validar campos obrigatórios
      if (!event_name || !user_id || !source) {
        return res.status(400).json({
          error: "Missing required fields: event_name, user_id, source",
        });
      }

      const event = await createEvent({
        eventName: event_name,
        userId: user_id,
        source: source,
        payload: payload || {},
        idempotencyKey: idempotency_key,
      });

      if (!event) {
        return res.json({
          ok: true,
          id: null,
          message: "Event already processed",
        });
      }

      res.json({ ok: true, id: event.id });
    } catch (error: any) {
      console.error("❌ [EVENTS API] Error:", error);
      res.status(500).json({ error: "Internal server error" });
    }
  });

