  app.post(
    "/api/admin/beneficios/ganhadores",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        const { beneficioId, userId, depoimento } = req.body;

        if (!beneficioId || !userId) {
          return res.status(400).json({
            success: false,
            message: "beneficioId e userId são obrigatórios",
          });
        }

        // Buscar lances do usuário neste benefício
        const lancesUsuario = await db
          .select()
          .from(beneficioLances)
          .where(
            and(
              eq(beneficioLances.beneficioId, beneficioId),
              eq(beneficioLances.userId, userId)
            )
          );

        const lancesTotais = lancesUsuario.length;
        const gritosTotais = lancesUsuario.reduce(
          (acc, l) => acc + (l.pontosOfertados || 0),
          0
        );

        // Inserir ganhador
        const [novoGanhador] = await db
          .insert(beneficioGanhadores)
          .values({
            beneficioId,
            userId,
            lancesTotais,
            gritosTotais,
            depoimento: depoimento || null,
            visivel: true,
            dataGanhou: new Date(),
          })
          .returning();

      // Atualizar status dos lances para 'ganho'
      await db.update(beneficioLances)
        .set({ status: 'ganho', dataResultado: new Date() })
        .where(and(
          eq(beneficioLances.beneficioId, beneficioId),
          eq(beneficioLances.userId, userId)
        ));

        console.log(
          "✅ [GANHADORES] Novo ganhador registrado: user " +
            userId +
            " - benefício " +
            beneficioId
        );
        res.json({ success: true, ganhador: novoGanhador });
      } catch (error: any) {
        console.error("Erro ao criar ganhador:", error);
        res
          .status(500)
          .json({ success: false, message: "Erro ao criar ganhador" });
      }
    }
  );

